import re

_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_IDENT_RE = re.compile(r"^[0-9A-Za-z-]+$")


def _parse_prerelease(prerelease: str):
    idents = []
    for ident in prerelease.split("."):
        if not _IDENT_RE.match(ident):
            raise ValueError(f"invalid prerelease identifier: {ident!r}")
        if ident.isdigit():
            if len(ident) > 1 and ident[0] == "0":
                raise ValueError(f"numeric prerelease identifier with leading zero: {ident!r}")
            idents.append((0, int(ident)))
        else:
            idents.append((1, ident))
    return tuple(idents)


def _parse_build(build: str):
    for ident in build.split("."):
        if not _IDENT_RE.match(ident):
            raise ValueError(f"invalid build identifier: {ident!r}")


def _key(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"invalid version: {version!r}")
    major, minor, patch, prerelease, build = m.groups()
    if build is not None:
        _parse_build(build)
    pre = _parse_prerelease(prerelease) if prerelease is not None else None
    # No prerelease sorts after any prerelease: use (1,) vs (0, idents)
    pre_key = (1,) if pre is None else (0, pre)
    return (int(major), int(minor), int(patch), pre_key)


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=_key)

import re

_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-((?:0|[1-9][0-9]*|[0-9A-Za-z-]+)(?:\.(?:0|[1-9][0-9]*|[0-9A-Za-z-]+))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_IDENT_RE = re.compile(r"^[0-9A-Za-z-]+$")


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = m.group(4)
    build = m.group(5)

    pre_ids = None
    if pre is not None:
        pre_ids = []
        for ident in pre.split("."):
            if not _IDENT_RE.match(ident):
                raise ValueError(f"Invalid version: {version!r}")
            if ident.isdigit():
                if len(ident) > 1 and ident[0] == "0":
                    raise ValueError(f"Invalid version: {version!r}")
                pre_ids.append((0, int(ident), ""))
            else:
                pre_ids.append((1, 0, ident))

    if build is not None:
        for ident in build.split("."):
            if not _IDENT_RE.match(ident):
                raise ValueError(f"Invalid version: {version!r}")

    return major, minor, patch, pre_ids


def _key(version: str):
    major, minor, patch, pre_ids = _parse(version)
    if pre_ids is None:
        # release sorts after any pre-release of same core
        return (major, minor, patch, 1, [])
    return (major, minor, patch, 0, pre_ids)


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=_key)

import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


def _key(v: str):
    m = _VERSION_RE.match(v)
    if not m:
        raise ValueError(f"invalid version: {v!r}")
    major, minor, patch, pre, build = m.groups()
    core = (int(major), int(minor), int(patch))
    if pre is None:
        pre_key = (1,)
    else:
        ids = pre.split(".")
        pre_key = (0, tuple(
            (0, int(x)) if x.isdigit() else (1, x) for x in ids
        ) + ((-1,),))  # sentinel so fewer identifiers sorts lower
    return core + pre_key


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=_key)

