import re

_CORE = r"(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
_ID = r"[0-9A-Za-z-]+"
_NUMID = r"0|[1-9]\d*"
_PRERELEASE = rf"{_NUMID}(?:\.{_NUMID})*(?:\.{_ID}(?:\.{_ID})*)|{_ID}(?:\.{_ID})*"
_PATTERN = re.compile(
    rf"^{_CORE}(?:-({_PRERELEASE}))?(?:\+{_ID}(?:\.{_ID})*)?$"
)


def _parse_prerelease(pre: str):
    ids = pre.split(".")
    key = []
    for ident in ids:
        if ident.isdigit():
            key.append((0, int(ident), ""))
        else:
            key.append((1, 0, ident))
    return tuple(key)


def sort_versions(versions: list[str]) -> list[str]:
    parsed = []
    for v in versions:
        m = _PATTERN.match(v)
        if not m:
            raise ValueError(f"invalid version: {v!r}")
        major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
        pre = m.group(4)
        pre_key = _parse_prerelease(pre) if pre is not None else None
        parsed.append(((major, minor, patch), pre_key, v))
    # No prerelease sorts after any prerelease: use (0, pre_key) vs (1,)
    def key(item):
        core, pre_key, _ = item
        if pre_key is None:
            pre_sort = (1,)
        else:
            pre_sort = (0, pre_key)
        return (core, pre_sort)
    parsed.sort(key=key)
    return [v for _, _, v in parsed]

import re

_VERSION_RE = re.compile(
    r'^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)'
    r'(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)

def _parse_prerelease(s):
    ids = s.split('.')
    key = []
    for ident in ids:
        if ident.isdigit():
            if len(ident) > 1 and ident[0] == '0':
                raise ValueError(f"invalid prerelease identifier: {ident}")
            key.append((0, int(ident), ''))
        else:
            key.append((1, 0, ident))
    return key

def sort_versions(versions):
    parsed = []
    for i, v in enumerate(versions):
        m = _VERSION_RE.match(v)
        if not m:
            raise ValueError(f"invalid version: {v}")
        major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
        pre = _parse_prerelease(m.group(4)) if m.group(4) else None
        parsed.append(((major, minor, patch), pre, i, v))
    def key(item):
        core, pre, i, _ = item
        if pre is None:
            return (core, 1, [])
        return (core, 0, pre)
    parsed.sort(key=lambda item: (key(item), item[2]))
    return [item[3] for item in parsed]

