import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_IDENT_RE = re.compile(r"^[0-9A-Za-z-]+$")


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = m.group(4)
    build = m.group(5)

    pre_key = None
    if pre is not None:
        idents = pre.split(".")
        for ident in idents:
            if not _IDENT_RE.match(ident):
                raise ValueError(f"Invalid version: {version!r}")
            if ident.isdigit():
                if len(ident) > 1 and ident[0] == "0":
                    raise ValueError(f"Invalid version: {version!r}")
        pre_key = tuple(
            (0, int(i)) if i.isdigit() else (1, i) for i in idents
        )
    if build is not None:
        for ident in build.split("."):
            if not _IDENT_RE.match(ident):
                raise ValueError(f"Invalid version: {version!r}")

    return major, minor, patch, pre_key


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [(v, _parse(v)) for v in versions]

    def key(item):
        v, (major, minor, patch, pre_key) = item
        # No prerelease sorts after any prerelease: use (1,) vs (0, ...)
        if pre_key is None:
            pre_sort = (1,)
        else:
            pre_sort = (0, pre_key)
        return (major, minor, patch, pre_sort)

    parsed.sort(key=key)
    return [v for v, _ in parsed]

import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major, minor, patch, pre, build = m.groups()
    core = (int(major), int(minor), int(patch))
    if pre is None:
        pre_key = None
    else:
        pre_key = tuple(
            (0, int(x)) if x.isdigit() else (1, x)
            for x in pre.split(".")
        )
    return core, pre_key, build


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [_parse(v) for v in versions]

    def key(item):
        core, pre, _ = item
        # No prerelease sorts after any prerelease: use flag 1 vs 0,
        # and empty tuple for prerelease-less so comparisons stay valid.
        if pre is None:
            return (core, 1, ())
        return (core, 0, pre)

    # stable sort keeps input order for equal precedence (build ignored)
    return [v for v, _ in sorted(zip(versions, parsed), key=lambda p: key(p[1]))]

import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid semantic version: {version!r}")
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = m.group(4)
    pre_ids = pre.split(".") if pre else []
    return major, minor, patch, pre_ids


def _pre_key(pre_ids):
    key = []
    for ident in pre_ids:
        if ident.isdigit():
            key.append((0, int(ident), ""))
        else:
            key.append((1, 0, ident))
    return key


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [_parse(v) for v in versions]
    indexed = list(range(len(versions)))

    def key(i: int):
        major, minor, patch, pre_ids = parsed[i]
        # Pre-release sorts before release: use 0 for pre, 1 for release.
        pre_flag = 0 if pre_ids else 1
        return (major, minor, patch, pre_flag, _pre_key(pre_ids), len(pre_ids))

    indexed.sort(key=key)
    return [versions[i] for i in indexed]

import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|[0-9A-Za-z-]+)(?:\.(?:0|[1-9]\d*|[0-9A-Za-z-]+))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_IDENT_RE = re.compile(r"^[0-9A-Za-z-]+$")


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch, pre, build = m.groups()
    if pre is not None:
        for ident in pre.split("."):
            if not _IDENT_RE.match(ident):
                raise ValueError(f"Invalid version: {version!r}")
            if ident.isdigit() and len(ident) > 1 and ident[0] == "0":
                raise ValueError(f"Invalid version: {version!r}")
    if build is not None:
        for ident in build.split("."):
            if not _IDENT_RE.match(ident):
                raise ValueError(f"Invalid version: {version!r}")
    pre_key = (
        tuple(
            (0, int(i), "") if i.isdigit() else (1, 0, i)
            for i in pre.split(".")
        ),
        len(pre.split(".")),
    ) if pre is not None else None
    return (int(major), int(minor), int(patch)), pre_key


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [_parse(v) for v in versions]
    # stable sort: None (no prerelease) sorts after any prerelease
    def key(item):
        core, pre_key = item
        if pre_key is None:
            return (core, 1, ())
        return (core, 0, pre_key[0])
    indexed = sorted(range(len(versions)), key=lambda i: (key(parsed[i]), i))
    return [versions[i] for i in indexed]

import re

_VERSION_RE = re.compile(
    r'^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)'
    r'(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?'
    r'(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$'
)


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = m.group(4)
    pre_ids = pre.split('.') if pre else []
    return (major, minor, patch), pre_ids


def _pre_key(pre_ids):
    key = []
    for ident in pre_ids:
        if ident.isdigit():
            key.append((0, int(ident), ''))
        else:
            key.append((1, 0, ident))
    return key


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [_parse(v) for v in versions]
    indexed = list(range(len(versions)))

    def key(i):
        core, pre_ids = parsed[i]
        # stable sort: include index so equal-precedence keep input order
        return (core, 0 if pre_ids else 1, _pre_key(pre_ids), len(pre_ids), i)

    indexed.sort(key=key)
    return [versions[i] for i in indexed]

import re

_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)

_IDENT_RE = re.compile(r"^[0-9A-Za-z-]+$")


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = m.group(4)
    build = m.group(5)
    pre_ids = pre.split(".") if pre else []
    for ident in pre_ids:
        if ident.isdigit():
            if len(ident) > 1 and ident[0] == "0":
                raise ValueError(f"Invalid version: {version!r}")
        elif not _IDENT_RE.match(ident):
            raise ValueError(f"Invalid version: {version!r}")
    if build:
        for ident in build.split("."):
            if not _IDENT_RE.match(ident):
                raise ValueError(f"Invalid version: {version!r}")
    key_pre = tuple(
        (0, int(i), "") if i.isdigit() else (1, 0, i) for i in pre_ids
    )
    return (major, minor, patch, 0 if pre else 1, key_pre)


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=_parse)

import re

_VERSION_RE = re.compile(
    r"^(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
    r"(?:-((?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*)(?:\.(?:0|[1-9]\d*|\d*[A-Za-z-][0-9A-Za-z-]*))*))?"
    r"(?:\+([0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*))?$"
)


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    pre = m.group(4)
    pre_ids = pre.split(".") if pre else []
    key = (major, minor, patch)
    if not pre_ids:
        # release sorts after any prerelease of same core
        return (key, 1, ())
    ids = tuple((0, int(i), "") if i.isdigit() else (1, 0, i) for i in pre_ids)
    return (key, 0, ids)


def sort_versions(versions: list[str]) -> list[str]:
    return sorted(versions, key=_parse)

