import re

_CORE = r"(0|[1-9]\d*)\.(0|[1-9]\d*)\.(0|[1-9]\d*)"
_IDENT = r"[0-9A-Za-z-]+"
_NUMID = r"0|[1-9]\d*"
_PRE = rf"(?:-({_IDENT}(?:\.{_IDENT})*))?"
_BUILD = rf"(?:\+{_IDENT}(?:\.{_IDENT})*)?"
_RE = re.compile(rf"^{_CORE}{_PRE}{_BUILD}$")


def _parse_prerelease(s):
    ids = s.split(".")
    out = []
    for i in ids:
        if re.fullmatch(_NUMID, i):
            out.append((0, int(i)))
        else:
            out.append((1, i))
    return out


def sort_versions(versions):
    parsed = []
    for idx, v in enumerate(versions):
        m = _RE.match(v)
        if not m:
            raise ValueError(f"invalid version: {v!r}")
        core = tuple(int(m.group(i)) for i in (1, 2, 3))
        pre = _parse_prerelease(m.group(4)) if m.group(4) else None
        parsed.append((core, pre, idx, v))

    def key(item):
        core, pre, idx, _ = item
        if pre is None:
            return (core, 1, [], idx)
        return (core, 0, pre, idx)

    parsed.sort(key=key)
    return [p[3] for p in parsed]

