)

_IDENT_RE = re.compile(r"^[0-9A-Za-z-]+$")


def _parse(version: str):
    m = _VERSION_RE.match(version)
    if not m:
        raise ValueError(f"Invalid version: {version!r}")
    major, minor, patch = int(m.group(1)), int(m.group(2)), int(m.group(3))
    prerelease = m.group(4)
    build = m.group(5)
    if prerelease:
        for ident in prerelease.split("."):
            if not _IDENT_RE.match(ident):
                raise ValueError(f"Invalid version: {version!r}")
            if ident.isdigit() and len(ident) > 1 and ident[0] == "0":
                raise ValueError(f"Invalid version: {version!r}")
    if build:
        for ident in build.split("."):
            if not _IDENT_RE.match(ident):
                raise ValueError(f"Invalid version: {version!r}")
    key_pre = []
    if prerelease:
        for ident in prerelease.split("."):
            if ident.isdigit():
                key_pre.append((0, int(ident), ""))
            else:
                key_pre.append((1, 0, ident))
    # No prerelease -> higher precedence: use a flag that sorts after any prerelease key
    return (major, minor, patch), (1, []) if not prerelease else (0, key_pre)


def sort_versions(versions: list[str]) -> list[str]:
    parsed = [_parse(v) for v in versions]
    indexed = sorted(range(len(versions)), key=lambda i: (*parsed[i][0], *parsed[i][1], i))
    # Need stable sort with tuple key: (major, minor, patch, pre_flag, pre_idents)
    keyed = [(parsed[i][0], parsed[i][1], i) for i in range(len(versions))]
    order = sorted(range(len(versions)), key=lambda i: keyed[i])
    return [versions[i] for i in order]

