from functools import lru_cache


def _parse_class(p, i):
    """Parse a bracket class starting at p[i] == '['.
    Returns (items, negated, end_index) or None if unclosed."""
    n = len(p)
    pos = i + 1
    neg = False
    if pos < n and p[pos] == '!':
        neg = True
        pos += 1
    first = True
    items = []
    while pos < n:
        if p[pos] == ']' and not first:
            return items, neg, pos + 1
        if p[pos] == ']' and first:
            items.append(']')
            pos += 1
            first = False
            continue
        if pos + 2 < n and p[pos + 1] == '-' and p[pos + 2] != ']':
            items.append((p[pos], p[pos + 2]))
            pos += 3
        else:
            items.append(p[pos])
            pos += 1
        first = False
    return None


def _validate(p):
    i = 0
    n = len(p)
    while i < n:
        c = p[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with unpaired backslash")
            i += 2
        elif c == '[':
            r = _parse_class(p, i)
            i = r[2] if r is not None else i + 1
        else:
            i += 1


def _seg_match(p, s):
    """Match a single pattern segment against a single path segment."""
    n, m = len(p), len(s)

    @lru_cache(maxsize=None)
    def f(i, j):
        if i == n:
            return j == m
        c = p[i]
        if c == '\\':
            return j < m and s[j] == p[i + 1] and f(i + 2, j + 1)
        if c == '?':
            return j < m and f(i + 1, j + 1)
        if c == '*':
            return any(f(i + 1, k) for k in range(j, m + 1))
        if c == '[':
            r = _parse_class(p, i)
            if r is None:
                return j < m and s[j] == '[' and f(i + 1, j + 1)
            items, neg, end = r
            if j >= m:
                return False
            ch = s[j]
            hit = False
            for it in items:
                if isinstance(it, tuple):
                    if it[0] <= ch <= it[1]:
                        hit = True
                        break
                elif ch == it:
                    hit = True
                    break
            if hit == neg:
                return False
            return f(end, j + 1)
        return j < m and s[j] == c and f(i + 1, j + 1)

    return f(0, 0)


def glob_match(pattern: str, path: str) -> bool:
    _validate(pattern)
    P = pattern.split('/')
    S = path.split('/')

    @lru_cache(maxsize=None)
    def lm(pi, si):
        if pi == len(P):
            return si == len(S)
        if P[pi] == '**':
            return any(lm(pi + 1, k) for k in range(si, len(S) + 1))
        return si < len(S) and _seg_match(P[pi], S[si]) and lm(pi + 1, si + 1)

    return lm(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    """Report whether a slash-separated path matches a glob pattern."""

    # ---------- parsing ----------
    def parse_set(pat, i):
        """Parse a bracket set starting at pat[i] == '['.
        Returns ((SET token), next_index) or None if unclosed."""
        n = len(pat)
        j = i + 1
        neg = False
        if j < n and pat[j] == '!':
            neg = True
            j += 1
        chars = set()
        first = True
        last = None  # last plain char added (for ranges)
        while True:
            if j >= n:
                return None  # unclosed '[' -> literal
            c = pat[j]
            if c == ']' and not first:
                j += 1
                break
            if c == '-' and not first and last is not None \
                    and j + 1 < n and pat[j + 1] != ']':
                # range
                hi = pat[j + 1]
                lo, hi_o = ord(last), ord(hi)
                if lo <= hi_o:
                    for o in range(lo, hi_o + 1):
                        chars.add(chr(o))
                last = hi
                j += 2
                first = False
                continue
            # literal char (includes ']' right after '[' or '[!', and
            # '-' that is first or last in the set)
            chars.add(c)
            last = c
            j += 1
            first = False
        return ('SET', neg, frozenset(chars)), j

    def parse(pat):
        """Parse pattern into a list of segments. Each segment is either
        the string 'GS' (a ** whole-segment globstar) or a list of tokens.
        Tokens: ('L', ch), ('ANY',), ('STAR',), ('SET', neg, chars)."""
        n = len(pat)
        segs = []
        cur = []
        i = 0
        while i < n:
            c = pat[i]
            if c == '\\':
                if i + 1 >= n:
                    raise ValueError("pattern ends with an unpaired backslash")
                cur.append(('L', pat[i + 1]))
                i += 2
            elif c == '[':
                res = parse_set(pat, i)
                if res is None:
                    cur.append(('L', '['))
                    i += 1
                else:
                    tok, i = res
                    cur.append(tok)
            elif c == '*':
                # both '*' and '**' parse as stars; globstar is decided
                # at the segment level below
                cur.append(('STAR',))
                i += 1
            elif c == '?':
                cur.append(('ANY',))
                i += 1
            elif c == '/':
                segs.append(cur)
                cur = []
                i += 1
            else:
                cur.append(('L', c))
                i += 1
        segs.append(cur)
        out = []
        for seg in segs:
            if len(seg) == 2 and seg[0] == ('STAR',) and seg[1] == ('STAR',):
                out.append('GS')
            else:
                out.append(seg)
        return out

    # ---------- segment matching (no '/' involved) ----------
    def segmatch(toks, s):
        n = len(toks)
        pos = {0}
        for ch in s:
            new = set()
            for p in pos:
                t = toks[p]
                k = t[0]
                if k == 'L':
                    if t[1] == ch:
                        new.add(p + 1)
                elif k == 'ANY':
                    new.add(p + 1)
                elif k == 'SET':
                    neg, cs = t[1], t[2]
                    if (ch in cs) != neg:
                        new.add(p + 1)
                else:  # STAR
                    new.add(p)      # star matches empty here
                    new.add(p + 1)  # star consumes this char
            pos = new
            if not pos:
                return False
        # collapse trailing stars (they can match the empty string)
        changed = True
        while changed:
            changed = False
            for p in list(pos):
                if p < n and toks[p][0] == 'STAR' and (p + 1) not in pos:
                    pos.add(p + 1)
                    changed = True
        return n in pos

    # ---------- whole-path matching ----------
    segs = parse(pattern)
    parts = path.split('/')
    ns, np = len(segs), len(parts)
    memo = {}

    def m(si, pi):
        if si == ns:
            return pi == np
        key = (si, pi)
        if key in memo:
            return memo[key]
        seg = segs[si]
        if seg == 'GS':
            result = any(m(si + 1, k) for k in range(pi, np + 1))
        else:
            if pi >= np:
                result = False
            else:
                result = segmatch(seg, parts[pi]) and m(si + 1, pi + 1)
        memo[key] = result
        return result

    return m(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Tokenize pattern into segments
    def tokenize(seg):
        tokens = []
        i = 0
        n = len(seg)
        while i < n:
            c = seg[i]
            if c == '\\':
                if i + 1 >= n:
                    raise ValueError("pattern ends with unpaired backslash")
                tokens.append(('lit', seg[i + 1]))
                i += 2
            elif c == '?':
                tokens.append(('any',))
                i += 1
            elif c == '*':
                # count consecutive stars
                j = i
                while j < n and seg[j] == '*':
                    j += 1
                if j - i >= 2:
                    tokens.append(('star',))  # ** not whole segment behaves like *
                else:
                    tokens.append(('star',))
                i = j
            elif c == '[':
                j = i + 1
                neg = False
                if j < n and seg[j] == '!':
                    neg = True
                    j += 1
                items = []
                first = True
                closed = False
                k = j
                while k < n:
                    if seg[k] == ']' and not first:
                        closed = True
                        break
                    first = False
                    if k + 2 < n and seg[k + 1] == '-' and seg[k + 2] != ']':
                        items.append((seg[k], seg[k + 2]))
                        k += 3
                    else:
                        items.append((seg[k], seg[k]))
                        k += 1
                if not closed:
                    tokens.append(('lit', '['))
                    i += 1
                else:
                    tokens.append(('class', neg, items))
                    i = k + 1
            else:
                tokens.append(('lit', c))
                i += 1
        return tokens

    def match_seg(tokens, s):
        # DP over tokens and string chars
        m = len(tokens)
        n = len(s)
        # dp[i][j]: tokens[i:] matches s[j:]
        dp = [[False] * (n + 1) for _ in range(m + 1)]
        dp[m][n] = True
        for i in range(m - 1, -1, -1):
            for j in range(n, -1, -1):
                t = tokens[i]
                if t[0] == 'star':
                    dp[i][j] = dp[i + 1][j] or (j < n and dp[i][j + 1])
                elif t[0] == 'any':
                    dp[i][j] = j < n and s[j] != '/' and dp[i + 1][j + 1]
                elif t[0] == 'lit':
                    dp[i][j] = j < n and s[j] == t[1] and dp[i + 1][j + 1]
                else:  # class
                    neg, items = t[1], t[2]
                    ok = False
                    if j < n and s[j] != '/':
                        in_set = any(lo <= s[j] <= hi for lo, hi in items)
                        ok = (not neg and in_set) or (neg and not in_set)
                    dp[i][j] = ok and dp[i + 1][j + 1]
        return dp[0][0]

    psegs = pattern.split('/')
    usegs = path.split('/')

    # Pre-tokenize; mark ** segments
    ptoks = []
    for seg in psegs:
        if seg == '**':
            ptoks.append(None)  # ** segment
        else:
            ptoks.append(tokenize(seg))

    # Segment-level DP: dp[i][j] = ptoks[i:] matches usegs[j:]
    m, n = len(ptoks), len(usegs)
    dp = [[False] * (n + 1) for _ in range(m + 1)]
    dp[m][n] = True
    for i in range(m - 1, -1, -1):
        for j in range(n, -1, -1):
            if ptoks[i] is None:
                dp[i][j] = dp[i + 1][j] or (dp[i][j + 1])
            else:
                dp[i][j] = match_seg(ptoks[i], usegs[j]) and dp[i + 1][j + 1]
    return dp[0][0]

def glob_match(pattern: str, path: str) -> bool:
    # Validate trailing backslash
    n = len(pattern)
    i = n
    while i > 0 and pattern[i - 1] == '\\':
        i -= 1
    if (n - i) % 2 == 1:
        raise ValueError("pattern ends with an unpaired backslash")

    memo_seg = {}

    def seg_match(pat: str, s: str) -> bool:
        """Match a single-segment pattern (no unescaped '/') against a path segment."""
        key = (pat, s)
        if key in memo_seg:
            return memo_seg[key]

        # Pre-parse pattern into tokens for efficiency
        tokens = []  # list of ('lit', ch) | ('any',) | ('star',) | ('set', neg, frozenset, ranges)
        i = 0
        L = len(pat)
        while i < L:
            c = pat[i]
            if c == '\\':
                tokens.append(('lit', pat[i + 1]))
                i += 2
            elif c == '?':
                tokens.append(('any',))
                i += 1
            elif c == '*':
                tokens.append(('star',))
                i += 1
            elif c == '[':
                parsed = _parse_bracket(pat, i)
                if parsed is None:
                    tokens.append(('lit', '['))
                    i += 1
                else:
                    neg, items, ranges, i = parsed
                    tokens.append(('set', neg, frozenset(items), ranges))
            else:
                tokens.append(('lit', c))
                i += 1

        T = len(tokens)
        ls = len(s)
        memo = {}

        def m(ti: int, j: int) -> bool:
            if ti == T:
                return j == ls
            key2 = (ti, j)
            if key2 in memo:
                return memo[key2]
            tok = tokens[ti]
            res = False
            if tok[0] == 'lit':
                res = j < ls and s[j] == tok[1] and m(ti + 1, j + 1)
            elif tok[0] == 'any':
                res = j < ls and s[j] != '/' and m(ti + 1, j + 1)
            elif tok[0] == 'star':
                # '*' cannot cross '/', but s is a single segment anyway
                k = j
                while True:
                    if m(ti + 1, k):
                        res = True
                        break
                    if k >= ls:
                        break
                    k += 1
            else:  # set
                _, neg, items, ranges = tok
                if j < ls and s[j] != '/':
                    ch = s[j]
                    inside = ch in items or any(lo <= ch <= hi for lo, hi in ranges)
                    if inside != neg:
                        res = m(ti + 1, j + 1)
            memo[key2] = res
            return res

        result = m(0, 0)
        memo_seg[key] = result
        return result

    def _parse_bracket(pat: str, i: int):
        """Parse bracket expression starting at pat[i] == '['.
        Returns (neg, items, ranges, next_index) or None if unclosed."""
        L = len(pat)
        pos = i + 1
        neg = False
        if pos < L and pat[pos] == '!':
            neg = True
            pos += 1
        items = set()
        ranges = []
        first = True
        # A ']' right after '[' or '[!' is a literal ']'
        if pos < L and pat[pos] == ']':
            items.add(']')
            pos += 1
            first = False
        while pos < L and pat[pos] != ']':
            if (not first and pos + 1 < L and pat[pos + 1] == '-'
                    and pos + 2 < L and pat[pos + 2] != ']'):
                lo, hi = pat[pos], pat[pos + 2]
                if lo <= hi:
                    ranges.append((lo, hi))
                else:
                    ranges.append((hi, lo))
                pos += 3
            else:
                items.add(pat[pos])
                pos += 1
                first = False
        if pos == L:
            return None  # unclosed '[': literal
        return (neg, items, ranges, pos + 1)

    memo_top = {}

    def match(pi: int, si: int) -> bool:
        key = (pi, si)
        if key in memo_top:
            return memo_top[key]
        if pi == n:
            res = si == len(path)
            memo_top[key] = res
            return res

        # Check for a special '**' whole segment
        if pattern[pi:pi + 2] == '**':
            prev_ok = pi == 0 or pattern[pi - 1] == '/'
            next_ok = pi + 2 == n or pattern[pi + 2] == '/'
            if prev_ok and next_ok:
                # Zero segments
                np = pi + 2
                if np < n:
                    np += 1  # skip '/'
                if match(np, si):
                    memo_top[key] = True
                    return True
                # Consume one path segment and stay at '**'
                k = path.find('/', si)
                if k != -1:
                    res = match(pi, k + 1)
                    memo_top[key] = res
                    return res
                memo_top[key] = False
                return False

        # Find end of current pattern segment (next unescaped '/')
        j = pi
        esc = False
        while j < n:
            if esc:
                esc = False
            elif pattern[j] == '\\':
                esc = True
            elif pattern[j] == '/':
                break
            j += 1
        seg_pat = pattern[pi:j]

        # Find end of current path segment
        k = path.find('/', si)
        if k == -1:
            k = len(path)
        seg = path[si:k]

        if seg_match(seg_pat, seg):
            if j == n:
                res = k == len(path)
            else:
                res = match(j + 1, k + 1)
            memo_top[key] = res
            return res
        memo_top[key] = False
        return False

    return match(0, 0)

from functools import lru_cache


def glob_match(pattern: str, path: str) -> bool:
    tokens = _tokenize(pattern)
    n, m = len(path), len(tokens)

    @lru_cache(maxsize=None)
    def match(ti: int, pi: int) -> bool:
        if ti == m:
            return pi == n
        tok = tokens[ti]
        kind = tok[0]
        if kind == "sep":
            return pi < n and path[pi] == "/" and match(ti + 1, pi + 1)
        if kind == "lit":
            return pi < n and path[pi] == tok[1] and match(ti + 1, pi + 1)
        if kind == "q":
            return pi < n and path[pi] != "/" and match(ti + 1, pi + 1)
        if kind == "cls":
            if pi >= n or path[pi] == "/":
                return False
            c = path[pi]
            inside = any(lo <= c <= hi for lo, hi in tok[2])
            if tok[1]:
                inside = not inside
            return inside and match(ti + 1, pi + 1)
        if kind == "star":
            k = pi
            while True:
                if match(ti + 1, k):
                    return True
                if k >= n or path[k] == "/":
                    return False
                k += 1
        # kind == "ds": '**' segment matches zero or more whole segments
        if match(ti + 1, pi):
            return True
        k = pi
        while k < n and path[k] != "/":
            k += 1
        if k < n and match(ti + 1, k + 1):
            return True
        return False

    return match(0, 0)


def _tokenize(pattern: str):
    tokens = []
    i = 0
    L = len(pattern)
    at_seg_start = True
    while i < L:
        c = pattern[i]
        if c == "\\":
            if i + 1 >= L:
                raise ValueError("pattern ends with an unpaired backslash")
            tokens.append(("lit", pattern[i + 1]))
            i += 2
            at_seg_start = False
        elif c == "*":
            if (
                at_seg_start
                and i + 1 < L
                and pattern[i + 1] == "*"
                and (i + 2 == L or pattern[i + 2] == "/")
            ):
                tokens.append(("ds",))
                i += 2
                continue  # still at segment start only if followed by '/'
                # (handled below: if next is '/', sep token resets flag)
            tokens.append(("star",))
            i += 1
            at_seg_start = False
        elif c == "?":
            tokens.append(("q",))
            i += 1
            at_seg_start = False
        elif c == "[":
            j = i + 1
            negated = False
            if j < L and pattern[j] == "!":
                negated = True
                j += 1
            items = []
            first = True
            closed = False
            while j < L:
                if pattern[j] == "]" and not first:
                    closed = True
                    j += 1
                    break
                ch = pattern[j]
                if (
                    j + 2 < L
                    and pattern[j + 1] == "-"
                    and pattern[j + 2] != "]"
                ):
                    items.append((ch, pattern[j + 2]))
                    j += 3
                else:
                    items.append((ch, ch))
                    j += 1
                first = False
            if closed:
                tokens.append(("cls", negated, items))
                i = j
            else:
                # Unclosed '[': literal '['
                tokens.append(("lit", "["))
                i += 1
            at_seg_start = False
        elif c == "/":
            tokens.append(("sep",))
            i += 1
            at_seg_start = True
        else:
            tokens.append(("lit", c))
            i += 1
            at_seg_start = False
        if tokens and tokens[-1][0] == "ds":
            # after a '**' segment, if next char is '/', next iteration emits
            # 'sep' and resets at_seg_start; otherwise we're no longer at start
            if i >= L or pattern[i] != "/":
                at_seg_start = False
    return tokens

def glob_match(pattern: str, path: str) -> bool:
    # --- tokenize pattern into segments ---
    tokens = []  # flat list of ('lit',c) ('any',) ('star',) ('cls',neg,ranges) ('seg',)
    i, n = 0, len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with unpaired backslash")
            tokens.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '[':
            j = i + 1
            neg = False
            if j < n and pattern[j] == '!':
                neg = True
                j += 1
            items = []
            start = j
            closed = False
            k = j
            while k < n:
                if pattern[k] == ']' and k > start:
                    closed = True
                    break
                if pattern[k] == ']' and k == start:
                    items.append(('lit', ']'))
                    k += 1
                    start = k
                    continue
                if k + 2 < n and pattern[k + 1] == '-' and pattern[k + 2] != ']':
                    items.append(('rng', pattern[k], pattern[k + 2]))
                    k += 3
                else:
                    items.append(('lit', pattern[k]))
                    k += 1
            if not closed:
                tokens.append(('lit', '['))
                i += 1
            else:
                tokens.append(('cls', neg, items))
                i = k + 1
        elif c == '?':
            tokens.append(('any',))
            i += 1
        elif c == '*':
            tokens.append(('star',))
            i += 1
        elif c == '/':
            tokens.append(('seg',))
            i += 1
        else:
            tokens.append(('lit', c))
            i += 1

    # split into segments; a segment that is exactly two stars -> GSTAR
    segments = [[]]
    for t in tokens:
        if t[0] == 'seg':
            segments.append([])
        else:
            segments[-1].append(t)
    segs = []
    for s in segments:
        if len(s) == 2 and s[0][0] == 'star' and s[1][0] == 'star':
            segs.append('GSTAR')
        else:
            segs.append(tuple(s))

    path_segs = path.split('/') if path else [''] if False else path.split('/')

    def match_seg(pat, s):
        # classic glob match within one segment (no '/' present)
        pi, si = 0, 0
        star = -1
        ss = 0
        lp, ls = len(pat), len(s)
        while si < ls:
            if pi < lp and (pat[pi][0] == 'any' or
                            (pat[pi][0] == 'lit' and pat[pi][1] == s[si]) or
                            (pat[pi][0] == 'cls' and cls_match(pat[pi], s[si]))):
                pi += 1
                si += 1
            elif pi < lp and pat[pi][0] == 'star':
                star = pi
                ss = si
                pi += 1
            elif star != -1:
                ss += 1
                si = ss
                pi = star + 1
            else:
                return False
        while pi < lp and pat[pi][0] == 'star':
            pi += 1
        return pi == lp

    def cls_match(tok, ch):
        _, neg, items = tok
        ok = False
        for it in items:
            if it[0] == 'lit':
                if ch == it[1]:
                    ok = True
                    break
            else:
                if it[1] <= ch <= it[2]:
                    ok = True
                    break
        return ok != neg

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(p_idx, s_idx):
        if p_idx == len(segs):
            return s_idx == len(path_segs)
        if segs[p_idx] == 'GSTAR':
            for k in range(s_idx, len(path_segs) + 1):
                if match(p_idx + 1, k):
                    return True
            return False
        if s_idx == len(path_segs):
            return False
        return match_seg(segs[p_idx], path_segs[s_idx]) and match(p_idx + 1, s_idx + 1)

    return match(0, 0)

from functools import lru_cache


def glob_match(pattern: str, path: str) -> bool:
    """Report whether a slash-separated path matches a glob pattern."""
    pat = pattern

    # Validate escapes: a trailing single unpaired backslash is invalid.
    i = 0
    while i < len(pat):
        if pat[i] == '\\':
            if i + 1 >= len(pat):
                raise ValueError("pattern ends with an unpaired backslash")
            i += 2
        else:
            i += 1

    @lru_cache(maxsize=None)
    def match(i: int, j: int) -> bool:
        if i >= len(pat):
            return j == len(path)

        # '**' as a whole path segment
        if (pat[i:i + 2] == '**'
                and (i == 0 or pat[i - 1] == '/')
                and (i + 2 == len(pat) or pat[i + 2] == '/')):
            if i + 2 == len(pat):
                # matches zero or more whole trailing segments
                return True
            # pat[i+2] == '/': skip '**/' (zero segments) or consume segments
            starts = [j] + [k + 1 for k in range(j, len(path)) if path[k] == '/']
            return any(match(i + 3, s) for s in starts)

        c = pat[i]

        if c == '*':
            # '*' matches zero or more non-'/' characters
            k = j
            while True:
                if match(i + 1, k):
                    return True
                if k >= len(path) or path[k] == '/':
                    return False
                k += 1

        if c == '?':
            return j < len(path) and path[j] != '/' and match(i + 1, j + 1)

        if c == '[':
            parsed = _parse_bracket(i)
            if parsed is None:
                # unclosed '[' is a literal
                return j < len(path) and path[j] == '[' and match(i + 1, j + 1)
            neg, chars, ranges, nxt = parsed
            if j >= len(path) or path[j] == '/':
                return False
            ch = path[j]
            in_set = ch in chars or any(lo <= ch <= hi for lo, hi in ranges)
            if in_set != neg:
                return match(nxt, j + 1)
            return False

        if c == '\\':
            # validated earlier: i+1 exists
            return j < len(path) and path[j] == pat[i + 1] and match(i + 2, j + 1)

        # literal character (including '/')
        return j < len(path) and path[j] == c and match(i + 1, j + 1)

    def _parse_bracket(i: int):
        """Parse a [...] set starting at i. Returns (neg, chars, ranges, next_index)
        or None if unclosed."""
        k = i + 1
        neg = False
        if k < len(pat) and pat[k] == '!':
            neg = True
            k += 1
        chars = set()
        ranges = []
        # a ']' right after '[' or '[!' is a literal ']'
        if k < len(pat) and pat[k] == ']':
            chars.add(']')
            k += 1
        start = None  # pending character for a potential range
        while k < len(pat) and pat[k] != ']':
            if (pat[k] == '-' and start is not None
                    and k + 1 < len(pat) and pat[k + 1] != ']'):
                ranges.append((start, pat[k + 1]))
                start = None
                k += 2
            else:
                start = pat[k]
                chars.add(pat[k])
                k += 1
        if k >= len(pat):
            return None  # no closing ']'
        return (neg, chars, ranges, k + 1)

    return match(0, 0)

from functools import lru_cache


def glob_match(pattern: str, path: str) -> bool:
    tokens = _parse(pattern)
    n = len(path)

    @lru_cache(maxsize=None)
    def match(pi: int, si: int) -> bool:
        if pi == len(tokens):
            return si == n
        kind = tokens[pi][0]

        if kind == "gstar":
            # Whole-segment `**`.
            if pi == len(tokens) - 1:
                # At end: matches zero or more trailing segments (anything).
                return True
            # Followed by a slash (only possibility for a whole-segment **).
            # Option 1: match zero segments, skipping the '/' too.
            if match(pi + 2, si):
                return True
            # Option 2: match one or more segments, ending at a '/'.
            j = si
            while j < n:
                if path[j] == "/":
                    if match(pi + 2, j + 1):
                        return True
                j += 1
            return False

        if kind == "slash":
            # A '/' followed by a trailing `**` also allows skipping the '/'.
            if (
                pi + 1 < len(tokens)
                and tokens[pi + 1][0] == "gstar"
                and pi + 1 == len(tokens) - 1
            ):
                if si == n:
                    return True
                if path[si] == "/":
                    return True
                return False
            return si < n and path[si] == "/" and match(pi + 1, si + 1)

        if kind == "lit":
            return si < n and path[si] == tokens[pi][1] and match(pi + 1, si + 1)

        if kind == "qm":
            return si < n and path[si] != "/" and match(pi + 1, si + 1)

        if kind == "star":
            # Zero or more non-'/' characters.
            end = si
            while end < n and path[end] != "/":
                end += 1
            for j in range(end, si - 1, -1):
                if match(pi + 1, j):
                    return True
            return False

        if kind == "set":
            _, chars, neg = tokens[pi]
            if si >= n or path[si] == "/":
                return False
            c = path[si]
            if (c in chars) != neg:
                return match(pi + 1, si + 1)
            return False

        raise AssertionError(kind)

    return match(0, 0)


def _parse(pattern: str):
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("pattern ends with a single unpaired backslash")
            tokens.append(("lit", pattern[i + 1]))
            i += 2
        elif c == "[":
            tok = _parse_bracket(pattern, i)
            if tok is None:
                tokens.append(("lit", "["))
                i += 1
            else:
                tokens.append(tok)
                i = tok[3]
        elif c == "*":
            if i + 1 < n and pattern[i + 1] == "*":
                prev_ok = i == 0 or pattern[i - 1] == "/"
                next_ok = i + 2 >= n or pattern[i + 2] == "/"
                if prev_ok and next_ok:
                    tokens.append(("gstar",))
                    i += 2
                    continue
            tokens.append(("star",))
            i += 1
        elif c == "?":
            tokens.append(("qm",))
            i += 1
        elif c == "/":
            tokens.append(("slash",))
            i += 1
        else:
            tokens.append(("lit", c))
            i += 1
    return tokens


def _parse_bracket(pattern: str, start: int):
    """Parse a [...] starting at pattern[start] == '['.

    Returns ("set", chars, negated, end_index) or None if unclosed.
    """
    n = len(pattern)
    j = start + 1
    neg = False
    if j < n and pattern[j] == "!":
        neg = True
        j += 1
    k = j
    if k < n and pattern[k] == "]":
        k += 1  # a ']' right after '[' or '[!' is a literal
    while k < n and pattern[k] != "]":
        k += 1
    if k >= n:
        return None  # no closing bracket: literal '['
    content = pattern[j:k]
    chars = set()
    idx = 0
    m = len(content)
    while idx < m:
        c = content[idx]
        if idx + 2 < m and content[idx + 1] == "-":
            lo, hi = c, content[idx + 2]
            for o in range(ord(lo), ord(hi) + 1):
                chars.add(chr(o))
            idx += 3
        else:
            chars.add(c)
            idx += 1
    return ("set", chars, neg, k + 1)

def glob_match(pattern: str, path: str) -> bool:
    # ---- Parse pattern into a list of segments; each segment is a token list.
    # Token forms: ('LIT', ch), ('ANY',), ('STAR',), ('GLOBSTAR',), ('CLASS', frozenset, negated)
    segments = []
    cur = []

    def flush():
        nonlocal cur
        if len(cur) == 2 and cur[0] == ('STAR',) and cur[1] == ('STAR',):
            segments.append([('GLOBSTAR',)])
        else:
            segments.append(cur)
        cur = []

    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with an unpaired backslash")
            cur.append(('LIT', pattern[i + 1]))
            i += 2
        elif c == '*':
            j = i
            while j < n and pattern[j] == '*':
                j += 1
            for _ in range(j - i):
                cur.append(('STAR',))
            i = j
        elif c == '?':
            cur.append(('ANY',))
            i += 1
        elif c == '[':
            j = i + 1
            negated = False
            if j < n and pattern[j] == '!':
                negated = True
                j += 1
            chars = []
            closed = False
            k = j
            while k < n:
                if pattern[k] == ']':
                    if k == j:  # ']' right after '[' or '[!' is literal
                        chars.append(']')
                        k += 1
                        continue
                    closed = True
                    break
                chars.append(pattern[k])
                k += 1
            if not closed:
                cur.append(('LIT', '['))
                i += 1
            else:
                members = set()
                idx = 0
                m = len(chars)
                while idx < m:
                    if idx + 2 < m and chars[idx + 1] == '-':
                        lo, hi = chars[idx], chars[idx + 2]
                        if ord(lo) > ord(hi):
                            lo, hi = hi, lo
                        for o in range(ord(lo), ord(hi) + 1):
                            members.add(chr(o))
                        idx += 3
                    else:
                        members.add(chars[idx])
                        idx += 1
                cur.append(('CLASS', frozenset(members), negated))
                i = k + 1
        elif c == '/':
            flush()
            i += 1
        else:
            cur.append(('LIT', c))
            i += 1
    flush()

    path_segs = path.split('/')

    # ---- Match one pattern segment against one path segment (no '/' inside).
    from functools import lru_cache

    def seg_match(tokens, s):
        lt, ls = len(tokens), len(s)

        @lru_cache(maxsize=None)
        def m(ti, si):
            if ti == lt:
                return si == ls
            t = tokens[ti]
            kind = t[0]
            if kind == 'STAR':
                return any(m(ti + 1, k) for k in range(si, ls + 1))
            if si >= ls:
                return False
            if kind == 'LIT':
                return s[si] == t[1] and m(ti + 1, si + 1)
            if kind == 'ANY':
                return m(ti + 1, si + 1)
            # CLASS
            _, members, negated = t
            ch = s[si]
            if ch == '/':
                return False
            if (ch in members) == negated:
                return False
            return m(ti + 1, si + 1)

        return m(0, 0)

    # ---- Match whole pattern against whole path, segment by segment.
    lp, ls = len(segments), len(path_segs)

    @lru_cache(maxsize=None)
    def match(pi, si):
        if pi == lp:
            return si == ls
        seg = segments[pi]
        if len(seg) == 1 and seg[0][0] == 'GLOBSTAR':
            return any(match(pi + 1, k) for k in range(si, ls + 1))
        return si < ls and seg_match(tuple(seg), path_segs[si]) and match(pi + 1, si + 1)

    return match(0, 0)

from functools import lru_cache


def glob_match(pattern: str, path: str) -> bool:
    tokens = _tokenize(pattern)
    # Split tokens into segments on '/' separators.
    segments = []
    cur = []
    for tok in tokens:
        if tok[0] == 'slash':
            segments.append(cur)
            cur = []
        else:
            cur.append(tok)
    segments.append(cur)

    psegs = path.split('/')

    @lru_cache(maxsize=None)
    def match_segment(toks: tuple, s: str, i: int, j: int) -> bool:
        if i == len(toks):
            return j == len(s)
        tok = toks[i]
        kind = tok[0]
        if kind == 'lit':
            return j < len(s) and s[j] == tok[1] and match_segment(toks, s, i + 1, j + 1)
        if kind == 'any':
            return j < len(s) and s[j] != '/' and match_segment(toks, s, i + 1, j + 1)
        if kind == 'star':
            if match_segment(toks, s, i + 1, j):
                return True
            return j < len(s) and s[j] != '/' and match_segment(toks, s, i, j + 1)
        if kind == 'set':
            _, neg, ranges = tok
            if j >= len(s) or s[j] == '/':
                return False
            c = s[j]
            inside = any(lo <= c <= hi for lo, hi in ranges)
            if inside == neg:
                return False
            return match_segment(toks, s, i + 1, j + 1)
        raise AssertionError

    def seg_tuple(seg):
        return tuple(seg)

    @lru_cache(maxsize=None)
    def match_path(si: int, pi: int) -> bool:
        if si == len(segments):
            return pi == len(psegs)
        seg = segments[si]
        if len(seg) == 1 and seg[0][0] == 'dstar':
            # matches zero or more whole path segments
            if match_path(si + 1, pi):
                return True
            return pi < len(psegs) and match_path(si, pi + 1)
        if pi >= len(psegs):
            return False
        if match_segment(seg_tuple(seg), psegs[pi], 0, 0):
            return match_path(si + 1, pi + 1)
        return False

    return match_path(0, 0)


def _tokenize(p: str):
    toks = []
    i = 0
    n = len(p)
    while i < n:
        c = p[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with a single unpaired backslash")
            toks.append(('lit', p[i + 1]))
            i += 2
        elif c == '?':
            toks.append(('any',))
            i += 1
        elif c == '*':
            if (i + 1 < n and p[i + 1] == '*'
                    and (i == 0 or p[i - 1] == '/')
                    and (i + 2 == n or p[i + 2] == '/')):
                toks.append(('dstar',))
                i += 2
            else:
                toks.append(('star',))
                i += 1
        elif c == '/':
            toks.append(('slash',))
            i += 1
        elif c == '[':
            j = i + 1
            neg = False
            if j < n and p[j] == '!':
                neg = True
                j += 1
            start = j  # position of first set content character
            chars = []
            k = j
            closed = False
            while k < n:
                if p[k] == ']':
                    if k == start:
                        chars.append(']')
                        k += 1
                        continue
                    closed = True
                    break
                chars.append(p[k])
                k += 1
            if not closed:
                # Unclosed '[' is a literal '['; reparse the rest normally.
                toks.append(('lit', '['))
                i += 1
                continue
            ranges = []
            idx = 0
            while idx < len(chars):
                if idx + 2 < len(chars) and chars[idx + 1] == '-':
                    ranges.append((chars[idx], chars[idx + 2]))
                    idx += 3
                else:
                    ranges.append((chars[idx], chars[idx]))
                    idx += 1
            toks.append(('set', neg, tuple(ranges)))
            i = k + 1
        else:
            toks.append(('lit', c))
            i += 1
    return toks

def glob_match(pattern: str, path: str) -> bool:
    # --- parse pattern into segments of atoms ---
    def parse_segment(seg):
        atoms = []
        i = 0
        n = len(seg)
        while i < n:
            c = seg[i]
            if c == '\\':
                if i + 1 >= n:
                    raise ValueError("pattern ends with unpaired backslash")
                atoms.append(('lit', seg[i + 1]))
                i += 2
            elif c == '?':
                atoms.append(('any',))
                i += 1
            elif c == '*':
                while i < n and seg[i] == '*':
                    i += 1
                atoms.append(('star',))
            elif c == '[':
                j = i + 1
                neg = False
                if j < n and seg[j] == '!':
                    neg = True
                    j += 1
                # ']' right after '[' or '[!' is literal
                start = j
                if j < n and seg[j] == ']':
                    j += 1
                while j < n and seg[j] != ']':
                    j += 1
                if j >= n:
                    # no closing bracket: literal '['
                    atoms.append(('lit', '['))
                    i += 1
                    continue
                s = seg[start:j]
                chars = set()
                k = 0
                while k < len(s):
                    if k + 1 < len(s) and s[k + 1] == '-' and k + 2 < len(s):
                        lo, hi = s[k], s[k + 2]
                        if lo > hi:
                            lo, hi = hi, lo
                        for o in range(ord(lo), ord(hi) + 1):
                            chars.add(chr(o))
                        k += 3
                    elif s[k] == '-':
                        chars.add('-')
                        k += 1
                    else:
                        chars.add(s[k])
                        k += 1
                atoms.append(('class', frozenset(chars), neg))
                i = j + 1
            else:
                atoms.append(('lit', c))
                i += 1
        return atoms

    # split pattern on unescaped '/'
    pat_segments = []
    cur = []
    i = 0
    n = len(pattern)
    while i < n:
        if pattern[i] == '\\' and i + 1 < n:
            cur.append(pattern[i])
            cur.append(pattern[i + 1])
            i += 2
        elif pattern[i] == '/':
            pat_segments.append(''.join(cur))
            cur = []
            i += 1
        else:
            cur.append(pattern[i])
            i += 1
    pat_segments.append(''.join(cur))

    parsed = []
    for seg in pat_segments:
        if seg == '**':
            parsed.append(None)  # globstar
        else:
            parsed.append(parse_segment(seg))

    path_segments = path.split('/')

    from functools import lru_cache

    def seg_match(atoms, s):
        @lru_cache(maxsize=None)
        def go(a, p):
            if a == len(atoms):
                return p == len(s)
            atom = atoms[a]
            if atom[0] == 'lit':
                return p < len(s) and s[p] == atom[1] and go(a + 1, p + 1)
            if atom[0] == 'any':
                return p < len(s) and s[p] != '/' and go(a + 1, p + 1)
            if atom[0] == 'class':
                return p < len(s) and s[p] != '/' and (s[p] in atom[1]) != atom[2] and go(a + 1, p + 1)
            # star
            for q in range(p, len(s) + 1):
                if go(a + 1, q):
                    return True
            return False
        return go(0, 0)

    m = len(parsed)
    N = len(path_segments)

    @lru_cache(maxsize=None)
    def match(i, j):
        if i == m:
            return j == N
        seg = parsed[i]
        if seg is None:  # '**'
            return any(match(i + 1, k) for k in range(j, N + 1))
        return j < N and seg_match(seg, path_segments[j]) and match(i + 1, j + 1)

    return match(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    tokens = _tokenize(pattern)
    n = len(path)
    memo = {}

    def m(ti: int, pi: int) -> bool:
        key = (ti, pi)
        if key in memo:
            return memo[key]
        if ti == len(tokens):
            res = (pi == n)
            memo[key] = res
            return res
        tok = tokens[ti]
        kind = tok[0]
        if kind == 'S':
            res = pi < n and path[pi] == '/' and m(ti + 1, pi + 1)
        elif kind == 'L':
            res = pi < n and path[pi] == tok[1] and m(ti + 1, pi + 1)
        elif kind == 'Q':
            res = pi < n and path[pi] != '/' and m(ti + 1, pi + 1)
        elif kind == 'STAR':
            end = pi
            while end < n and path[end] != '/':
                end += 1
            res = False
            for k in range(pi, end + 1):
                if m(ti + 1, k):
                    res = True
                    break
        elif kind == 'D':
            if ti + 1 == len(tokens):
                res = True
            else:
                # next token must be a slash separator
                res = m(ti + 2, pi)  # ** matches zero segments, skip the '/'
                if not res:
                    for k in range(pi, n):
                        if path[k] == '/' and m(ti + 1, k):
                            res = True
                            break
        elif kind == 'C':
            neg, items = tok[1], tok[2]
            res = False
            if pi < n and path[pi] != '/':
                ch = path[pi]
                in_set = False
                for item in items:
                    if isinstance(item, tuple):
                        lo, hi = item
                        if lo <= ch <= hi:
                            in_set = True
                            break
                    else:
                        if ch == item:
                            in_set = True
                            break
                res = (in_set != neg)
        else:
            res = False
        memo[key] = res
        return res

    return m(0, 0)


def _tokenize(pattern: str):
    tokens = []
    i = 0
    n = len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with an unpaired backslash")
            tokens.append(('L', pattern[i + 1]))
            i += 2
        elif c == '[':
            j = i + 1
            neg = False
            if j < n and pattern[j] == '!':
                neg = True
                j += 1
            if j < n and pattern[j] == ']':
                j += 1  # literal ']' first in set
            k = j
            while k < n and pattern[k] != ']':
                k += 1
            if k >= n:
                # no closing ']': literal '['
                tokens.append(('L', '['))
                i += 1
            else:
                items = []
                p = j
                while p < k:
                    if p + 2 < k + 1 and p + 1 < k and pattern[p + 1] == '-' and p + 2 <= k - 1:
                        # range: dash not last in set
                        lo, hi = pattern[p], pattern[p + 2]
                        if lo > hi:
                            lo, hi = hi, lo
                        items.append((lo, hi))
                        p += 3
                    else:
                        items.append(pattern[p])
                        p += 1
                tokens.append(('C', neg, items))
                i = k + 1
        elif c == '*':
            j = i
            while j < n and pattern[j] == '*':
                j += 1
            before_ok = (i == 0) or (tokens and tokens[-1][0] == 'S')
            after_ok = (j == n) or (j < n and pattern[j] == '/')
            if j - i >= 2 and before_ok and after_ok:
                tokens.append(('D',))
            else:
                tokens.append(('STAR',))
            i = j
        elif c == '/':
            tokens.append(('S',))
            i += 1
        elif c == '?':
            tokens.append(('Q',))
            i += 1
        else:
            tokens.append(('L', c))
            i += 1
    return tokens

from functools import lru_cache


def glob_match(pattern: str, path: str) -> bool:
    # ---- Parse pattern into segments (lists of tokens) ----
    # Token kinds: ('lit', ch), ('q',), ('star', count), ('cls', chars, ranges, negated)
    segments = []
    cur = []
    i, n = 0, len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with a single unpaired backslash")
            cur.append(('lit', pattern[i + 1]))
            i += 2
        elif c == '?':
            cur.append(('q',))
            i += 1
        elif c == '[':
            # Try to parse a character class; if unterminated, '[' is literal.
            j = i + 1
            neg = False
            if j < n and pattern[j] == '!':
                neg = True
                j += 1
            items = []  # single chars or (lo, hi) range tuples
            k = j
            first = True
            closed = False
            while k < n:
                if pattern[k] == ']' and not first:
                    closed = True
                    k += 1
                    break
                ch = pattern[k]
                k += 1
                first = False
                if k < n and pattern[k] == '-' and k + 1 < n and pattern[k + 1] != ']':
                    items.append((ch, pattern[k + 1]))
                    k += 2
                else:
                    items.append(ch)
            if closed:
                chars = set()
                ranges = []
                for it in items:
                    if isinstance(it, tuple):
                        ranges.append(it)
                    else:
                        chars.add(it)
                cur.append(('cls', frozenset(chars), tuple(ranges), neg))
                i = k
            else:
                cur.append(('lit', '['))
                i += 1
        elif c == '*':
            j = i
            while j < n and pattern[j] == '*':
                j += 1
            cur.append(('star', j - i))
            i = j
        elif c == '/':
            segments.append(cur)
            cur = []
            i += 1
        else:
            cur.append(('lit', c))
            i += 1
    segments.append(cur)

    # A segment is a double-star iff it consists of exactly one '*' token of count 2.
    def is_doublestar(seg):
        return len(seg) == 1 and seg[0][0] == 'star' and seg[0][1] == 2

    ds = [is_doublestar(s) for s in segments]

    # ---- Match a single (non-**) pattern segment against one path segment ----
    def class_match(token, ch):
        _, chars, ranges, neg = token
        inside = ch in chars
        for lo, hi in ranges:
            if lo <= ch <= hi:
                inside = True
                break
        return inside != neg

    def seg_match(tokens, s):
        @lru_cache(maxsize=None)
        def m(ti, si):
            if ti == len(tokens):
                return si == len(s)
            t = tokens[ti]
            kind = t[0]
            if kind == 'lit':
                return si < len(s) and s[si] == t[1] and m(ti + 1, si + 1)
            if kind == 'q':
                return si < len(s) and m(ti + 1, si + 1)
            if kind == 'star':
                # '*' (or a non-segment '**') matches any run without '/'
                for k in range(si, len(s) + 1):
                    if m(ti + 1, k):
                        return True
                return False
            # class
            if si < len(s) and class_match(t, s[si]) and m(ti + 1, si + 1):
                return True
            return False
        return m(0, 0)

    # ---- Match segments against path segments ----
    ps = path.split('/') if path else []
    nseg, nps = len(segments), len(ps)

    @lru_cache(maxsize=None)
    def M(i, j):
        if i == nseg:
            return j == nps
        if ds[i]:
            if M(i + 1, j):
                return True
            return j < nps and M(i, j + 1)
        return j < nps and seg_match(segments[i], ps[j]) and M(i + 1, j + 1)

    return M(0, 0)

from functools import lru_cache


def _segment_match(pat: str, s: str) -> bool:
    """Match a single pattern segment against a single path segment (no '/')."""

    @lru_cache(maxsize=None)
    def m(pi: int, si: int) -> bool:
        if pi == len(pat):
            return si == len(s)
        c = pat[pi]
        if c == '\\':
            # trailing unpaired backslash handled globally; treat as literal guard
            if pi + 1 >= len(pat):
                return False
            return si < len(s) and s[si] == pat[pi + 1] and m(pi + 2, si + 1)
        if c == '?':
            return si < len(s) and m(pi + 1, si + 1)
        if c == '*':
            return any(m(pi + 1, si + k) for k in range(len(s) - si + 1))
        if c == '[':
            j = pi + 1
            neg = False
            if j < len(pat) and pat[j] == '!':
                neg = True
                j += 1
            chars = set()
            k = j
            first = True
            while k < len(pat) and (first or pat[k] != ']'):
                if (k + 2 < len(pat) and pat[k + 1] == '-'
                        and pat[k + 2] != ']'):
                    lo, hi = ord(pat[k]), ord(pat[k + 2])
                    for o in range(min(lo, hi), max(lo, hi) + 1):
                        chars.add(chr(o))
                    k += 3
                else:
                    chars.add(pat[k])
                    k += 1
                first = False
            if k >= len(pat):
                # no closing ']': '[' is a literal
                return si < len(s) and s[si] == '[' and m(pi + 1, si + 1)
            if neg:
                ok = si < len(s) and s[si] not in chars
            else:
                ok = si < len(s) and s[si] in chars
            return ok and m(k + 1, si + 1)
        return si < len(s) and s[si] == c and m(pi + 1, si + 1)

    return m(0, 0)


def glob_match(pattern: str, path: str) -> bool:
    # A pattern ending with an odd number of backslashes has an unpaired '\'.
    trailing = 0
    while trailing < len(pattern) and pattern[len(pattern) - 1 - trailing] == '\\':
        trailing += 1
    if trailing % 2 == 1:
        raise ValueError("pattern ends with an unpaired backslash")

    psegs = pattern.split('/')
    ssegs = path.split('/')

    @lru_cache(maxsize=None)
    def match(i: int, j: int) -> bool:
        if i == len(psegs):
            return j == len(ssegs)
        if psegs[i] == '**':
            return any(match(i + 1, k) for k in range(j, len(ssegs) + 1))
        return (j < len(ssegs)
                and _segment_match(psegs[i], ssegs[j])
                and match(i + 1, j + 1))

    return match(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # Token types: ('lit', c), ('any',), ('star',), ('class', negated, items)
    # items: list of (lo, hi) inclusive ranges (lo == hi for single chars)

    LIT, ANY, STAR, CLS = 0, 1, 2, 3

    def parse():
        segments = []  # list of (tokens, is_double_star)
        tokens = []
        i = 0
        n = len(pattern)

        def finish_segment():
            nonlocal tokens
            if len(tokens) == 2 and tokens[0][0] == STAR and tokens[1][0] == STAR:
                segments.append(([], True))
            else:
                segments.append((tokens, False))
            tokens = []

        while i < n:
            c = pattern[i]
            if c == '\\':
                if i + 1 >= n:
                    raise ValueError("pattern ends with a single unpaired backslash")
                tokens.append((LIT, pattern[i + 1]))
                i += 2
            elif c == '/':
                finish_segment()
                i += 1
            elif c == '?':
                tokens.append((ANY,))
                i += 1
            elif c == '*':
                tokens.append((STAR,))
                i += 1
            elif c == '[':
                j = i + 1
                negated = False
                if j < n and pattern[j] == '!':
                    negated = True
                    j += 1
                items = []
                closed = False
                last = None
                k = j
                while k < n:
                    if pattern[k] == ']' and k != j:
                        closed = True
                        k += 1
                        break
                    if pattern[k] == ']' and k == j:
                        # literal ']' right after '[' or '[!'
                        items.append((']', ']'))
                        last = ']'
                        k += 1
                        continue
                    if pattern[k] == '-' and last is not None and k + 1 < n and pattern[k + 1] != ']':
                        items[-1] = (last, pattern[k + 1])
                        last = pattern[k + 1]
                        k += 2
                        continue
                    items.append((pattern[k], pattern[k]))
                    last = pattern[k]
                    k += 1
                if closed:
                    tokens.append((CLS, negated, items))
                    i = k
                else:
                    # unclosed '[': literal '['
                    tokens.append((LIT, '['))
                    i += 1
            else:
                tokens.append((LIT, c))
                i += 1
        finish_segment()
        return segments

    segments = parse()
    psegs = path.split('/')

    def seg_match(tokens, s):
        m = len(tokens)
        nn = len(s)
        # dp[j][i]: tokens[j:] matches s[i:]
        dp = [[False] * (nn + 1) for _ in range(m + 1)]
        dp[m][nn] = True
        for j in range(m - 1, -1, -1):
            tok = tokens[j]
            kind = tok[0]
            for i in range(nn, -1, -1):
                if kind == STAR:
                    dp[j][i] = dp[j + 1][i] or (i < nn and dp[j][i + 1])
                elif kind == LIT:
                    dp[j][i] = i < nn and s[i] == tok[1] and dp[j + 1][i + 1]
                elif kind == ANY:
                    dp[j][i] = i < nn and s[i] != '/' and dp[j + 1][i + 1]
                else:  # CLS
                    ok = False
                    if i < nn and s[i] != '/':
                        ch = s[i]
                        in_set = any(lo <= ch <= hi for lo, hi in tok[2])
                        ok = (not in_set) if tok[1] else in_set
                    dp[j][i] = ok and dp[j + 1][i + 1]
        return dp[0][0]

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(pi, si):
        if pi == len(segments):
            return si == len(psegs)
        tokens, is_ds = segments[pi]
        if is_ds:
            for k in range(si, len(psegs) + 1):
                if match(pi + 1, k):
                    return True
            return False
        if si >= len(psegs):
            return False
        return seg_match(tokens, psegs[si]) and match(pi + 1, si + 1)

    return match(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    n = len(pattern)
    m = len(path)

    # A pattern ending with an unpaired backslash is invalid.
    k = n
    while k > 0 and pattern[k - 1] == '\\':
        k -= 1
    if (n - k) % 2 == 1:
        raise ValueError("pattern ends with an unpaired backslash")

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def rec(i: int, j: int) -> bool:
        if i >= n:
            return j == m

        # Whole-segment '**'?
        if pattern.startswith('**', i):
            is_whole = (i == 0 or pattern[i - 1] == '/') and \
                       (i + 2 == n or pattern[i + 2] == '/')
            if is_whole:
                if i + 2 == n:
                    # '**' at the end matches zero or more remaining segments.
                    return True
                ni = i + 3  # skip '**/'
                # '**' matches zero or more whole segments: try j itself
                # (zero segments) and every position just after a '/'.
                candidates = [j]
                p = path.find('/', j)
                while p != -1:
                    candidates.append(p + 1)
                    p = path.find('/', p + 1)
                return any(rec(ni, c) for c in candidates)

        c = pattern[i]

        # Trailing '/**' at end of pattern: the '/' is optional so that
        # zero segments can match (e.g. 'a/**' matches 'a'); otherwise
        # the '**' consumes the rest of the path.
        if c == '/' and i + 3 == n and pattern[i + 1:i + 3] == '**':
            return j == m or path[j] == '/'

        if c == '\\':
            if i + 1 < n and j < m and path[j] == pattern[i + 1]:
                return rec(i + 2, j + 1)
            return False

        if c == '?':
            return j < m and path[j] != '/' and rec(i + 1, j + 1)

        if c == '*':
            # zero or more non-'/' characters
            end = path.find('/', j)
            limit = m if end == -1 else end
            return any(rec(i + 1, t) for t in range(j, limit + 1))

        if c == '[':
            k2 = i + 1
            neg = False
            if k2 < n and pattern[k2] == '!':
                neg = True
                k2 += 1
            start = k2
            # ']' right after '[' or '[!' is a literal ']'
            if k2 < n and pattern[k2] == ']':
                k2 += 1
            while k2 < n and pattern[k2] != ']':
                k2 += 1
            if k2 >= n:
                # unclosed '[' is a literal '['
                return j < m and path[j] == '[' and rec(i + 1, j + 1)
            chars = set()
            p = start
            while p < k2:
                if (p + 2 < k2 and pattern[p + 1] == '-'
                        and not (p == start and pattern[p] == '-')):
                    lo, hi = pattern[p], pattern[p + 2]
                    for o in range(ord(lo), ord(hi) + 1):
                        chars.add(chr(o))
                    p += 3
                else:
                    chars.add(pattern[p])
                    p += 1
            if j < m and path[j] != '/' and (path[j] in chars) != neg:
                return rec(k2 + 1, j + 1)
            return False

        # literal
        return j < m and path[j] == c and rec(i + 1, j + 1)

    return rec(0, 0)

def glob_match(pattern: str, path: str) -> bool:
    # --- tokenize pattern into segments ---
    if pattern.endswith("\\") and (len(pattern) < 2 or pattern[-2] != "\\"):
        # a single unpaired trailing backslash (after unescaping check below)
        pass  # handled during parsing

    segments = []
    cur = []
    i = 0
    n = len(pattern)

    def is_doublestar(toks):
        return len(toks) == 1 and toks[0] == ("starstar",)

    while i < n:
        c = pattern[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("pattern ends with unpaired backslash")
            cur.append(("lit", pattern[i + 1]))
            i += 2
        elif c == "[":
            j = i + 1
            neg = False
            if j < n and pattern[j] == "!":
                neg = True
                j += 1
            items = []
            # first ']' is literal
            if j < n and pattern[j] == "]":
                items.append(("char", "]"))
                j += 1
            closed = False
            while j < n:
                if pattern[j] == "]":
                    closed = True
                    j += 1
                    break
                if j + 2 < n and pattern[j + 1] == "-" and pattern[j + 2] != "]":
                    items.append(("range", pattern[j], pattern[j + 2]))
                    j += 3
                else:
                    items.append(("char", pattern[j]))
                    j += 1
            if not closed:
                # literal '[' — reparse rest normally
                cur.append(("lit", "["))
                i += 1
            else:
                cur.append(("set", neg, items))
                i = j
        elif c == "*":
            if i + 1 < n and pattern[i + 1] == "*":
                cur.append(("starstar",))
                i += 2
            else:
                cur.append(("star",))
                i += 1
        elif c == "?":
            cur.append(("q",))
            i += 1
        elif c == "/":
            if len(cur) == 1 and cur[0] == ("starstar",):
                segments.append([("dstar",)])
            else:
                # collapse consecutive starstars inside a segment into star
                seg = [("star",) if t == ("starstar",) else t for t in cur]
                segments.append(seg)
            cur = []
            i += 1
        else:
            cur.append(("lit", c))
            i += 1

    if len(cur) == 1 and cur[0] == ("starstar",):
        segments.append([("dstar",)])
    else:
        segments.append([("star",) if t == ("starstar",) else t for t in cur])

    path_segs = path.split("/")

    def seg_match(toks, s):
        # DP: toks match string s fully; no token matches '/'
        m = len(toks)
        L = len(s)
        # dp[j] for suffix matching; do iterative from end
        dp = [False] * (L + 1)
        dp[L] = True
        for ti in range(m - 1, -1, -1):
            t = toks[ti]
            ndp = [False] * (L + 1)
            if t == ("star",):
                # star matches zero or more chars
                for j in range(L, -1, -1):
                    ndp[j] = dp[j] or (j < L and ndp[j + 1])
            else:
                for j in range(L):
                    c = s[j]
                    if t == ("q",):
                        ok = c != "/"
                    elif t[0] == "lit":
                        ok = c == t[1]
                    else:
                        _, neg, items = t
                        if c == "/":
                            ok = False
                        else:
                            in_set = False
                            for it in items:
                                if it[0] == "char":
                                    if c == it[1]:
                                        in_set = True
                                        break
                                else:
                                    if it[1] <= c <= it[2]:
                                        in_set = True
                                        break
                            ok = (not in_set) if neg else in_set
                    ndp[j] = ok and dp[j + 1]
            dp = ndp
        return dp[0]

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def match(pi, si):
        if pi == len(segments):
            return si == len(path_segs)
        seg = segments[pi]
        if len(seg) == 1 and seg[0] == ("dstar",):
            return any(match(pi + 1, k) for k in range(si, len(path_segs) + 1))
        if si >= len(path_segs):
            return False
        return seg_match(seg, path_segs[si]) and match(pi + 1, si + 1)

    return match(0, 0)

from functools import lru_cache


def glob_match(pattern: str, path: str) -> bool:
    psegs = _split_segments(pattern)
    path_segs = path.split('/')

    seg_matchers = []
    for seg in psegs:
        if _is_globstar(seg):
            seg_matchers.append(None)
        else:
            seg_matchers.append(_compile_segment(seg))

    n, m = len(psegs), len(path_segs)

    @lru_cache(maxsize=None)
    def dp(i: int, j: int) -> bool:
        if i == n:
            return j == m
        matcher = seg_matchers[i]
        if matcher is None:  # '**' segment: zero or more whole segments
            if dp(i + 1, j):
                return True
            return j < m and dp(i, j + 1)
        if j >= m:
            return False
        return matcher(path_segs[j]) and dp(i + 1, j + 1)

    return dp(0, 0)


def _is_globstar(seg: str) -> bool:
    """A segment made of two or more '*' characters is a globstar."""
    return len(seg) >= 2 and set(seg) == {'*'}


def _split_segments(pattern: str):
    """Split on unescaped '/'; validate trailing backslash."""
    segments = []
    cur = []
    i, n = 0, len(pattern)
    while i < n:
        c = pattern[i]
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("pattern ends with an unpaired backslash")
            cur.append(c)
            cur.append(pattern[i + 1])
            i += 2
        elif c == '/':
            segments.append(''.join(cur))
            cur = []
            i += 1
        else:
            cur.append(c)
            i += 1
    segments.append(''.join(cur))
    return segments


def _compile_segment(seg: str):
    tokens = _parse_segment(seg)

    @lru_cache(maxsize=None)
    def match(s: str) -> bool:
        return _match_tokens(tokens, s)

    return match


def _match_tokens(tokens, s: str) -> bool:
    @lru_cache(maxsize=None)
    def m(pi: int, si: int) -> bool:
        if pi == len(tokens):
            return si == len(s)
        kind = tokens[pi][0]
        if kind == 'LIT':
            return si < len(s) and s[si] == tokens[pi][1] and m(pi + 1, si + 1)
        if kind == 'ANY':
            return si < len(s) and s[si] != '/' and m(pi + 1, si + 1)
        if kind == 'SET':
            neg, ranges = tokens[pi][1], tokens[pi][2]
            if si >= len(s) or s[si] == '/':
                return False
            inside = any(lo <= s[si] <= hi for lo, hi in ranges)
            return (inside != neg) and m(pi + 1, si + 1)
        # STAR
        if m(pi + 1, si):
            return True
        return si < len(s) and s[si] != '/' and m(pi, si + 1)

    return m(0, 0)


def _parse_segment(seg: str):
    tokens = []
    i, n = 0, len(seg)
    while i < n:
        c = seg[i]
        if c == '\\':
            # trailing backslash was already rejected during splitting
            tokens.append(('LIT', seg[i + 1]))
            i += 2
        elif c == '?':
            tokens.append(('ANY',))
            i += 1
        elif c == '*':
            j = i
            while j < n and seg[j] == '*':
                j += 1
            tokens.append(('STAR',))
            i = j
        elif c == '[':
            tok, i = _parse_set(seg, i)
            tokens.append(tok)
        else:
            tokens.append(('LIT', c))
            i += 1
    return tokens


def _parse_set(pattern: str, i: int):
    """Parse a bracket expression starting at pattern[i] == '['.
    Returns (token, next_index). If unterminated, returns a literal '['."""
    n = len(pattern)
    j = i + 1
    neg = False
    if j < n and pattern[j] == '!':
        neg = True
        j += 1
    ranges = []
    first = True
    while j < n:
        if pattern[j] == ']' and not first:
            return ('SET', neg, ranges), j + 1
        c1 = pattern[j]
        j += 1
        if j + 1 < n and pattern[j] == '-' and pattern[j + 1] != ']':
            ranges.append((c1, pattern[j + 1]))
            j += 2
        else:
            ranges.append((c1, c1))
        first = False
    # No closing ']': the '[' is a literal.
    return ('LIT', '['), i + 1

from datetime import datetime, timedelta, date

RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _to_int(s):
    if not s.isdigit():
        raise ValueError("bad number: %r" % s)
    return int(s)


def _parse_field(field, lo, hi):
    values = set()
    for item in field.split(','):
        if item == '':
            raise ValueError("empty item")
        step = 1
        base = item
        if '/' in item:
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError("bad item: %r" % item)
            base, step_s = parts
            step = _to_int(step_s)
            if step == 0:
                raise ValueError("step 0")
        if base == '*':
            rng = range(lo, hi + 1)
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError("bad range: %r" % base)
            a, b = _to_int(parts[0]), _to_int(parts[1])
            if not (lo <= a <= hi) or not (lo <= b <= hi):
                raise ValueError("value out of range")
            if a > b:
                raise ValueError("A > B")
            rng = range(a, b + 1)
        else:
            n = _to_int(base)
            if not (lo <= n <= hi):
                raise ValueError("value out of range")
            rng = range(n, n + 1)
        values.update(rng[::step])
    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("need 5 fields")
    parsed = []
    for f, (lo, hi) in zip(fields, RANGES):
        parsed.append(_parse_field(f, lo, hi))
    minutes, hours, doms, months, dows = parsed
    dows = {d % 7 for d in dows}

    dom_star = fields[2].startswith('*')
    dow_star = fields[4].startswith('*')
    either = not dom_star and not dow_star

    try:
        t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after: %r" % after)
    t += timedelta(minutes=1)

    limit = date(t.year + 8, t.month, t.day) if t.month <= 12 else None
    # handle month overflow safely
    try:
        limit = date(t.year + 8, t.month, t.day)
    except ValueError:
        limit = date(t.year + 8, 12, 31)

    d = t.date()
    while d <= limit:
        if d.month in months:
            dom_ok = d.day in doms
            cron_dow = (d.weekday() + 1) % 7
            dow_ok = cron_dow in dows
            if (dom_ok or dow_ok) if either else (dom_ok and dow_ok):
                for h in sorted(hours):
                    for m in sorted(minutes):
                        cand = datetime(d.year, d.month, d.day, h, m)
                        if cand > datetime.strptime(after, "%Y-%m-%dT%H:%M"):
                            return cand.strftime("%Y-%m-%dT%H:%M")
        d += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

from datetime import datetime, timedelta

RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _parse_field(field, lo, hi):
    if not field:
        raise ValueError("empty field")
    values = set()
    for item in field.split(','):
        step = 1
        if '/' in item:
            base, s = item.split('/', 1)
            if not s.isdigit() or int(s) == 0:
                raise ValueError("bad step")
            step = int(s)
        else:
            base = item
        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            a, b = base.split('-', 1)
            if not a.isdigit() or not b.isdigit():
                raise ValueError("bad range")
            start, end = int(a), int(b)
            if start < lo or end > hi or start > end:
                raise ValueError("out of range")
        else:
            if not base.isdigit():
                raise ValueError("bad value")
            v = int(base)
            if v < lo or v > hi:
                raise ValueError("out of range")
            start = end = v
        values.update(range(start, end + 1, step))
    if not values:
        raise ValueError("empty field")
    return values


def next_cron(expr: str, after: str) -> str:
    parts = expr.split(' ')
    if len(parts) != 5:
        raise ValueError("wrong number of fields")
    mins = _parse_field(parts[0], 0, 59)
    hrs = _parse_field(parts[1], 0, 23)
    doms = _parse_field(parts[2], 1, 31)
    mons = _parse_field(parts[3], 1, 12)
    dows = _parse_field(parts[4], 0, 7)
    dows = {0 if d == 7 else d for d in dows}

    dom_restricted = not parts[2].startswith('*')
    dow_restricted = not parts[4].startswith('*')

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    limit = t + timedelta(days=8 * 366)

    day = t.date()
    while day <= limit.date():
        if day.month in mons:
            dm = day.day in doms
            dw = (day.weekday() + 1) % 7 in dows  # Monday=1..Sunday=0
            if dom_restricted and dow_restricted:
                day_ok = dm or dw
            else:
                day_ok = dm and dw
            if day_ok:
                for h in sorted(hrs):
                    for m in sorted(mins):
                        cand = datetime(day.year, day.month, day.day, h, m)
                        if cand > t:
                            return cand.strftime("%Y-%m-%dT%H:%M")
        day += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

from datetime import date, datetime, timedelta

RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _parse_field(text, lo, hi):
    values = set()
    for item in text.split(','):
        step = 1
        base = item
        if '/' in item:
            base, step_s = item.split('/', 1)
            if not step_s.isdigit():
                raise ValueError("bad step")
            step = int(step_s)
            if step == 0:
                raise ValueError("step 0")
        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError("bad range")
            a, b = parts
            if not (a.isdigit() and b.isdigit()):
                raise ValueError("bad range")
            start, end = int(a), int(b)
            if start > end:
                raise ValueError("A > B")
        else:
            if not base.isdigit():
                raise ValueError("bad value")
            start = end = int(base)
        if start < lo or end > hi:
            raise ValueError("out of range")
        values.update(range(start, end + 1, step))
    if not values:
        raise ValueError("empty field")
    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("wrong number of fields")
    minutes = sorted(_parse_field(fields[0], 0, 59))
    hours = sorted(_parse_field(fields[1], 0, 23))
    doms = sorted(_parse_field(fields[2], 1, 31))
    months = sorted(_parse_field(fields[3], 1, 12))
    dows = sorted(_parse_field(fields[4], 0, 7))
    dows = sorted({7 if d == 0 else d for d in dows})  # normalize Sunday to 7

    dom_wild = fields[2].startswith('*')
    dow_wild = fields[4].startswith('*')

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    start_date = t.date()
    limit = start_date + timedelta(days=8 * 366)

    d = start_date
    while d <= limit:
        if d.month in months:
            dom_ok = d.day in doms
            dow_ok = (d.isoweekday() in dows)
            if dom_wild or dow_wild:
                day_match = dom_ok and dow_ok
            else:
                day_match = dom_ok or dow_ok
            if day_match:
                for h in hours:
                    for m in minutes:
                        cand = datetime(d.year, d.month, d.day, h, m)
                        if cand > t:
                            return cand.strftime("%Y-%m-%dT%H:%M")
        d += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

from datetime import datetime, timedelta

def next_cron(expr: str, after: str) -> str:
