                    raise ValueError("bad")
                v = int(base)
                if v < lo or v > hi:
                    raise ValueError("range")
                start = end = v
            vals.update(range(start, end + 1, step))
        return vals

    try:
        minutes = parse_field(parts[0], 0, 59)
        hours = parse_field(parts[1], 0, 23)
        doms = parse_field(parts[2], 1, 31)
        months = parse_field(parts[3], 1, 12)
        dows = parse_field(parts[4], 0, 7)
    except ValueError:
        raise
    except Exception:
        raise ValueError("bad expr")

    dom_star = parts[2].startswith('*')
    dow_star = parts[4].startswith('*')
    restricted = not dom_star and not dow_star

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    limit = t + timedelta(days=8 * 366)

    times = sorted((h, m) for h in hours for m in minutes)

    day = t.replace(hour=0, minute=0)
    while day <= limit:
        if day.month in months:
            cron_dow = (day.weekday() + 1) % 7
            dm = day.day in doms
            dw = cron_dow in dows
            ok = (dm or dw) if restricted else (dm and dw)
            if ok:
                for h, m in times:
                    cand = day.replace(hour=h, minute=m)
                    if cand > t:
                        return cand.strftime("%Y-%m-%dT%H:%M")
        day += timedelta(days=1)
    raise ValueError("no matching time")

from datetime import datetime, timedelta

RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]

def _parse_field(field, lo, hi):
    if not field:
        raise ValueError("empty field")
    values = set()
    for item in field.split(','):
        if not item:
            raise ValueError("empty item")
        step = 1
        if '/' in item:
            base, s = item.split('/', 1)
            if not s.isdigit():
                raise ValueError("bad step")
            step = int(s)
            if step == 0:
                raise ValueError("step 0")
        else:
            base = item
        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            a, b = base.split('-', 1)
            if not (a.isdigit() and b.isdigit()):
                raise ValueError("bad range")
            start, end = int(a), int(b)
            if start < lo or end > hi or start > end:
                raise ValueError("out of range")
        else:
            if not base.isdigit():
                raise ValueError("bad value")
            start = end = int(base)
            if start < lo or start > hi:
                raise ValueError("out of range")
        values.update(range(start, end + 1, step))
    return values

def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("wrong number of fields")
    sets = []
    for f, (lo, hi) in zip(fields, RANGES):
        sets.append(_parse_field(f, lo, hi))
    minutes, hours, doms, months, dows = sets
    dows = {0 if d == 7 else d for d in dows}

    dom_restricted = not fields[2].startswith('*')
    dow_restricted = not fields[4].startswith('*')

    try:
        t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after")

    limit = t + timedelta(days=8 * 366)

    def day_matches(d):
        if d.month not in months:
            return False
        if d.day > 31:
            return False
        dom_ok = d.day in doms
        dow_ok = (d.weekday() + 1) % 7 in dows  # Monday=1 -> cron 1
        if dom_restricted and dow_restricted:
            return dom_ok or dow_ok
        return dom_ok and dow_ok

    cur = t + timedelta(minutes=1)
    day = cur.replace(hour=0, minute=0)
    while day <= limit:
        if day_matches(day):
            start = cur if day.date() == cur.date() else day
            m = start.hour * 60 + start.minute
            while m < 1440:
                if m % 60 in minutes and m // 60 in hours:
                    return (day + timedelta(minutes=m)).strftime("%Y-%m-%dT%H:%M")
                m += 1
        day += timedelta(days=1)
        cur = day
    raise ValueError("no matching time within 8 years")

