RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _parse_field(text, lo, hi):
    values = set()
    for item in text.split(','):
        if not item:
            raise ValueError("empty field item")
        step = 1
        base = item
        if '/' in item:
            base, step_s = item.split('/', 1)
            if not step_s.isdigit():
                raise ValueError("bad step")
            step = int(step_s)
            if step < 1:
                raise ValueError("step 0")
        if base == '*':
            a, b = lo, hi
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError("bad range")
            a_s, b_s = parts
            if not (a_s.isdigit() and b_s.isdigit()):
                raise ValueError("bad range")
            a, b = int(a_s), int(b_s)
            if a > b:
                raise ValueError("A > B")
        else:
            if not base.isdigit():
                raise ValueError("bad value")
            a = b = int(base)
        if a < lo or b > hi:
            raise ValueError("value out of range")
        values.update(range(a, b + 1, step))
    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("wrong number of fields")
    mins, hours, doms, months, dows = (
        _parse_field(f, lo, hi) for f, (lo, hi) in zip(fields, RANGES)
    )
    dom_restricted = not fields[2].startswith('*')
    dow_restricted = not fields[4].startswith('*')

    start = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    y = start.year + 8
    try:
        limit = start.replace(year=y)
    except ValueError:
        limit = start.replace(year=y, day=28)

    cur = start + timedelta(minutes=1)
    while cur <= limit:
        date = cur.date()
        dom_ok = date.day in doms
        # cron dow: 0/7=Sunday..6=Saturday; python weekday(): Monday=0..Sunday=6
        cron_dow = (date.weekday() + 1) % 7
        dow_ok = cron_dow in dows
        if dom_restricted and dow_restricted:
            day_ok = dom_ok or dow_ok
        else:
            day_ok = dom_ok and dow_ok
        if day_ok and date.month in months:
            # iterate minutes of this day starting at cur
            t = cur
            end_of_day = datetime(date.year, date.month, date.day, 23, 59)
            while t <= end_of_day and t <= limit:
                if t.hour in hours and t.minute in mins:
                    return t.strftime("%Y-%m-%dT%H:%M")
                t += timedelta(minutes=1)
        # move to next day 00:00
        cur = datetime(date.year, date.month, date.day) + timedelta(days=1)
    raise ValueError("no matching time within 8 years")

