RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _parse_field(field, lo, hi):
    values = set()
    for item in field.split(','):
        if not item:
            raise ValueError("empty item")
        step = 1
        body = item
        if '/' in item:
            body, step_s = item.split('/', 1)
            try:
                step = int(step_s)
            except ValueError:
                raise ValueError("bad step")
            if step < 1:
                raise ValueError("step must be >= 1")
            if '/' in step_s:
                raise ValueError("bad step")
