    dow_star = fields[4].startswith('*')

    try:
        t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after")

    start = t + timedelta(minutes=1)
    day = start.replace(hour=0, minute=0)
    limit = day + timedelta(days=366 * 8 + 2)

    while day < limit:
        if day.month in months:
            dom_ok = day.day in doms
            dow_ok = day.weekday() in dows if False else ((day.weekday() + 1) % 7) in dows
            if dom_star and dow_star:
                day_ok = dom_ok and dow_ok
            elif not dom_star and not dow_star:
                day_ok = dom_ok or dow_ok
            elif dom_star:
                day_ok = dow_ok
            else:
                day_ok = dom_ok
            if day_ok:
                for h in sorted(hours):
                    for m in sorted(minutes):
                        cand = day.replace(hour=h, minute=m)
                        if cand > t:
                            return cand.strftime("%Y-%m-%dT%H:%M")
        day += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

