RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]

def _parse_field(field, lo, hi):
    values = set()
    for item in field.split(','):
        if '/' in item:
            base, step_s = item.split('/', 1)
            try:
                step = int(step_s)
            except ValueError:
                raise ValueError("bad step")
            if step <= 0:
                raise ValueError("step 0")
            if base == '*':
                a, b = lo, hi
            else:
                if '-' not in base:
                    raise ValueError("bad range with step")
                a_s, b_s = base.split('-', 1)
                a, b = int(a_s), int(b_s)
                if a < lo or b > hi or a > b:
                    raise ValueError("range out of bounds")
            values.update(range(a, b + 1, step))
        elif item == '*':
            values.update(range(lo, hi + 1))
        elif '-' in item:
            a_s, b_s = item.split('-', 1)
            a, b = int(a_s), int(b_s)
            if a < lo or b > hi or a > b:
                raise ValueError("range out of bounds")
            values.update(range(a, b + 1))
        else:
            v = int(item)
            if v < lo or v > hi:
                raise ValueError("value out of range")
            values.add(v)
    if not values:
        raise ValueError("empty field")
    return values

def next_cron(expr: str, after: str) -> str:
    parts = expr.split(' ')
    if len(parts) != 5:
        raise ValueError("need 5 fields")
    fields = []
    for p, (lo, hi) in zip(parts, RANGES):
        fields.append((_parse_field(p, lo, hi), p.startswith('*')))
    minutes, hours, doms, months, dows = [f[0] for f in fields]
    dom_star, dow_star = fields[2][1], fields[4][1]
    dows = {d % 7 for d in dows}  # normalize 7 -> 0

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    limit = t + timedelta(days=8 * 366)

    day = t.date()
    while day <= limit.date():
        if day.month in months:
            dom_ok = day.day in doms
            dow_ok = day.isoweekday() % 7 in dows
            if dom_star and dow_star:
                day_ok = True
            elif not dom_star and not dow_star:
                day_ok = dom_ok or dow_ok
            elif dom_star:
                day_ok = dow_ok
            else:
                day_ok = dom_ok
            if day_ok:
                base = datetime(day.year, day.month, day.day)
                for h in sorted(hours):
                    for m in sorted(minutes):
                        cand = base + timedelta(hours=h, minutes=m)
                        if cand > t:
                            return cand.strftime("%Y-%m-%dT%H:%M")
        day += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

