from datetime import datetime, timedelta

RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]

def _parse_field(text, lo, hi):
    values = set()
    for item in text.split(','):
        if '/' in item:
            base, step_s = item.split('/', 1)
            step = int(step_s)
            if step < 1:
                raise ValueError("bad step")
        else:
            base, step = item, 1
        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            a, b = base.split('-', 1)
            start, end = int(a), int(b)
            if start > end:
                raise ValueError("A > B")
        else:
            start = end = int(base)
        if start < lo or end > hi:
            raise ValueError("out of range")
        values.update(range(start, end + 1, step))
    return values

def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("wrong number of fields")
    sets = []
    for f, (lo, hi) in zip(fields, RANGES):
        if not f:
            raise ValueError("empty field")
        sets.append(_parse_field(f, lo, hi))
    minutes, hours, dom, mon, dow = sets

    # normalize dow: 7 -> 0
    dow = {0 if d == 7 else d for d in dow}

    dom_restricted = not fields[2].startswith('*')
    dow_restricted = not fields[3 + 1].startswith('*')  # fields[4]
    dow_restricted = not fields[4].startswith('*')

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    t += timedelta(minutes=1)
    limit = t + timedelta(days=8 * 366)

    day = t.date()
    while datetime.combine(day, datetime.min.time()) <= limit:
        if day.month in mon:
            m_dom = dom_restricted and day.day in dom
            m_dow = dow_restricted and day.weekday() in dow  # Monday=0; cron Sunday=0
            cron_dow = (day.weekday() + 1) % 7
            m_dow = dow_restricted and cron_dow in dow
            if dom_restricted and dow_restricted:
                day_ok = m_dom or m_dow
            else:
                day_ok = (not dom_restricted or m_dom) and (not dow_restricted or m_dow)
            if day_ok:
                for h in sorted(hours):
                    for m in sorted(minutes):
                        cand = datetime(day.year, day.month, day.day, h, m)
                        if cand >= t:
                            return cand.strftime("%Y-%m-%dT%H:%M")
        day += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

