    for p, (lo, hi) in zip(parts, RANGES):
        fields.append(_parse_field(p, lo, hi))
    minute_set, _ = fields[0]
    hour_set, _ = fields[1]
    dom_set, dom_star = fields[2]
    mon_set, _ = fields[3]
    dow_set, dow_star = fields[4]
    dow_set = {(d % 7) for d in dow_set}

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M") + timedelta(minutes=1)
    limit = t + timedelta(days=8 * 366 + 4)

    def day_matches(d):
        if d.month not in mon_set:
            return False
        dm = d.day in dom_set
        dw = ((d.weekday() + 1) % 7) in dow_set
        if not dom_star and not dow_star:
            return dm or dw
        return dm and dw

    cur = t
    while cur < limit:
        d = cur.date()
        if day_matches(d):
            day_start = datetime(d.year, d.month, d.day)
            m0 = cur.hour * 60 + cur.minute if cur.date() == t.date() and day_start == t.replace(hour=0, minute=0) else 0
            start_min = (t - day_start).total_seconds() // 60 if day_start <= t else 0
            start_min = int(start_min)
            if day_start > t:
                start_min = 0
            for m in range(start_min, 1440):
                if (m % 60) in minute_set and (m // 60) in hour_set:
                    cand = day_start + timedelta(minutes=m)
                    if cand > datetime.strptime(after, "%Y-%m-%dT%H:%M"):
                        return cand.strftime("%Y-%m-%dT%H:%M")
        cur = datetime(d.year, d.month, d.day) + timedelta(days=1)
