    dows = dows | {0} if 7 in dows else dows

    dom_restricted = not dom_field.startswith('*')
    dow_restricted = not dow_field.startswith('*')

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    limit = t + timedelta(days=8 * 366 + 2)

