        if d.month not in months:
            return False
        dm = d.day in doms
        dw = (d.weekday() + 1) % 7 in dows  # Monday=1 ... Sunday=0
        if dom_restricted and dow_restricted:
            return dm or dw
        if dom_restricted:
            return dm
        if dow_restricted:
            return dw
        return True

    d = t.date()
    first = True
    while d <= limit.date():
        if day_matches(d):
            if first:
                start_min = t.hour * 60 + t.minute + 1
            else:
                start_min = 0
            for m in range(start_min, 1440):
                if m % 60 in minutes and m // 60 in hours:
                    return (datetime(d.year, d.month, d.day) +
                            timedelta(minutes=m)).strftime("%Y-%m-%dT%H:%M")
        first = False
        d += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

