def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("wrong number of fields")
    mins = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    doms = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12)
    dows = _parse_field(fields[4], 0, 7)
    dows = {0 if d == 7 else d for d in dows}

    dom_star = fields[2].startswith('*')
    dow_star = fields[4].startswith('*')
    restricted_both = (not dom_star) and (not dow_star)

    try:
        t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after")
    t = t + timedelta(minutes=1)
    limit = t + timedelta(days=8 * 366)

    while t < limit:
        if t.month in months:
            dom_ok = t.day in doms
            dow_ok = (t.weekday() + 1) % 7 in dows
            day_match = (dom_ok or dow_ok) if restricted_both else (dom_ok and dow_ok)
            if day_match:
                h, m = t.hour, t.minute
                for hh in range(h, 24):
                    if hh not in hours:
                        continue
                    if hh == h:
                        candidates = [x for x in mins if x >= m]
                    else:
                        candidates = mins
                    if candidates:
                        cand = min(candidates)
                        return t.replace(hour=hh, minute=cand,
                                         second=0, microsecond=0).strftime("%Y-%m-%dT%H:%M")
        # move to next day 00:00
        t = (t + timedelta(days=1)).replace(hour=0, minute=0)
    raise ValueError("no matching time within 8 years")

