from datetime import datetime, date, timedelta


def _parse_field(field, lo, hi, is_dow=False):
    values = set()
    for item in field.split(','):
        step = 1
        base = item
        if '/' in item:
            parts = item.split('/')
            if len(parts) != 2:
                raise ValueError("bad item: " + item)
            base, step_s = parts
            if not step_s.isdigit():
                raise ValueError("bad step: " + item)
            step = int(step_s)
            if step == 0:
                raise ValueError("step 0")
        if base == '*':
            start, end = lo, hi
        else:
            parts = base.split('-')
            if len(parts) == 1:
                if '/' in item:
                    raise ValueError("bad item: " + item)
                if not parts[0].isdigit():
                    raise ValueError("bad value: " + item)
                v = int(parts[0])
                if v < lo or v > hi:
                    raise ValueError("out of range: " + item)
                values.add(0 if (is_dow and v == 7) else v)
                continue
            if len(parts) != 2:
                raise ValueError("bad item: " + item)
            a, b = parts
            if not (a.isdigit() and b.isdigit()):
                raise ValueError("bad item: " + item)
            start, end = int(a), int(b)
            if start > end or start < lo or end > hi:
                raise ValueError("bad range: " + item)
        for v in range(start, end + 1, step):
            values.add(0 if (is_dow and v == 7) else v)
    if not values:
        raise ValueError("empty field")
    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("need 5 fields")
    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    dom_field = fields[2]
    dom = _parse_field(dom_field, 1, 31)
    _parse_field(fields[3], 1, 12)  # months validated; used via per-day check
    months = _parse_field(fields[3], 1, 12)
    dow_field = fields[4]
    dow = _parse_field(dow_field, 0, 7, is_dow=True)

    dom_restricted = not dom_field.startswith('*')
    dow_restricted = not dow_field.startswith('*')

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    start_date = t.date()
    limit = date(start_date.year + 8, start_date.month, start_date.day)

    d = start_date
    one_day = timedelta(days=1)
    while d <= limit:
        if d.month in months:
            dm = d.day in dom
            dw = d.isoweekday() % 7 in dow  # Sunday(7)->0
            if dom_restricted and dow_restricted:
                day_ok = dm or dw
            else:
                day_ok = dm and dw
            if day_ok:
                for h in sorted(hours):
                    for m in sorted(minutes):
                        cand = datetime(d.year, d.month, d.day, h, m)
                        if cand > t:
                            return cand.strftime("%Y-%m-%dT%H:%M")
        d += one_day
    raise ValueError("no matching time within 8 years")

