def next_cron(expr: str, after: str) -> str:
    RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]

    def parse_field(field, lo, hi):
        star = field.startswith('*')
        values = set()
        for item in field.split(','):
            step = 1
            if '/' in item:
                base, step_s = item.split('/', 1)
                try:
                    step = int(step_s)
                except ValueError:
                    raise ValueError("bad step")
                if step <= 0:
                    raise ValueError("step 0")
            else:
                base = item
            if base == '*':
                a, b = lo, hi
            elif '-' in base:
                parts = base.split('-')
                if len(parts) != 2:
                    raise ValueError("bad range")
                try:
                    a, b = int(parts[0]), int(parts[1])
                except ValueError:
                    raise ValueError("bad number")
                if a > b:
                    raise ValueError("A > B")
            else:
                try:
                    a = b = int(base)
                except ValueError:
                    raise ValueError("bad number")
            if a < lo or b > hi:
                raise ValueError("out of range")
            values.update(range(a, b + 1, step))
        return star, values

    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("wrong number of fields")
    parsed = [parse_field(f, lo, hi) for f, (lo, hi) in zip(fields, RANGES)]
    dom_star, dom_set = parsed[2]
    dow_star, dow_set = parsed[4]
    # normalize sunday 7 -> 0
    dow_set = {0 if v == 7 else v for v in dow_set}

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M") + timedelta(minutes=1)
    end = t + timedelta(days=8 * 366 + 2)

    d = t.replace(hour=0, minute=0)
    # first day: handle partial day
    first = True
    while d < end:
        if (not dom_star and not dow_star):
            day_ok = (d.day in dom_set) or ((d.weekday() + 1) % 7 in dow_set)
        else:
            day_ok = (d.day in dom_set) and ((d.weekday() + 1) % 7 in dow_set)
        if day_ok:
            _, hour_set = parsed[1]
            _, min_set = parsed[0]
            if first:
                start_h, start_m = t.hour, t.minute
                first = False
            else:
                start_h, start_m = 0, 0
            for h in sorted(hour_set):
                if h < start_h:
                    continue
                for m in sorted(min_set):
                    if h == start_h and m < start_m:
                        continue
                    return d.replace(hour=h, minute=m).strftime("%Y-%m-%dT%H:%M")
        d += timedelta(days=1)
        first = False
    raise ValueError("no matching time within 8 years")

from datetime import datetime, timedelta


def _parse_field(spec, lo, hi):
    if not spec:
        raise ValueError("empty field")
    values = set()
    for item in spec.split(","):
        if not item:
            raise ValueError("empty item")
        step = 1
        if "/" in item:
            base, step_s = item.split("/", 1)
            if not step_s.isdigit():
                raise ValueError("bad step")
            step = int(step_s)
            if step == 0:
                raise ValueError("step 0")
        else:
            base = item
        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            a, b = base.split("-", 1)
            if not a.isdigit() or not b.isdigit():
                raise ValueError("bad range")
            start, end = int(a), int(b)
            if start > end:
                raise ValueError("A > B")
        else:
            if not base.isdigit():
                raise ValueError("bad value")
            start = end = int(base)
        if not (lo <= start <= hi) or not (lo <= end <= hi):
            raise ValueError("value out of range")
        values.update(range(start, end + 1, step))
    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split(" ")
    if len(fields) != 5:
        raise ValueError("wrong number of fields")
    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    dom = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12)
    dow = _parse_field(fields[4], 0, 7)
    dow = {d % 7 for d in dow}

    dom_star = fields[2].startswith("*")
    dow_star = fields[4].startswith("*")

    try:
        t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after")

    start = t + timedelta(minutes=1)
    mod = start.hour * 60 + start.minute
    mods = sorted(h * 60 + m for h in hours for m in minutes)

    day = start.date()
    end = start + timedelta(days=8 * 366 + 5)
    while day <= end.date():
        if day.month in months:
            cdom = day.day
            cdow = (day.weekday() + 1) % 7
            if dom_star and dow_star:
                ok = True
            elif not dom_star and not dow_star:
                ok = cdom in dom or cdow in dow
            elif dom_star:
                ok = cdow in dow
            else:
                ok = cdom in dom
            if ok:
                if day == start.date():
                    cand = [x for x in mods if x > mod]
                else:
                    cand = mods
                if cand:
                    x = cand[0]
                    return "%04d-%02d-%02dT%02d:%02d" % (
                        day.year, day.month, day.day, x // 60, x % 60)
        day += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

