        if dom_restricted:
            return dm
        if dow_restricted:
            return dw
        return True

    d = t.replace(hour=0, minute=0)
    first = True
    while d < limit:
        if day_matches(d):
            if first:
                start_h, start_m = t.hour, t.minute
            else:
