    if not s:
        raise ValueError("empty field")
    vals = set()
    for item in s.split(','):
        if item.count('/') > 1:
            raise ValueError("bad item")
        if '/' in item:
            base, step_s = item.split('/')
            try:
                step = int(step_s)
            except ValueError:
                raise ValueError("bad step")
            if step <= 0:
                raise ValueError("step must be >= 1")
        else:
            base, step = item, 1
        if base == '*':
            a, b = lo, hi
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError("bad range")
            try:
                a, b = int(parts[0]), int(parts[1])
            except ValueError:
                raise ValueError("bad number")
        else:
            try:
                a = b = int(base)
            except ValueError:
                raise ValueError("bad number")
        if not (lo <= a <= hi) or not (lo <= b <= hi) or a > b:
            raise ValueError("value out of range")
        vals.update(range(a, b + 1, step))
    if not vals:
        raise ValueError("empty field")
    return vals


def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("need exactly 5 fields")
    minute_f, hour_f, dom_f, mon_f, dow_f = fields

    minutes = _parse_field(minute_f, 0, 59)
    hours = _parse_field(hour_f, 0, 23)
    doms = _parse_field(dom_f, 1, 31)
    months = _parse_field(mon_f, 1, 12)
    dows_raw = _parse_field(dow_f, 0, 7)
    # cron: 0/7 = Sunday, 1 = Monday; Python weekday(): Monday=0 .. Sunday=6
    dows = {(d - 1) % 7 for d in dows_raw}

    dom_star = dom_f.startswith('*')
    dow_star = dow_f.startswith('*')
    both_restricted = (not dom_star) and (not dow_star)

    try:
        t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after format")

    hm_list = [(h, m) for h in sorted(hours) for m in sorted(minutes)]

    day = t.date()
    end = day + timedelta(days=366 * 8 + 2)

    while day <= end:
        if day.month in months:
            dom_ok = day.day in doms
            dow_ok = day.weekday() in dows
            if both_restricted:
                day_ok = dom_ok or dow_ok
            else:
                day_ok = dom_ok and dow_ok
            if day_ok:
                if day == t.date():
                    tod = t.hour * 60 + t.minute
                    for h, m in hm_list:
                        if h * 60 + m > tod:
                            return f"{day.isoformat()}T{h:02d}:{m:02d}"
                else:
                    h, m = hm_list[0]
                    return f"{day.isoformat()}T{h:02d}:{m:02d}"
        day += timedelta(days=1)

    raise ValueError("no matching time within 8 years")

from datetime import datetime, timedelta

RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _parse_field(field, lo, hi):
    values = set()
    for item in field.split(','):
        if not item:
            raise ValueError("empty field item")
        if item.startswith('*'):
            rest = item[1:]
            step = 1
            if rest == '':
                pass
            elif rest.startswith('/'):
                step = int(rest[1:])
                if step <= 0:
                    raise ValueError("step must be >= 1")
            else:
                raise ValueError("bad item after *")
            values.update(range(lo, hi + 1, step))
        elif '/' in item:
            base, step_s = item.split('/', 1)
            step = int(step_s)
            if step <= 0:
                raise ValueError("step must be >= 1")
            if '-' in base:
                a, b = base.split('-', 1)
                a, b = int(a), int(b)
            else:
                a, b = int(base), int(base)
            if a < lo or b > hi or a > b:
                raise ValueError("range out of bounds")
            values.update(range(a, b + 1, step))
        elif '-' in item:
            a, b = item.split('-', 1)
            a, b = int(a), int(b)
            if a < lo or b > hi or a > b:
                raise ValueError("range out of bounds")
            values.update(range(a, b + 1))
        else:
            v = int(item)
            if v < lo or v > hi:
                raise ValueError("value out of range")
            values.add(v)
    if not values:
        raise ValueError("empty field")
    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("need exactly 5 fields")
    minutes = _parse_field(fields[0], 0, 59)
    hours = _parse_field(fields[1], 0, 23)
    doms = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12)
    dows = _parse_field(fields[4], 0, 7)
    dows = {d % 7 for d in dows}

    dom_star = fields[2].startswith('*')
    dow_star = fields[4].startswith('*')

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    limit = t + timedelta(days=8 * 366)

    day = t.date()
    first_day = True
    while day <= limit.date():
        if day.month in months:
            dm = day.day in doms
            cw = (day.weekday() + 1) % 7 in dows
            if not dom_star and not dow_star:
                day_ok = dm or cw
            else:
                day_ok = dm and cw
            if day_ok:
                if first_day:
                    # need strictly after t
                    for h in sorted(hours):
                        if h < t.hour:
                            continue
                        for m in sorted(minutes):
                            cand = day.replace()  # placeholder
                            dt = datetime(day.year, day.month, day.day, h, m)
                            if dt > t:
                                return dt.strftime("%Y-%m-%dT%H:%M")
                else:
                    h = min(hours)
                    m = min(minutes)
                    return datetime(day.year, day.month, day.day, h, m).strftime("%Y-%m-%dT%H:%M")
        day += timedelta(days=1)
        first_day = False
    raise ValueError("no matching time within 8 years")

