import datetime as dt

RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]

def _parse_field(field, lo, hi):
    if not field:
        raise ValueError("empty field")
    vals = set()
    for item in field.split(","):
        if item == "":
            raise ValueError("empty item")
        step = 1
        if "/" in item:
            base, s = item.split("/", 1)
            if not s.isdigit():
                raise ValueError("bad step")
            step = int(s)
            if step == 0:
                raise ValueError("step 0")
        else:
            base = item
        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            a, b = base.split("-", 1)
            if not (a.isdigit() and b.isdigit()):
                raise ValueError("bad range")
            start, end = int(a), int(b)
            if start < lo or end > hi or start > end:
                raise ValueError("out of range")
        else:
            if not base.isdigit():
                raise ValueError("bad value")
            start = end = int(base)
            if start < lo or start > hi:
                raise ValueError("out of range")
        vals.update(range(start, end + 1, step))
    return vals

def next_cron(expr: str, after: str) -> str:
    parts = expr.split(" ")
    if len(parts) != 5:
        raise ValueError("need 5 fields")
    mins = _parse_field(parts[0], 0, 59)
    hrs = _parse_field(parts[1], 0, 23)
    doms = _parse_field(parts[2], 1, 31)
    mons = _parse_field(parts[3], 1, 12)
    dows = _parse_field(parts[4], 0, 7)
    dows = {0 if d == 7 else d for d in dows}

    dom_star = parts[2].startswith("*")
    dow_star = parts[4].startswith("*")
    both_star = dom_star and dow_star
    either = (not dom_star) and (not dow_star)

    t = dt.datetime.strptime(after, "%Y-%m-%dT%H:%M")
    limit = t + dt.timedelta(days=8 * 366)

    day = (t + dt.timedelta(days=1)).replace(hour=0, minute=0)
    # first: check remainder of the starting day
    candidates_days = [t.replace(hour=0, minute=0), day]

    def day_matches(d):
        if d.month not in mons:
            return False
        dm = d.day in doms
        dw = (d.weekday() + 1) % 7 in dows  # Monday=1..Sunday=0
        if either:
            return dm or dw
        if both_star:
            return dm and dw
        return dm and dw if (dom_star or dow_star) else (dm and dw)

    def day_matches2(d):
        if d.month not in mons:
            return False
        dm = d.day in doms
        dw = (d.weekday() + 1) % 7 in dows
        if either:
            return dm or dw
        return dm and dw

    for start in candidates_days:
        if start > t or start < t.replace(hour=0, minute=0):
            continue
        if day_matches2(start):
            for h in sorted(hrs):
                for m in sorted(mins):
                    cand = start.replace(hour=h, minute=m)
                    if cand > t:
                        return cand.strftime("%Y-%m-%dT%H:%M")

    d = day
    while d <= limit:
        if day_matches2(d):
            for h in sorted(hrs):
                for m in sorted(mins):
                    return d.replace(hour=h, minute=m).strftime("%Y-%m-%dT%H:%M")
        d += dt.timedelta(days=1)
    raise ValueError("no matching time within 8 years")

