_RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _parse_field(field, lo, hi):
    """Return (set_of_values, starts_with_star)."""
    if not field:
        raise ValueError("empty field")
    starts_with_star = field.startswith("*")
    values = set()
    for item in field.split(","):
        if not item:
            raise ValueError("empty item")
        step = 1
        body = item
        if "/" in item:
            body, step_s = item.split("/", 1)
            if not step_s.isdigit():
                raise ValueError("bad step")
            step = int(step_s)
            if step == 0:
                raise ValueError("step 0")
        if body == "*":
            a, b = lo, hi
        elif "-" in body:
            parts = body.split("-")
            if len(parts) != 2:
                raise ValueError("bad range")
            a_s, b_s = parts
            if not a_s.isdigit() or not b_s.isdigit():
                raise ValueError("bad range")
            a, b = int(a_s), int(b_s)
            if a > b:
                raise ValueError("A > B")
        else:
            if not body.isdigit():
                raise ValueError("bad value")
            a = b = int(body)
        if a < lo or b > hi:
            raise ValueError("out of range")
        values.update(range(a, b + 1, step))
    return values, starts_with_star


def next_cron(expr: str, after: str) -> str:
    fields = expr.split(" ")
    if len(fields) != 5:
        raise ValueError("wrong number of fields")
    parsed = [_parse_field(f, lo, hi) for f, (lo, hi) in zip(fields, _RANGES)]
    minutes, _ = parsed[0]
    hours, _ = parsed[1]
    doms, dom_star = parsed[2]
    months, _ = parsed[3]
    dows, dow_star = parsed[4]
    dows = {0 if d == 7 else d for d in dows}

    try:
        t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after")

    limit = t + timedelta(days=8 * 366)

    # advance to first candidate minute strictly after t
    cur = t + timedelta(minutes=1)

    day = cur.replace(hour=0, minute=0)
    first_day = True
    while day <= limit:
        if day.month in months:
            dom_ok = day.day in doms
            dow_ok = day.isoweekday() % 7 in dows  # Mon=1..Sun=7 -> Sun=0
            if dom_star and dow_star:
                day_matches = dom_ok and dow_ok
            elif not dom_star and not dow_star:
                day_matches = dom_ok or dow_ok
            else:
                day_matches = dom_ok and dow_ok
            if day_matches:
                start_min = cur.hour * 60 + cur.minute if first_day else 0
                for m in range(start_min, 1440):
                    if m % 60 in minutes and m // 60 in hours:
                        return (day + timedelta(minutes=m)).strftime("%Y-%m-%dT%H:%M")
        day += timedelta(days=1)
        first_day = False
    raise ValueError("no matching time within 8 years")

