RANGES = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]


def _parse_field(field, lo, hi):
    if not field:
        raise ValueError("empty field")
    values = set()
    for item in field.split(","):
        if not item:
            raise ValueError("empty item")
        step = 1
        if "/" in item:
            base, step_s = item.split("/", 1)
            try:
                step = int(step_s)
            except ValueError:
                raise ValueError("bad step")
            if step < 1:
                raise ValueError("step must be >= 1")
        else:
            base = item
        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            parts = base.split("-")
            if len(parts) != 2:
                raise ValueError("bad range")
            try:
                start, end = int(parts[0]), int(parts[1])
            except ValueError:
                raise ValueError("bad number")
            if start < lo or end > hi or start > end:
                raise ValueError("range out of bounds")
        else:
            try:
                start = int(base)
            except ValueError:
                raise ValueError("bad number")
            if start < lo or start > hi:
                raise ValueError("value out of range")
            end = start
        values.update(range(start, end + 1, step))
    return values


def _parse(expr):
    fields = expr.split(" ")
    if len(fields) != 5:
        raise ValueError("need 5 fields")
    sets = []
    for f, (lo, hi) in zip(fields, RANGES):
        sets.append(_parse_field(f, lo, hi))
    # normalize dow: 7 -> 0
    sets[4] = {0 if v == 7 else v for v in sets[4]}
    dom_star = fields[2].startswith("*")
    dow_star = fields[4].startswith("*")
    return sets, dom_star, dow_star


def next_cron(expr: str, after: str) -> str:
    sets, dom_star, dow_star = _parse(expr)
    minutes, hours, doms, months, dows = sets

    try:
        t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad time format")

    t = t + timedelta(minutes=1)
    limit = t + timedelta(days=8 * 366 + 2)

    day = t.replace(hour=0, minute=0)
    while day < limit:
        if day.month in months:
            dom_ok = day.day in doms
            dow_ok = day.isoweekday() % 7 in dows
            if dom_star and dow_star:
                day_ok = True
            elif not dom_star and not dow_star:
                day_ok = dom_ok or dow_ok
            elif dom_star:
                day_ok = dow_ok
            else:
                day_ok = dom_ok
            if day_ok:
                # find first matching minute >= t on this day
                if day.date() == t.date():
                    start_h, start_m = t.hour, t.minute
                else:
                    start_h, start_m = 0, 0
                for h in sorted(hours):
                    if h < start_h:
                        continue
                    if h == start_h:
                        cand = [m for m in minutes if m >= start_m]
                    else:
                        cand = sorted(minutes)
                    if cand:
                        m = min(cand)
                        return day.strftime("%Y-%m-%dT") + f"{h:02d}:{m:02d}"
        day += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

