def next_cron(expr: str, after: str) -> str:
    fields = expr.split(" ")
    if len(fields) != 5:
        raise ValueError("wrong number of fields")

    ranges = [(0, 59), (0, 23), (1, 31), (1, 12), (0, 7)]

    def parse_field(text, lo, hi):
        vals = set()
        for item in text.split(","):
            step = 1
            if "/" in item:
                base, step_s = item.split("/", 1)
                if not step_s.isdigit():
                    raise ValueError("bad step")
                step = int(step_s)
                if step == 0:
                    raise ValueError("step 0")
            else:
                base = item
            if base == "*":
                start, end = lo, hi
            elif "-" in base:
                a, b = base.split("-", 1)
                if not (a.isdigit() and b.isdigit()):
                    raise ValueError("bad range")
                start, end = int(a), int(b)
                if start > end:
                    raise ValueError("A > B")
            else:
                if not base.isdigit():
                    raise ValueError("bad value")
                start = end = int(base)
            if not (lo <= start <= hi and lo <= end <= hi):
                raise ValueError("out of range")
            vals.update(range(start, end + 1, step))
        return vals

    minutes = parse_field(fields[0], 0, 59)
    hours = parse_field(fields[1], 0, 23)
    dom_vals = parse_field(fields[2], 1, 31)
    months = parse_field(fields[3], 1, 12)
    dow_vals = parse_field(fields[4], 0, 7)
    dow_vals = dow_vals | ({7} if 7 in dow_vals else set()) | ({0} if 7 in dow_vals else set())

    dom_restricted = not fields[2].startswith("*")
    dow_restricted = not fields[4].startswith("*")

    t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    t = t + timedelta(minutes=1)
    day = t.replace(hour=0, minute=0)
    limit = day + timedelta(days=366 * 8 + 2)

    while day <= limit:
        if day.month in months:
            dom_ok = day.day in dom_vals
            dow_ok = (day.weekday() + 1) % 7 in dow_vals  # Mon=1..Sun=0
            if dom_restricted and dow_restricted:
                day_ok = dom_ok or dow_ok
            else:
                day_ok = dom_ok and dow_ok
            if day_ok:
                for h in sorted(hours):
                    for m in sorted(minutes):
                        cand = day.replace(hour=h, minute=m)
                        if cand > t - timedelta(minutes=1) and cand > datetime.strptime(after, "%Y-%m-%dT%H:%M"):
                            return cand.strftime("%Y-%m-%dT%H:%M")
        day += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

