            start, end = lo, hi
        elif '-' in base:
            parts = base.split('-')
            if len(parts) != 2:
                raise ValueError("bad range")
            try:
                start, end = int(parts[0]), int(parts[1])
            except ValueError:
                raise ValueError("bad range")
            if not (lo <= start <= hi and lo <= end <= hi):
                raise ValueError("value out of range")
            if start > end:
                raise ValueError("A > B")
        else:
            try:
                start = end = int(base)
            except ValueError:
                raise ValueError("bad value")
            if not (lo <= start <= hi):
                raise ValueError("value out of range")
        values.update(range(start, end + 1, step))
    return values


def next_cron(expr: str, after: str) -> str:
    fields = expr.split(' ')
    if len(fields) != 5:
        raise ValueError("need exactly 5 fields")
    parsed = []
    for f, (lo, hi) in zip(fields, _RANGES):
        parsed.append(_parse_field(f, lo, hi))
    minutes, hours, doms, months, dows = parsed

    try:
        t = datetime.strptime(after, "%Y-%m-%dT%H:%M")
    except ValueError:
        raise ValueError("bad after format")

    def day_matches(d):
        cron_dow = (d.weekday() + 1) % 7  # Monday=0 -> cron 1; Sunday -> 0
        dom_ok = d.day in doms
        dow_ok = cron_dow in dows
        dom_star = fields[2].startswith('*')
        dow_star = fields[4].startswith('*')
        if not dom_star and not dow_star:
            return dom_ok or dow_ok
        return dom_ok and dow_ok

    limit = t + timedelta(days=8 * 366 + 2)
    d = t.date()
    while d <= limit.date():
        if day_matches(d):
            base = datetime(d.year, d.month, d.day)
            for m in range(1440):
                cand = base + timedelta(minutes=m)
                if cand <= t:
                    continue
                if cand.minute in minutes and cand.hour in hours:
                    return cand.strftime("%Y-%m-%dT%H:%M")
        d += timedelta(days=1)
    raise ValueError("no matching time within 8 years")

from fractions import Fraction

def evaluate(expr: str) -> str:
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError("bad character")
    pos = [0]

    def peek():
        return tokens[pos[0]][0] if pos[0] < len(tokens) else None

    def next_tok():
        t = tokens[pos[0]][0]
        pos[0] += 1
        return t

    def parse_expr():
        v = parse_term()
        while peek() in ('+', '-'):
            op = next_tok()
            w = parse_term()
            v = v + w if op == '+' else v - w
        return v

    def parse_term():
        v = parse_unary()
        while peek() in ('*', '/'):
            op = next_tok()
            w = parse_unary()
            if op == '*':
                v = v * w
            else:
                if w == 0:
                    raise ZeroDivisionError
                v = v / w
        return v

    def parse_unary():
        if peek() in ('+', '-'):
            op = next_tok()
            v = parse_unary()
            return v if op == '+' else -v
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            next_tok()
            exp = parse_unary()  # right-assoc; exponent may have unary sign
            if exp.denominator != 1:
                raise ValueError("non-integer exponent")
            e = exp.numerator
            if e < 0 and base == 0:
                raise ZeroDivisionError
            return Fraction(base) ** e
        return base

    def parse_atom():
        t = peek()
        if t == 'num':
            return Fraction(next_tok_val := tokens[pos[0]][1]) if False else (pos.__setitem__(0, pos[0] + 1), Fraction(tokens[pos[0] - 1][1]))[1]
        if t == '(':
            next_tok()
            v = parse_expr()
            if peek() != ')':
                raise ValueError("missing )")
            next_tok()
            return v
        raise ValueError("missing operand")

    if not tokens:
        raise ValueError("empty")
    result = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("trailing tokens")
    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"

