def evaluate(expr: str) -> str:
    s = expr
    n = len(s)
    i = 0  # position

    def skip():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def peek():
        skip()
        return s[i] if i < n else None

    def parse_expr():
        # + and -
        val = parse_term()
        while True:
            c = peek()
            if c in ('+', '-'):
                nonlocal i
                i += 1
                rhs = parse_term()
                val = val + rhs if c == '+' else val - rhs
            else:
                return val

    def parse_term():
        val = parse_unary()
        while True:
            c = peek()
            if c in ('*', '/'):
                nonlocal i
                i += 1
                rhs = parse_unary()
                if c == '*':
                    val = val * rhs
                else:
                    if rhs == 0:
                        raise ZeroDivisionError("division by zero")
                    val = val / rhs
            else:
                return val

    def parse_unary():
        c = peek()
        if c == '-':
            nonlocal i
            i += 1
            return -parse_unary()
        if c == '+':
            i += 1
            return parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        c = peek()
        if c == '^':
            nonlocal i
            i += 1
            exp = parse_unary()  # exponent may start with unary sign
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if e < 0 and base == 0:
                raise ZeroDivisionError("0 to negative power")
            return base ** e
        return base

    def parse_atom():
        nonlocal i
        c = peek()
        if c == '(':
            i += 1
            val = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses")
            i += 1
            return val
        if c is not None and c.isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            return Fraction(int(s[start:i]))
        raise ValueError("missing operand")

    result = parse_expr()
    if peek() is not None:
        raise ValueError("unexpected trailing input")
    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"

