        t = tokens[pos[0]]
        pos[0] += 1
        return t

    def expect(t):
        if peek() != t:
            raise ValueError("expected " + t)
        next_tok()

    def parse_expr():
        v = parse_term()
        while peek() in ('+', '-'):
            op = next_tok()[0]
            w = parse_term()
            v = v + w if op == '+' else v - w
        return v

    def parse_term():
        v = parse_unary()
        while peek() in ('*', '/'):
            op = next_tok()[0]
            w = parse_unary()
            if op == '*':
