            exp = parse_unary()  # right-assoc, exponent may have unary sign
            if exp.denominator != 1:
                raise ValueError("exponent must be integer")
            e = int(exp)
            if e < 0 and base == 0:
                raise ZeroDivisionError("0 to negative power")
            return base ** e
        return base

    def parse_atom():
        t = peek()
        if t == 'num':
            return Fraction(next_tok()[1])
        if t == '(':
            next_tok()
            v = parse_expr()
            expect(')')
            return v
        raise ValueError("missing operand")

    if not tokens:
        raise ValueError("empty expression")
    v = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("unexpected token")
    if v.denominator == 1:
        return str(v.numerator)
    return f"{v.numerator}/{v.denominator}"

