    pos = [0]

    def peek():
        return tokens[pos[0]][0] if pos[0] < len(tokens) else None

    def take():
        t = tokens[pos[0]]
        pos[0] += 1
        return t

    def parse_expr():
        v = parse_term()
        while peek() in ('+', '-'):
            op = take()[0]
            w = parse_term()
            v = v + w if op == '+' else v - w
        return v

    def parse_term():
        v = parse_unary()
        while peek() in ('*', '/'):
            op = take()[0]
            w = parse_unary()
            if op == '*':
                v = v * w
            else:
                if w == 0:
                    raise ZeroDivisionError("division by zero")
                v = v / w
        return v

    def parse_unary():
        if peek() in ('+', '-'):
            op = take()[0]
            v = parse_unary()
            return v if op == '+' else -v
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            take()
            exp = parse_unary()  # right-assoc, exponent may have unary sign
            if exp.denominator != 1:
                raise ValueError("non-integer exponent")
            e = exp.numerator
            if e < 0:
                if base == 0:
                    raise ZeroDivisionError("zero to negative power")
                return Fraction(base) ** e
            return Fraction(base) ** e
        return base

    def parse_atom():
        t = peek()
        if t == 'num':
            return Fraction(take()[1])
        if t == '(':
            take()
            v = parse_expr()
            if peek() != ')':
                raise ValueError("missing )")
            take()
            return v
        raise ValueError("missing operand")

    if not tokens:
        raise ValueError("empty expression")
    v = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("trailing tokens")
    if v.denominator == 1:
        return str(v.numerator)
    return f"{v.numerator}/{v.denominator}"

