def evaluate(expr: str) -> str:
    s = expr
    n = len(s)
    i = 0

    def skip():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def peek():
        skip()
        return s[i] if i < n else ''

    def parse_expr():
        # + and - (lowest precedence)
        left = parse_term()
        while True:
            c = peek()
            if c and c in '+-':
                nonlocal i
                i += 1
                right = parse_term()
                left = left + right if c == '+' else left - right
            else:
                return left

    def parse_term():
        left = parse_unary()
        while True:
            c = peek()
            if c and c in '*/':
                nonlocal i
                i += 1
                right = parse_unary()
                if c == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError
                    left = left / right
            else:
                return left

    def parse_unary():
        c = peek()
        if c and c in '+-':
            nonlocal i
            i += 1
            v = parse_unary()
            return v if c == '+' else -v
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            nonlocal i
            i += 1
            exp = parse_unary()  # exponent may start with unary sign; right-assoc
            if exp.denominator != 1:
                raise ValueError
            e = exp.numerator
            if e < 0:
                if base == 0:
                    raise ZeroDivisionError
                return Fraction(base.denominator, base.numerator) ** (-e)
            return base ** e
        return base

    def parse_atom():
        c = peek()
        if c == '(':
            nonlocal i
            i += 1
            v = parse_expr()
            if peek() != ')':
                raise ValueError
            i += 1
            return v
        if c and c.isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            return Fraction(int(s[start:i]))
        raise ValueError

    result = parse_expr()
    if peek() != '':
        raise ValueError
    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"

