def evaluate(expr: str) -> str:
    s = expr
    n = len(s)
    i = 0

    def skip():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def peek():
        skip()
        return s[i] if i < n else None

    def parse_expr():
        v = parse_term()
        while True:
            c = peek()
            if c == '+':
                nonlocal_step(1)
                v += parse_term()
            elif c == '-':
                nonlocal_step(1)
                v -= parse_term()
            else:
                return v

    def nonlocal_step(k):
        nonlocal i
        i += k

    def parse_term():
        v = parse_unary()
        while True:
            c = peek()
            if c == '*':
                nonlocal_step(1)
                v *= parse_unary()
            elif c == '/':
                nonlocal_step(1)
                d = parse_unary()
                if d == 0:
                    raise ZeroDivisionError
                v /= d
            else:
                return v

    def parse_unary():
        c = peek()
        if c == '-':
            nonlocal_step(1)
            return -parse_unary()
        if c == '+':
            nonlocal_step(1)
            return parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        c = peek()
        if c == '^':
            nonlocal_step(1)
            exp = parse_unary()  # right-assoc; exponent may have unary sign
            if exp.denominator != 1:
                raise ValueError("non-integer exponent")
            e = exp.numerator
            if e < 0 and base == 0:
                raise ZeroDivisionError
            return base ** e
        return base

    def parse_atom():
        c = peek()
        if c == '(':
            nonlocal_step(1)
            v = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses")
            nonlocal_step(1)
            return v
        if c is not None and c.isdigit():
            j = i
            while j < n and s[j].isdigit():
                j += 1
            num = int(s[i:j])
            nonlocal_step(j - i)
            return Fraction(num)
        raise ValueError("missing operand")

    result = parse_expr()
    if peek() is not None:
        raise ValueError("unexpected trailing input")
    r = result
    if r.denominator == 1:
        return str(r.numerator)
    return f"{r.numerator}/{r.denominator}"

