class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos][0] if self.pos < len(self.tokens) else None

    def next(self):
        tok = self.tokens[self.pos]
        self.pos += 1
        return tok

    def expect(self, kind):
        if self.peek() != kind:
            raise ValueError(f"expected {kind!r}")
        return self.next()

    def parse_expr(self):
        return self.parse_add()

    def parse_add(self):
        value = self.parse_mul()
        while self.peek() in ('+', '-'):
            op = self.next()[0]
            rhs = self.parse_mul()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_mul(self):
        value = self.parse_unary()
        while self.peek() in ('*', '/'):
            op = self.next()[0]
            rhs = self.parse_unary()
            if op == '*':
                value = value * rhs
            else:
                if rhs == 0:
                    raise ZeroDivisionError("division by zero")
                value = value / rhs
        return value

    def parse_unary(self):
        if self.peek() in ('+', '-'):
            op = self.next()[0]
            value = self.parse_unary()
            return value if op == '+' else -value
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self.peek() == '^':
            self.next()
            exponent = self.parse_unary_signed_exponent()
            if exponent.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exponent.numerator
            if e < 0 and base == 0:
                raise ZeroDivisionError("zero raised to a negative power")
            return base ** e
        return base

    def parse_unary_signed_exponent(self):
        # exponent may start with unary signs, then a power-level expression
        if self.peek() in ('+', '-'):
            op = self.next()[0]
            value = self.parse_unary_signed_exponent()
            return value if op == '+' else -value
        return self.parse_power()

    def parse_atom(self):
        tok = self.peek()
        if tok == 'num':
            return Fraction(self.next()[1])
        if tok == '(':
            self.next()
            value = self.parse_expr()
            self.expect(')')
            return value
        raise ValueError("expected operand")


