def evaluate(expr: str) -> str:
    s = expr
    n = len(s)
    pos = 0

    def peek():
        nonlocal pos
        while pos < n and s[pos].isspace():
            pos += 1
        return s[pos] if pos < n else None

    def parse_expr():
        nonlocal pos
        v = parse_term()
        while True:
            c = peek()
            if c == '+':
                pos += 1
                v += parse_term()
            elif c == '-':
                pos += 1
                v -= parse_term()
            else:
                return v

    def parse_term():
        nonlocal pos
        v = parse_unary()
        while True:
            c = peek()
            if c == '*':
                pos += 1
                v *= parse_unary()
            elif c == '/':
                pos += 1
                d = parse_unary()
                if d == 0:
                    raise ZeroDivisionError("division by zero")
                v /= d
            else:
                return v

    def parse_unary():
        nonlocal pos
        c = peek()
        if c == '-':
            pos += 1
            return -parse_unary()
        if c == '+':
            pos += 1
            return parse_unary()
        return parse_power()

    def parse_power():
        nonlocal pos
        base = parse_atom()
        c = peek()
        if c == '^':
            pos += 1
            exp = parse_unary()
            if exp.denominator != 1:
                raise ValueError("exponent must be an integer")
            e = exp.numerator
            if e < 0 and base == 0:
                raise ZeroDivisionError("zero to a negative power")
            return base ** e
        return base

    def parse_atom():
        nonlocal pos
        c = peek()
        if c == '(':
            pos += 1
            v = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses")
            pos += 1
            return v
        if c is not None and c.isdigit():
            start = pos
            while pos < n and s[pos].isdigit():
                pos += 1
            return Fraction(int(s[start:pos]))
        raise ValueError("syntax error")

    result = parse_expr()
    if peek() is not None:
        raise ValueError("syntax error")
    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"

