from fractions import Fraction

def evaluate(expr: str) -> str:
    tokens = []
    i = 0
    while i < len(expr):
        c = expr[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < len(expr) and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
        elif c in '+-*/^()':
            tokens.append((c, c))
            i += 1
        else:
            raise ValueError("bad character")
    pos = [0]

    def peek():
        return tokens[pos[0]][0] if pos[0] < len(tokens) else None

    def next_tok():
        t = tokens[pos[0]][0]
        pos[0] += 1
        return t

    def parse_expr():
        v = parse_term()
        while peek() in ('+', '-'):
            op = next_tok()
            w = parse_term()
            v = v + w if op == '+' else v - w
        return v

    def parse_term():
        v = parse_unary()
        while peek() in ('*', '/'):
            op = next_tok()
            w = parse_unary()
            if op == '*':
                v = v * w
            else:
                if w == 0:
                    raise ZeroDivisionError
                v = v / w
        return v

    def parse_unary():
        if peek() in ('+', '-'):
            op = next_tok()
            v = parse_unary()
            return v if op == '+' else -v
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            next_tok()
            exp = parse_unary()  # right-assoc, exponent may have unary sign
            if exp.denominator != 1:
                raise ValueError("non-integer exponent")
            e = exp.numerator
            if e < 0 and base == 0:
                raise ZeroDivisionError
            return Fraction(base ** e) if e >= 0 else Fraction(1) / (base ** (-e))
        return base

    def parse_atom():
        t = peek()
        if t == 'num':
            next_tok()
            return Fraction(tokens[pos[0] - 1][1])
        if t == '(':
            next_tok()
            v = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parens")
            next_tok()
            return v
        raise ValueError("missing operand")

    if not tokens:
        raise ValueError("empty")
    v = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("trailing tokens")
    if v.denominator == 1:
        return str(v.numerator)
    return f"{v.numerator}/{v.denominator}"

