def evaluate(expr: str) -> str:
    s = expr
    n = len(s)
    i = 0  # position

    def skip():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def peek():
        skip()
        return s[i] if i < n else None

    def advance():
        nonlocal i
        skip()
        i += 1

    def parse_expr():  # + -
        left = parse_term()
        while True:
            c = peek()
            if c in ('+', '-'):
                advance()
                right = parse_term()
                left = left + right if c == '+' else left - right
            else:
                return left

    def parse_term():  # * /
        left = parse_unary()
        while True:
            c = peek()
            if c in ('*', '/'):
                advance()
                right = parse_unary()
                if c == '*':
                    left = left * right
                else:
                    if right == 0:
                        raise ZeroDivisionError
                    left = left / right
            else:
                return left

    def parse_unary():
        c = peek()
        if c == '-':
            advance()
            return -parse_unary()
        if c == '+':
            advance()
            return parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            advance()
            exp = parse_unary()  # exponent may have unary sign; right-assoc via recursion
            if exp.denominator != 1:
                raise ValueError
            e = exp.numerator
            if e < 0 and base == 0:
                raise ZeroDivisionError
            return Fraction(base) ** e
        return base

    def parse_atom():
        nonlocal i
        c = peek()
        if c == '(':
            advance()
            v = parse_expr()
            if peek() != ')':
                raise ValueError
            advance()
            return v
        if c is not None and c.isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            return Fraction(int(s[start:i]))
        raise ValueError

    def parse():
        v = parse_expr()
        skip()
        if i != n:
            raise ValueError
        return v

    result = parse()
    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"

