            return Fraction(t)
        raise ValueError("syntax error")

    if not tokens:
        raise ValueError("empty expression")
    result = parse_expr()
    if pos[0] != len(tokens):
        raise ValueError("syntax error")
    if result.denominator == 1:
        return str(result.numerator)
    return f"{result.numerator}/{result.denominator}"


def tokenize(s):
    tokens = []
    i = 0
    while i < len(s):
        c = s[i]
        if c.isspace():
            i += 1
        elif c.isdigit():
            j = i
            while j < len(s) and s[j].isdigit():
                j += 1
            tokens.append(int(s[i:j]))
            i = j
        elif c in '+-*/^()':
            tokens.append(c)
            i += 1
        else:
            raise ValueError("invalid character")
    return tokens

from fractions import Fraction

def evaluate(expr: str) -> str:
    s = expr
    n = len(s)
    i = 0

    def skip():
        nonlocal i
        while i < n and s[i].isspace():
            i += 1

    def peek():
        skip()
        return s[i] if i < n else None

    def advance():
        nonlocal i
        skip()
        i += 1

    def parse_expr():
        v = parse_term()
        while True:
            c = peek()
            if c == '+':
                advance()
                v += parse_term()
            elif c == '-':
                advance()
                v -= parse_term()
            else:
                return v

    def parse_term():
        v = parse_unary()
        while True:
            c = peek()
            if c == '*':
                advance()
                v *= parse_unary()
            elif c == '/':
                advance()
                d = parse_unary()
                if d == 0:
                    raise ZeroDivisionError
                v /= d
            else:
                return v

    def parse_unary():
        c = peek()
        if c == '-':
            advance()
            return -parse_unary()
        if c == '+':
            advance()
            return parse_unary()
        return parse_power()

    def parse_power():
        base = parse_atom()
        if peek() == '^':
            advance()
            exp = parse_unary()
            if exp.denominator != 1:
                raise ValueError("non-integer exponent")
            e = exp.numerator
            if e < 0 and base == 0:
                raise ZeroDivisionError
            if e >= 0:
                return Fraction(base ** e)
            return Fraction(base) ** e
        return base

    def parse_atom():
        nonlocal i
        c = peek()
        if c == '(':
            advance()
            v = parse_expr()
            if peek() != ')':
                raise ValueError("unbalanced parentheses")
            advance()
            return v
        if c is not None and c.isdigit():
            start = i
            while i < n and s[i].isdigit():
                i += 1
            return Fraction(int(s[start:i]))
        raise ValueError("missing operand")

    skip()
    if i >= n:
        raise ValueError("empty expression")
    v = parse_expr()
    skip()
    if i != n:
        raise ValueError("unexpected trailing input")
    if v.denominator == 1:
        return str(v.numerator)
    return f"{v.numerator}/{v.denominator}"

import re
from fractions import Fraction

_DATE_YMD = re.compile(r'^(?:(\d+(?:[.,]\d+)?)Y)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)D)?$')
_WEEKS = re.compile(r'^(\d+(?:[.,]\d+)?)W$')
_TIME = re.compile(r'^(?:(\d+(?:[.,]\d+)?)H)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)S)?$')


def _frac(tok):
    return Fraction(tok.replace(',', '.'))


def _parse_part(part, letters, is_time):
    """Return list of (letter, Fraction) or raise ValueError."""
    if not part:
        return []
    if is_time:
        m = _TIME.match(part)
        if not m:
            raise ValueError
        groups = m.groups()
        comps = [(letters[i], groups[2 * i]) for i in range(3) if groups[2 * i] is not None]
    else:
        m = _WEEKS.match(part)
        if m:
            comps = [('W', m.group(1))]
        else:
            m = _DATE_YMD.match(part)
            if not m:
                raise ValueError
            comps = [(letters[i], m.groups()[i]) for i in range(3) if m.groups()[i] is not None]
    if not comps:
        raise ValueError
    # only the last component may have a fraction
    for letter, tok in comps[:-1]:
        if re.search(r'[.,]', tok):
            raise ValueError
    return comps


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError
    m = re.fullmatch(r'P([^T]*)(?:T(.*))?', s)
    if not m:
        raise ValueError
    date_part, time_part = m.group(1) or '', m.group(2)
    if time_part == '':
        raise ValueError  # T must be followed by at least one component
    if 'T' in date_part:
        raise ValueError

    date_comps = _parse_part(date_part, ('Y', 'M', 'D'), is_time=False)
    time_comps = _parse_part(time_part, ('H', 'M', 'S'), is_time=True) if time_part else []
    if not date_comps and not time_comps:
        raise ValueError

    total = Fraction(0)
    for letter, val in date_comps:
        v = _frac(val)
        if letter == 'Y':
            total += v * 365 * 86400
        elif letter == 'M':
            total += v * 30 * 86400
        elif letter == 'W':
            total += v * 7 * 86400
        else:
            total += v * 86400
    for letter, val in time_comps:
        v = _frac(val)
        if letter == 'H':
            total += v * 3600
        elif letter == 'M':
            total += v * 60
        else:
            total += v
    if total.denominator != 1:
        raise ValueError
    return int(total)

import re

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s.startswith('P'):
        raise ValueError("must start with P")

    rest = s[1:]
    if rest.count('T') > 1:
        raise ValueError("multiple T")

    if 'T' in rest:
        date_part, _, time_part = rest.partition('T')
        if time_part == '':
            raise ValueError("T must be followed by a component")
    else:
        date_part, time_part = rest, ''

    token_re = re.compile(r'(\d+(?:[.,]\d+)?)([A-Z])')

    def tokenize(part):
        tokens = []
        pos = 0
        for m in token_re.finditer(part):
            if m.start() != pos:
                raise ValueError("invalid characters")
            tokens.append((m.group(1), m.group(2)))
            pos = m.end()
        if pos != len(part):
            raise ValueError("invalid characters")
        return tokens

    date_tokens = tokenize(date_part)
    time_tokens = tokenize(time_part)

    if not date_tokens and not time_tokens:
        raise ValueError("at least one component required")
    if 'T' in rest and not time_tokens:
        raise ValueError("T must be followed by a component")

    # validate date letters
    date_letters = [t[1] for t in date_tokens]
    if date_letters:
        if date_letters == ['W']:
            pass  # weeks only, alone
        else:
            if 'W' in date_letters:
                raise ValueError("W cannot be combined")
            order = 'YMD'
            idx = [order.index(l) for l in date_letters]
            if idx != sorted(idx) or len(set(idx)) != len(idx):
                raise ValueError("bad date order")
            if any(l not in order for l in date_letters):
                raise ValueError("bad date letter")

    # validate time letters
    time_letters = [t[1] for t in time_tokens]
    order = 'HMS'
    if any(l not in order for l in time_letters):
        raise ValueError("bad time letter")
    idx = [order.index(l) for l in time_letters]
    if idx != sorted(idx) or len(set(idx)) != len(idx):
        raise ValueError("bad time order")

    all_tokens = date_tokens + time_tokens

    # fraction only allowed on last token
    for num, letter in all_tokens[:-1]:
        if '.' in num or ',' in num:
            raise ValueError("fraction only on last component")

    unit_seconds = {
        'Y': 365 * 86400,
        'M': 30 * 86400,
        'W': 7 * 86400,
        'D': 86400,
        'H': 3600,
        'S': 1,
    }
    # minutes share letter M but appear in time part
    def unit_for(letter, in_time):
        if letter == 'M':
            return 60 if in_time else 30 * 86400
        return unit_seconds[letter]

    total = 0.0
    n_date = len(date_tokens)
    for i, (num, letter) in enumerate(all_tokens):
        in_time = i >= n_date
        value = float(num.replace(',', '.'))
        total += value * unit_for(letter, in_time)

    rounded = round(total)
    if abs(total - rounded) > 1e-9:
        raise ValueError("does not come to whole seconds")
    return int(rounded)

import re

_PATTERN = re.compile(
    r"^P"
    r"(?:(\d+(?:[.,]\d+)?)Y)?"
    r"(?:(\d+(?:[.,]\d+)?)M)?"
    r"(?:(\d+(?:[.,]\d+)?)D)?"
    r"(?:T"
    r"(?:(\d+(?:[.,]\d+)?)H)?"
    r"(?:(\d+(?:[.,]\d+)?)M)?"
    r"(?:(\d+(?:[.,]\d+)?)S)?"
    r")?"
    r"$"
)
_WEEKS_PATTERN = re.compile(r"^P(\d+(?:[.,]\d+)?)W$")


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")

    m = _WEEKS_PATTERN.match(s)
    if m:
        weeks = _to_number(m.group(1))
        total = weeks * 7 * 86400
        return _check_int(total)

    m = _PATTERN.match(s)
    if not m:
        raise ValueError("invalid duration")

    years, months, days, hours, minutes, seconds = m.groups()
    tokens = [t for t in (years, months, days, hours, minutes, seconds) if t is not None]

    if not tokens:
        raise ValueError("no components")

    # If T is present, it must be followed by at least one component.
    if "T" in s:
        if hours is None and minutes is None and seconds is None:
            raise ValueError("T without time components")

    # Fractional part allowed only on the last component.
    for t in tokens[:-1]:
        if "." in t or "," in t:
            raise ValueError("fraction on non-final component")

    y = _to_number(years) if years else 0
    mo = _to_number(months) if months else 0
    d = _to_number(days) if days else 0
    h = _to_number(hours) if hours else 0
    mi = _to_number(minutes) if minutes else 0
    sec = _to_number(seconds) if seconds else 0

    total = (
        y * 365 * 86400
        + mo * 30 * 86400
        + d * 86400
        + h * 3600
        + mi * 60
        + sec
    )
    return _check_int(total)


def _to_number(tok: str) -> float:
    return float(tok.replace(",", "."))


def _check_int(total: float) -> int:
    if total != int(total):
        raise ValueError("not a whole number of seconds")
    return int(total)

import re
from fractions import Fraction

_COMPONENT = re.compile(r'(\d+(?:[.,]\d+)?)([A-Z])')
_FULL = re.compile(r'P((?:\d+(?:[.,]\d+)?[YMWD])+)?(T(?:\d+(?:[.,]\d+)?[HMS])+)?')

def iso_duration_seconds(s: str) -> int:
    m = _FULL.fullmatch(s)
    if not m:
        raise ValueError("invalid duration")
    date_part, time_part = m.group(1), m.group(2)
    if date_part is None and time_part is None:
        raise ValueError("empty duration")

    def parse(part, allowed_order):
        comps = _COMPONENT.findall(part)
        letters = [c[1] for c in comps]
        if len(set(letters)) != len(letters):
            raise ValueError("repeated component")
        if letters == ['W']:
            pass  # weeks alone
        else:
            idx = [allowed_order.index(l) for l in letters]
            if idx != sorted(idx):
                raise ValueError("bad order")
        # fraction only on last component
        for num, _ in comps[:-1]:
            if '.' in num or ',' in num:
                raise ValueError("fraction not on last component")
        return {l: Fraction(num.replace(',', '.')) for num, l in comps}

    seconds = Fraction(0)
    if date_part is not None:
        d = parse(date_part, ['Y', 'M', 'D'])
        seconds += d.get('Y', 0) * 365 * 86400
        seconds += d.get('M', 0) * 30 * 86400
        seconds += d.get('W', 0) * 7 * 86400
        seconds += d.get('D', 0) * 86400
    if time_part is not None:
        t = parse(time_part[1:], ['H', 'M', 'S'])
        seconds += t.get('H', 0) * 3600
        seconds += t.get('M', 0) * 60
        seconds += t.get('S', 0)
    if seconds.denominator != 1:
        raise ValueError("not whole seconds")
    return int(seconds)

import re


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")

    num = r'(\d+(?:[.,]\d+)?)'

    def calc(comps):
        total = 0
        for g, u in comps:
            if '.' in g or ',' in g:
                a, b = re.split(r'[.,]', g)
                den = 10 ** len(b)
                numer = (int(a) * den + int(b)) * u
                if numer % den:
                    raise ValueError("not a whole number of seconds")
                total += numer // den
            else:
                total += int(g) * u
        return total

    # Weeks only on their own
    m = re.fullmatch(rf'P{num}W', s)
    if m:
        return calc([(m.group(1), 7 * 86400)])

    m = re.fullmatch(
        rf'P(?:{num}Y)?(?:{num}M)?(?:{num}D)?'
        rf'(?:T(?:{num}H)?(?:{num}M)?(?:{num}S)?)?',
        s,
    )
    if not m:
        raise ValueError("invalid duration")

    units = [365 * 86400, 30 * 86400, 86400, 3600, 60, 1]
    comps = [(g, u) for g, u in zip(m.groups(), units) if g is not None]
    if not comps:
        raise ValueError("no components")

    # Fraction allowed only on the last component
    for g, _ in comps[:-1]:
        if '.' in g or ',' in g:
            raise ValueError("fraction on non-last component")

    return calc(comps)

import re

_PATTERN = re.compile(
    r'^P(?:(?:(\d+(?:[.,]\d+)?)Y)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)D)?'
    r'|(\d+(?:[.,]\d+)?)W)?'
    r'(?:T(?:(\d+(?:[.,]\d+)?)H)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)S)?)?$'
)

_UNIT_SECONDS = {
    0: 365 * 86400,   # years
    1: 30 * 86400,    # months
    2: 86400,         # days
    3: 7 * 86400,     # weeks
    4: 3600,          # hours
    5: 60,            # minutes
    6: 1,             # seconds
}


def iso_duration_seconds(s: str) -> int:
    m = _PATTERN.match(s)
    if not m:
        raise ValueError(f"invalid ISO 8601 duration: {s!r}")

    groups = m.groups()
    matched = [(i, g) for i, g in enumerate(groups) if g is not None]

    # At least one component must be present.
    if not matched:
        raise ValueError(f"invalid ISO 8601 duration: {s!r}")

    # If a T is present, at least one time component must follow.
    if 'T' in s and not any(i >= 4 for i, _ in matched):
        raise ValueError(f"invalid ISO 8601 duration: {s!r}")

    # Only the last component may carry a fractional part.
    for i, g in matched[:-1]:
        if '.' in g or ',' in g:
            raise ValueError(f"invalid ISO 8601 duration: {s!r}")

    total = 0.0
    for i, g in matched:
        value = float(g.replace(',', '.'))
        total += value * _UNIT_SECONDS[i]

    result = round(total)
    if abs(total - result) > 1e-9:
        raise ValueError(f"duration is not a whole number of seconds: {s!r}")
    return int(result)

import re

_PATTERN = re.compile(
    r'^P'
    r'(?:(\d+)Y)?'
    r'(?:(\d+)M)?'
    r'(?:(\d+)D)?'
    r'(?:T'
    r'(?:(\d+)H)?'
    r'(?:(\d+)M)?'
    r'(?:(\d+(?:[.,]\d+)?)S)?'
    r')?$'
)
_WEEK = re.compile(r'^P(\d+(?:[.,]\d+)?)W$')


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if s == "P":
        raise ValueError("empty duration")
    m = _WEEK.match(s)
    if m:
        w = _to_float(m.group(1))
        return int(round(w * 7 * 86400))
    m = _PATTERN.match(s)
    if not m:
        raise ValueError("invalid format")
    y, mo, d, h, mi, sec = m.groups()
    if not any(g is not None for g in (y, mo, d, h, mi, sec)):
        raise ValueError("no components")
    if sec is not None and not re.match(r'^\d+[.,]\d+$', sec):
        raise ValueError("bad fraction")
    total = 0.0
    if y:
        total += int(y) * 365 * 86400
    if mo:
        total += int(mo) * 30 * 86400
    if d:
        total += int(d) * 86400
    if h:
        total += int(h) * 3600
    if mi:
        total += int(mi) * 60
    if sec:
        total += _to_float(sec)
    result = int(round(total))
    if abs(total - result) > 1e-9:
        raise ValueError("not whole seconds")
    return result


def _to_float(x: str) -> float:
    return float(x.replace(',', '.'))

import re

_PATTERN = re.compile(
    r'^P'
    r'(?:'
    r'(\d+(?:[.,]\d+)?)W'                       # weeks alone
    r'|'
    r'(?:(\d+(?:[.,]\d+)?)Y)?'                  # years
    r'(?:(\d+(?:[.,]\d+)?)M)?'                  # months
    r'(?:(\d+(?:[.,]\d+)?)D)?'                  # days
    r')'
    r'(?:T'
    r'(?:(\d+(?:[.,]\d+)?)H)?'                  # hours
    r'(?:(\d+(?:[.,]\d+)?)M)?'                  # minutes
    r'(?:(\d+(?:[.,]\d+)?)S)?'                  # seconds
    r')?$'
)


def iso_duration_seconds(s: str) -> int:
    m = _PATTERN.match(s)
    if not m:
        raise ValueError("invalid ISO 8601 duration: %r" % (s,))

    weeks, years, months, days, hours, minutes, seconds = m.groups()
    values = [weeks, years, months, days, hours, minutes, seconds]

    # At least one component must be present.
    if all(v is None for v in values):
        raise ValueError("no components present")

    # Weeks cannot be combined with any other component (including time).
    if weeks is not None and any(v is not None for v in values[1:]):
        raise ValueError("weeks combined with other components")

    # 'T' must be followed by at least one component.
    if 'T' in s and all(v is None for v in values[4:]):
        raise ValueError("'T' not followed by a component")

    # Only the last component may carry a fraction.
    present = [i for i, v in enumerate(values) if v is not None]
    last = present[-1]
    for i in present[:-1]:
        if '.' in values[i] or ',' in values[i]:
            raise ValueError("fraction on non-final component")

    def num(v):
        return float(v.replace(',', '.'))

    total = 0
    if weeks is not None:
        total += num(weeks) * 7 * 86400
    if years is not None:
        total += num(years) * 365 * 86400
    if months is not None:
        total += num(months) * 30 * 86400
    if days is not None:
        total += num(days) * 86400
    if hours is not None:
        total += num(hours) * 3600
    if minutes is not None:
        total += num(minutes) * 60
    if seconds is not None:
        total += num(seconds)

    result = round(total)
    if abs(total - result) > 1e-9:
        raise ValueError("duration is not a whole number of seconds")
    return int(result)

import re
from decimal import Decimal


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s or s[0] != 'P':
        raise ValueError("invalid duration")

    rest = s[1:]
    if 'T' in rest:
        date_part, _, time_part = rest.partition('T')
        has_time_marker = True
    else:
        date_part, time_part, has_time_marker = rest, None, False

    token_re = re.compile(r'(\d+(?:[.,]\d+)?)([A-Z])')

    def parse(part, allowed):
        if part is None:
            return []
        tokens = []
        pos = 0
        while pos < len(part):
            m = token_re.match(part, pos)
            if not m:
                raise ValueError("invalid duration")
            num_str, letter = m.group(1), m.group(2)
            if letter not in allowed:
                raise ValueError("invalid duration")
            has_fraction = '.' in num_str or ',' in num_str
            tokens.append((Decimal(num_str.replace(',', '.')), letter, has_fraction))
            pos = m.end()
        return tokens

    date_tokens = parse(date_part, 'YMWD')
    time_tokens = parse(time_part, 'HMS')

    if not date_tokens and not time_tokens:
        raise ValueError("invalid duration")
    if has_time_marker and not time_tokens:
        raise ValueError("invalid duration")

    all_tokens = date_tokens + time_tokens
    letters = [l for _, l, _ in all_tokens]

    # Weeks may not be combined with any other component.
    if 'W' in letters and len(letters) > 1:
        raise ValueError("invalid duration")

    # Each letter appears at most once.
    if len(set(letters)) != len(letters):
        raise ValueError("invalid duration")

    # Order matters within each part.
    date_order = {'Y': 0, 'M': 1, 'D': 2}
    time_order = {'H': 0, 'M': 1, 'S': 2}
    for part, order in ((date_tokens, date_order), (time_tokens, time_order)):
        indices = [order[l] for _, l, _ in part]
        if indices != sorted(indices):
            raise ValueError("invalid duration")

    # Only the last component may carry a fraction.
    for tok in all_tokens[:-1]:
        if tok[2]:
            raise ValueError("invalid duration")

    date_mult = {'Y': 365 * 86400, 'M': 30 * 86400, 'W': 7 * 86400, 'D': 86400}
    time_mult = {'H': 3600, 'M': 60, 'S': 1}

    total = Decimal(0)
    for value, letter, _ in date_tokens:
        total += value * date_mult[letter]
    for value, letter, _ in time_tokens:
        total += value * time_mult[letter]

    if total != total.to_integral_value():
        raise ValueError("not a whole number of seconds")
    return int(total)

import re

_TOKEN = re.compile(r"(\d+(?:[.,]\d+)?)([YMDWHS])")
_DATE_SECS = {"Y": 365 * 86400, "M": 30 * 86400, "W": 7 * 86400, "D": 86400}
_TIME_SECS = {"H": 3600, "M": 60, "S": 1}


def _parse_part(s, order, allow_empty=False):
    """Parse a date or time part; return list of (letter, value_str)."""
    tokens = []
    pos = 0
    while pos < len(s):
        m = _TOKEN.match(s, pos)
        if not m:
            raise ValueError("bad component")
        tokens.append((m.group(2), m.group(1)))
        pos = m.end()
    if not tokens:
        if allow_empty:
            return tokens
        raise ValueError("empty part")
    # order matters, each letter at most once
    idx = [order.index(l) for l, _ in tokens]
    if any(idx[i] >= idx[i + 1] for i in range(len(idx) - 1)):
        raise ValueError("bad order")
    if len(set(idx)) != len(idx):
        raise ValueError("duplicate letter")
    return tokens


def _value(numstr):
    numstr = numstr.replace(",", ".")
    if "." in numstr:
        return float(numstr)
    return int(numstr)


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s.startswith("P") or len(s) < 2:
        raise ValueError("invalid duration")
    body = s[1:]
    date_part, sep, time_part = body.partition("T")
    if sep and not time_part:
        raise ValueError("T must be followed by components")

    tokens = _parse_part(date_part, ["Y", "M", "W", "D"], allow_empty=bool(sep))
    # tag tokens with their part: True = time part
    tokens = [(l, n, False) for l, n in tokens]
    if sep:
        tokens += [(l, n, True) for l, n in _parse_part(time_part, ["H", "M", "S"])]

    letters = [l for l, _, _ in tokens]
    # weeks only alone
    if "W" in letters and (len(tokens) != 1 or sep):
        raise ValueError("W must be alone")
    if not tokens:
        raise ValueError("empty duration")

    # fraction only allowed on last component
    for _, num, _ in tokens[:-1]:
        if "." in num or "," in num:
            raise ValueError("fraction not on last component")

    total = 0.0
    for l, num, is_time in tokens:
        v = _value(num)
        total += v * (_TIME_SECS[l] if is_time else _DATE_SECS[l])
    result = round(total)
    if abs(total - result) > 1e-9:
        raise ValueError("not whole seconds")
    return int(result)

import re
from fractions import Fraction

_COMP = r'(\d+(?:[.,]\d+)?)'
_PATTERN = re.compile(
    r'P'
    r'(?:' + _COMP + r'Y)?'
    r'(?:' + _COMP + r'M)?'
    r'(?:' + _COMP + r'D)?'
    r'(?:' + _COMP + r'W)?'
    r'(?:T'
    r'(?:' + _COMP + r'H)?'
    r'(?:' + _COMP + r'M)?'
    r'(?:' + _COMP + r'S)?'
    r')?'
)

def iso_duration_seconds(s: str) -> int:
    m = _PATTERN.fullmatch(s)
    if not m:
        raise ValueError("invalid duration")
    y, mo, d, w, h, mi, sec = m.groups()
    if y is None and mo is None and d is None and w is None and h is None and mi is None and sec is None:
        raise ValueError("empty duration")
    if w is not None and any(g is not None for g in (y, mo, d, h, mi, sec)):
        raise ValueError("weeks cannot be combined")
    groups = [g for g in (y, mo, d, w, h, mi, sec) if g is not None]
    # only the last component may be fractional
    for g in groups[:-1]:
        if '.' in g or ',' in g:
            raise ValueError("fraction on non-last component")
    if 'T' in s and sec is None and mi is None and h is None:
        raise ValueError("T must be followed by a component")

    def val(g):
        return Fraction(g.replace(',', '.'))

    total = Fraction(0)
    if y is not None:
        total += val(y) * 365 * 86400
    if mo is not None:
        total += val(mo) * 30 * 86400
    if w is not None:
        total += val(w) * 7 * 86400
    if d is not None:
        total += val(d) * 86400
    if h is not None:
        total += val(h) * 3600
    if mi is not None:
        total += val(mi) * 60
    if sec is not None:
        total += val(sec)
    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

import re
from fractions import Fraction

_DATE_RE = re.compile(
    r"^(?:(\d+(?:[.,]\d+)?)Y)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)D)?$"
)
_WEEKS_RE = re.compile(r"^(\d+(?:[.,]\d+)?)W$")
_TIME_RE = re.compile(
    r"^(?:(\d+(?:[.,]\d+)?)H)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)S)?$"
)


def _frac(text):
    return Fraction(text.replace(",", "."))


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s or not s.startswith("P"):
        raise ValueError("invalid duration")

    date_part, sep, time_part = s[1:].partition("T")
    if "T" in time_part:
        raise ValueError("invalid duration")

    components = []  # list of (value: Fraction, seconds_per_unit: int)

    if date_part:
        m = _WEEKS_RE.match(date_part)
        if m:
            components.append((_frac(m.group(1)), 7 * 86400))
        else:
            m = _DATE_RE.match(date_part)
            if not m:
                raise ValueError("invalid duration")
            for value, secs in zip(m.groups(), (365 * 86400, 30 * 86400, 86400)):
                if value is not None:
                    components.append((_frac(value), secs))

    if sep:
        m = _TIME_RE.match(time_part)
        if not m:
            raise ValueError("invalid duration")
        groups = m.groups()
        if all(g is None for g in groups):
            raise ValueError("T must be followed by a component")
        for value, secs in zip(groups, (3600, 60, 1)):
            if value is not None:
                components.append((_frac(value), secs))

    if not components:
        raise ValueError("at least one component required")

    # Fraction allowed only on the last component
    for value, _ in components[:-1]:
        if value.denominator != 1:
            raise ValueError("fraction only allowed on last component")

    total = sum(v * secs for v, secs in components)
    if total.denominator != 1:
        raise ValueError("not a whole number of seconds")
    return int(total)

import re


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s.startswith("P"):
        raise ValueError("invalid duration")

    rest = s[1:]
    if "T" in rest:
        date_part, time_part = rest.split("T", 1)
        has_time = True
    else:
        date_part, time_part = rest, ""
        has_time = False

    num = r"\d+(?:[.,]\d+)?"
    tokens = []  # (key, number_string)

    if date_part:
        m = re.fullmatch(
            rf"(?:(?P<y>{num})Y)?(?:(?P<mo>{num})M)?(?:(?P<d>{num})D)?",
            date_part,
        )
        if m:
            for key, group in (("Y", "y"), ("MO", "mo"), ("D", "d")):
                if m.group(group) is not None:
                    tokens.append((key, m.group(group)))
        else:
            m = re.fullmatch(rf"(?P<w>{num})W", date_part)
            if not m:
                raise ValueError("invalid date part")
            tokens.append(("W", m.group("w")))

    if has_time:
        m = re.fullmatch(
            rf"(?:(?P<h>{num})H)?(?:(?P<mi>{num})M)?(?:(?P<s>{num})S)?",
            time_part,
        )
        if not m:
            raise ValueError("invalid time part")
        for key, group in (("H", "h"), ("MI", "mi"), ("S", "s")):
            if m.group(group) is not None:
                tokens.append((key, m.group(group)))
        if len(tokens) == 0:
            raise ValueError("T must be followed by a component")

    if not tokens:
        raise ValueError("empty duration")

    # Fraction allowed only on the last component.
    for key, numstr in tokens[:-1]:
        if "." in numstr or "," in numstr:
            raise ValueError("fraction on non-final component")

    values = {}
    for key, numstr in tokens:
        values[key] = float(numstr.replace(",", "."))

    total = (
        values.get("Y", 0) * 365 * 86400
        + values.get("MO", 0) * 30 * 86400
        + values.get("W", 0) * 7 * 86400
        + values.get("D", 0) * 86400
        + values.get("H", 0) * 3600
        + values.get("MI", 0) * 60
        + values.get("S", 0)
    )
    result = round(total)
    if abs(total - result) > 1e-9:
        raise ValueError("not a whole number of seconds")
    return int(result)

import re
from fractions import Fraction


def iso_duration_seconds(s: str) -> int:
    date_re = r"(?:(\d+(?:[.,]\d+)?)Y)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)D)?"
    time_re = r"(?:T(?:(\d+(?:[.,]\d+)?)H)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)S)?)?"

    m = re.fullmatch(r"P" + date_re + time_re, s)
    if m:
        groups = m.groups()
        labels = ["Y", "M", "D", "H", "M", "S"]
    else:
        m = re.fullmatch(r"P(\d+(?:[.,]\d+)?)W", s)
        if not m:
            raise ValueError("invalid duration")
        groups = (m.group(1), None, None, None, None, None)
        labels = ["W", None, None, None, None, None]

    matched = [(labels[i], groups[i]) for i in range(6) if groups[i] is not None]
    if not matched:
        raise ValueError("no components")

    # fraction allowed only on the last component
    for _, val in matched[:-1]:
        if "." in val or "," in val:
            raise ValueError("fraction not on last component")

    seconds = Fraction(0)
    for label, val in matched:
        num = Fraction(val.replace(",", "."))
        if label == "Y":
            seconds += num * 365 * 86400
        elif label == "M" and m.re.pattern.startswith("P("):
            seconds += num * 7 * 86400
        elif label == "M":
            # distinguish months vs minutes by position: index in matched order
            pass
        # handled below properly
    # recompute cleanly to avoid ambiguity between month/minute
    seconds = Fraction(0)
    is_weeks = len(matched) == 1 and matched[0][0] == "W"
    if is_weeks:
        seconds += Fraction(groups[0].replace(",", ".")) * 7 * 86400
    else:
        y, mo, d, h, mi, sec = groups
        if y:
            seconds += Fraction(y.replace(",", ".")) * 365 * 86400
        if mo:
            seconds += Fraction(mo.replace(",", ".")) * 30 * 86400
        if d:
            seconds += Fraction(d.replace(",", ".")) * 86400
        if h:
            seconds += Fraction(h.replace(",", ".")) * 3600
        if mi:
            seconds += Fraction(mi.replace(",", ".")) * 60
        if sec:
            seconds += Fraction(sec.replace(",", "."))
    if seconds.denominator != 1:
        raise ValueError("not whole seconds")
    return int(seconds)

import re
from fractions import Fraction

_NUM = r'\d+(?:[.,]\d+)?'
_FULL = re.compile(
    r'P(?:(\d+)Y)?(?:(\d+)M)?(?:(\d+)W)?(?:(\d+)D)?'
    r'(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?)?$'
)
_FULL_FRAC = re.compile(
    r'P(?:(\d+)Y)?(?:(\d+)M)?(?:(\d+)W)?(?:(\d+)D)?'
    r'(?:T(?:(\d+)H)?(?:(\d+)M)?(?:(%s)S)?)?$' % _NUM
)

def iso_duration_seconds(s: str) -> int:
    m = _FULL_FRAC.fullmatch(s)
    if not m:
        raise ValueError("invalid duration")
    y, mo, w, d, h, mi, sec = m.groups()
    parts = [g for g in (y, mo, w, d, h, mi, sec) if g is not None]
    if not parts:
        raise ValueError("empty duration")
    # weeks must be alone
    if w is not None and any(g is not None for g in (y, mo, d, h, mi, sec)):
        raise ValueError("W combined with other components")
    # T must be followed by at least one component
    if 'T' in s and h is None and mi is None and sec is None:
        raise ValueError("T without components")
    # fraction only allowed on last component
    for i, g in enumerate(parts):
        if ('.' in g or ',' in g) and i != len(parts) - 1:
            raise ValueError("fraction not on last component")

    def val(g, mult):
        if g is None:
            return Fraction(0)
        return Fraction(g.replace(',', '.')) * mult

    total = (val(y, 365 * 86400) + val(mo, 30 * 86400) + val(w, 7 * 86400)
             + val(d, 86400) + val(h, 3600) + val(mi, 60) + val(sec, 1))
    if total.denominator != 1:
        raise ValueError("not whole seconds")
    return int(total)

import re
from fractions import Fraction

_TOKEN = re.compile(r'(\d+(?:[.,]\d+)?)([A-Z])')

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s or s[0] != 'P':
        raise ValueError("invalid duration")
    rest = s[1:]
    if 'T' in rest:
        date_part, time_part = rest.split('T', 1)
        if time_part == '':
            raise ValueError("T must be followed by a component")
    else:
        date_part, time_part = rest, ''

    def parse(part, allowed):
        comps = []
        pos = 0
        while pos < len(part):
            m = _TOKEN.match(part, pos)
            if not m:
                raise ValueError("invalid component")
            num, letter = m.group(1), m.group(2)
            if letter not in allowed:
                raise ValueError("bad letter")
            comps.append((letter, num))
            pos = m.end()
        return comps

    date_comps = parse(date_part, 'YMDW')
    time_comps = parse(time_part, 'HMS')

    letters = [c[0] for c in date_comps]
    if 'W' in letters and len(date_comps) > 1:
        raise ValueError("W cannot be combined")

    def check_order(comps, order):
        idxs = [order.index(c[0]) for c in comps]
        return idxs == sorted(idxs) and len(set(idxs)) == len(idxs)
    if not check_order(date_comps, 'YMDW') or not check_order(time_comps, 'HMS'):
        raise ValueError("bad order")
    if not date_comps and not time_comps:
        raise ValueError("empty duration")

    all_comps = date_comps + time_comps
    for letter, num in all_comps[:-1]:
        if '.' in num or ',' in num:
            raise ValueError("fraction not on last component")

    factors = {'Y': 365 * 86400, 'W': 7 * 86400, 'D': 86400,
               'H': 3600, 'S': 1}

    total = Fraction(0)
    for letter, num in all_comps:
        if '.' in num or ',' in num:
            int_part, _, frac = num.replace(',', '.').partition('.')
            if not int_part or not frac:
                raise ValueError("bad number")
            value = Fraction(int(int_part)) + Fraction(int(frac), 10 ** len(frac))
        else:
            value = Fraction(int(num))
        if letter == 'M':
            f = 30 * 86400 if (letter, num) in date_comps else 60
        else:
            f = factors[letter]
        total += value * f

    if total.denominator != 1:
        raise ValueError("not whole seconds")
    return int(total)

import re
from decimal import Decimal

_TOKEN = re.compile(r'(\d+(?:[.,]\d+)?)([YMDWHS])')

_DATE_MULT = {'Y': 365 * 86400, 'M': 30 * 86400, 'W': 7 * 86400, 'D': 86400}
_TIME_MULT = {'H': 3600, 'M': 60, 'S': 1}


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str) or not s.startswith('P'):
        raise ValueError('invalid duration')

    body = s[1:]
    tokens = []  # list of (letter, number_string); letter 'T' has number None
    pos = 0
    while pos < len(body):
        if body[pos] == 'T':
            tokens.append(('T', None))
            pos += 1
            continue
        m = _TOKEN.match(body, pos)
        if not m:
            raise ValueError('invalid duration')
        tokens.append((m.group(2), m.group(1)))
        pos = m.end()

    if not tokens:
        raise ValueError('invalid duration')

    letters = [t[0] for t in tokens]

    if 'T' in letters:
        if letters.count('T') != 1:
            raise ValueError('invalid duration')
        ti = letters.index('T')
        if ti == len(letters) - 1:
            raise ValueError('invalid duration')  # T must be followed by a component
        date_letters = letters[:ti]
        time_letters = letters[ti + 1:]
    else:
        ti = None
        date_letters = letters
        time_letters = []

    # Validate date part ordering; W only alone
    if 'W' in date_letters:
        if len(date_letters) != 1:
            raise ValueError('invalid duration')
    else:
        idx = ['YMD'.index(l) for l in date_letters]
        if idx != sorted(idx) or len(set(idx)) != len(idx):
            raise ValueError('invalid duration')

    # Validate time part ordering
    tidx = ['HMS'.index(l) for l in time_letters]
    if tidx != sorted(tidx) or len(set(tidx)) != len(tidx):
        raise ValueError('invalid duration')

    # Fraction allowed only on the last component
    for _, num in tokens[:-1]:
        if num is not None and ('.' in num or ',' in num):
            raise ValueError('invalid duration')

    total = Decimal(0)
    for i, (letter, num) in enumerate(tokens):
        if letter == 'T':
            continue
        value = Decimal(num.replace(',', '.'))
        if ti is not None and i > ti:
            mult = _TIME_MULT[letter]
        else:
            mult = _DATE_MULT[letter]
        total += value * mult

    result = int(total)
    if total != result:
        raise ValueError('not a whole number of seconds')
    return result

import re

_TOKEN_RE = re.compile(r"(\d+(?:[.,]\d+)?)([YMDWHS])")

def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("invalid duration")
    if not s.startswith("P"):
        raise ValueError("invalid duration")
    body = s[1:]
    if not body:
        raise ValueError("invalid duration")

    # Split into date part and optional time part.
    time_part = None
    if "T" in body:
        date_part, _, time_part = body.partition("T")
        if time_part == "":
            raise ValueError("invalid duration")  # T must be followed by a component
    else:
        date_part = body

    def parse_part(text, allowed, unit_seconds):
        if text is None:
            return 0.0, None
        pos = 0
        seen = set()
        total = 0.0
        last_unit = None
        while pos < len(text):
            m = _TOKEN_RE.match(text, pos)
            if not m:
                raise ValueError("invalid duration")
            num, unit = m.group(1), m.group(2)
            if unit not in allowed or unit in seen:
                raise ValueError("invalid duration")
            seen.add(unit)
            if "." in num or "," in num:
                # fraction only allowed on the very last component of the string
                if pos + len(m.group(0)) != len(text):
                    raise ValueError("fraction only on last component")
                ip, fp = re.split(r"[.,]", num, maxsplit=1)
                if not ip or not fp:
                    raise ValueError("invalid duration")
                total += (int(ip) + int(fp) / 10 ** len(fp)) * unit_seconds[unit]
            else:
                total += int(num) * unit_seconds[unit]
            last_unit = unit
            pos = m.end()
        if pos != len(text):
            raise ValueError("invalid duration")
        return total, last_unit

    date_units = {"Y": 365 * 86400, "M": 30 * 86400, "D": 86400, "W": 7 * 86400}
    time_units = {"H": 3600, "M": 60, "S": 1}

    if time_part is None:
        total, last_unit = parse_part(body, date_units, date_units)
        if total == 0 and last_unit is None:
            raise ValueError("invalid duration")
    else:
        date_total, date_last = parse_part(date_part, date_units, date_units)
        time_total, time_last = parse_part(time_part, time_units, time_units)
        if date_last is None and time_last is None:
            raise ValueError("invalid duration")
        # W cannot be combined with anything else
        if date_last == "W" and (date_part.rstrip("0123456789.,W") != "W" or time_last is not None):
            raise ValueError("invalid duration")
        if "W" in date_part and date_last != "W":
            raise ValueError("invalid duration")
        total = date_total + time_total
        last_unit = time_last if time_last is not None else date_last

    # Fraction is only allowed on the last component; parse_part already enforced
    # position, but ensure the whole result is an integer number of seconds.
    if total != int(total):
        raise ValueError("not whole seconds")
    return int(total)

import re
from fractions import Fraction


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")

    # Weeks-only form
    m = re.fullmatch(r"P(\d+)W", s)
    if m:
        return int(m.group(1)) * 7 * 86400

    m = re.fullmatch(
        r"P(?:(\d+)Y)?(?:(\d+)M)?(?:(\d+)D)?"
        r"(?:T(?:(\d+(?:[.,]\d+)?)H)?(?:(\d+(?:[.,]\d+)?)M)?(?:(\d+(?:[.,]\d+)?)S)?)?",
        s,
    )
    if not m:
        raise ValueError("invalid duration")

    y, mo, d, h, mi, sec = m.groups()
    if y is None and mo is None and d is None and h is None and mi is None and sec is None:
        raise ValueError("empty duration")
    if h is None and mi is None and sec is None and "T" in s:
        raise ValueError("T without components")

    # Fraction allowed only on the last component of the string
    comps = re.findall(r"(\d+(?:[.,]\d+)?)([YMDHS])", s)
    if not comps:
        raise ValueError("no components")
    for value, letter in comps[:-1]:
        if re.search(r"[.,]", value):
            raise ValueError("fraction not on last component")

    def num(v):
        if v is None:
            return Fraction(0)
        v = v.replace(",", ".")
        if "." in v:
            whole, frac = v.split(".")
            return Fraction(int(whole)) + Fraction(int(frac), 10 ** len(frac))
        return Fraction(int(v))

    total = (
        num(y) * 365 * 86400
        + num(mo) * 30 * 86400
        + num(d) * 86400
        + num(h) * 3600
        + num(mi) * 60
        + num(sec)
    )
    if total.denominator != 1:
        raise ValueError("not whole seconds")
    return int(total)

import re
from decimal import Decimal, InvalidOperation

_DATE_LETTERS = ("Y", "M", "D")
_TIME_LETTERS = ("H", "M", "S")
_SECONDS_PER = {
    "Y": 365 * 86400,
    "M": 30 * 86400,   # months (date part)
    "W": 7 * 86400,
    "D": 86400,
    "H": 3600,
    "S": 1,
}
_MINUTE_SECONDS = 60


def _parse_components(part, allowed_order, is_time):
    """Parse a part into a list of (Decimal value, letter), validating format."""
    if part == "":
        return []
    comp_re = re.compile(r"(\d+(?:[.,]\d+)?)([A-Z])")
    tokens = comp_re.findall(part)
    # Ensure the whole part is consumed by well-formed components
    if "".join(n + l for n, l in tokens) != part:
        raise ValueError("invalid component format")
    letters = [l for _, l in tokens]
    # each letter at most once, correct order
    if len(set(letters)) != len(letters):
        raise ValueError("duplicate component")
    allowed = list(allowed_order)
    idx = [allowed.index(l) for l in letters]
    if idx != sorted(idx):
        raise ValueError("components out of order")
    if is_time and "M" in letters:
        # minutes allowed; letter 'M' in time means minutes
        pass
    result = []
    for num, letter in tokens:
        try:
            value = Decimal(num.replace(",", "."))
        except InvalidOperation:
            raise ValueError("bad number")
        result.append((value, letter))
    return result


def iso_duration_seconds(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("not a string")
    if not s.startswith("P"):
        raise ValueError("must start with P")
    rest = s[1:]
    if rest == "":
        raise ValueError("empty duration")

    if "T" in rest:
        date_part, sep, time_part = rest.partition("T")
        if "T" in time_part:
            raise ValueError("multiple T")
        if time_part == "":
            raise ValueError("T must be followed by a component")
        has_time = True
    else:
        date_part, time_part, has_time = rest, "", False

    # Weeks only on their own
    if "W" in date_part:
        if not re.fullmatch(r"\d+(?:[.,]\d+)?W", date_part):
            raise ValueError("W must be alone")
        if has_time:
            raise ValueError("W cannot be combined with time")
        tokens = [(Decimal(date_part[:-1].replace(",", ".")), "W")]
    else:
        tokens = _parse_components(date_part, _DATE_LETTERS, is_time=False)

    time_tokens = _parse_components(time_part, _TIME_LETTERS, is_time=True)

    # Fraction only allowed on the last component of the whole string
    all_tokens = tokens + time_tokens
    for value, letter in all_tokens[:-1]:
        if value != value.to_integral_value():
            raise ValueError("fraction only on last component")

    total = Decimal(0)
    for value, letter in all_tokens:
        if letter == "M":
            # months if it came from the date part, minutes if from time part
            secs = _SECONDS_PER["M"] if (value, letter) in tokens else _MINUTE_SECONDS
        else:
            secs = _SECONDS_PER[letter]
        total += value * secs

    if total != total.to_integral_value():
        raise ValueError("not a whole number of seconds")
