# Canonical forms only:
#   thousands: M{0,3}
#   hundreds:  CM | CD | D?C{0,3}
#   tens:      XC | XL | L?X{0,3}
#   units:     IX | IV | V?I{0,3}
_PATTERN = re.compile(
    r"M{0,3}(CM|CD|D?C{0,3})(XC|XL|L?X{0,3})(IX|IV|V?I{0,3})"
)


def parse_roman(s: str) -> int:
    if not isinstance(s, str) or not s or not _PATTERN.fullmatch(s):
        raise ValueError(f"invalid Roman numeral: {s!r}")
    total = 0
    for ch, nxt in zip(s, s[1:]):
        total += _VALUES[ch] if _VALUES[ch] >= _VALUES[nxt] else -_VALUES[ch]
    return total + _VALUES[s[-1]]

