import re

_ROMAN_RE = re.compile(
    r'^(?P<thousands>M{0,3})'
    r'(?P<hundreds>CM|CD|D?C{0,3})'
    r'(?P<tens>XC|XL|L?X{0,3})'
    r'(?P<units>IX|IV|V?I{0,3})$'
)

_VALUES = {
    'I': 1, 'V': 5, 'X': 10, 'L': 50,
    'C': 100, 'D': 500, 'M': 1000,
}


def _group_value(group: str) -> int:
    """Value of one digit position, correctly handling subtractive pairs."""
    if not group:
        return 0
    total = 0
    prev = 0
    # Iterate right to left: add a symbol, but if the symbol to its right
    # is larger, this symbol was subtractive, so subtract it instead.
    for c in reversed(group):
        v = _VALUES[c]
        if v < prev:
            total -= v
        else:
            total += v
        prev = max(prev, v)
    return total


def parse_roman(s: str) -> int:
    if not s:
        raise ValueError("invalid Roman numeral: empty string")
    m = _ROMAN_RE.match(s)
    if not m:
        raise ValueError(f"invalid Roman numeral: {s!r}")
    return sum(_group_value(m.group(name))
               for name in ('thousands', 'hundreds', 'tens', 'units'))

