def parse_roman(s: str) -> int:
    if not s:
        raise ValueError("invalid Roman numeral: empty string")
    m = _ROMAN_RE.fullmatch(s)
    if not m:
        raise ValueError(f"invalid Roman numeral: {s!r}")
    total = 0
    for i, c in enumerate(s):
        v = _VALUES[c]
        # The regex guarantees the only smaller-before-larger cases are
        # the valid subtractive pairs IV, IX, XL, XC, CD, CM.
        if i + 1 < len(s) and _VALUES[s[i + 1]] > v:
            total -= v
        else:
            total += v
    return total

def parse_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    n = len(line)
    while True:
        if i < n and line[i] == '"':
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise ValueError("unclosed quoted field")
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    buf.append(c)
                    i += 1
            if i < n and line[i] != ',':
                raise ValueError("character after closing quote")
            fields.append(''.join(buf))
            if i >= n:
                return fields
            i += 1  # skip comma
        else:
            j = i
            while j < n and line[j] != ',':
                if line[j] == '"':
                    raise ValueError('quote inside unquoted field')
                j += 1
            fields.append(line[i:j])
            if j >= n:
                return fields
            i = j + 1

