def parse_csv_line(line: str) -> list[str]:
    fields = []
    i = 0
    n = len(line)
    while True:
        if i < n and line[i] == '"':
            # Quoted field
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")
                if line[i] == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1
                        break
                else:
                    buf.append(line[i])
                    i += 1
            if i < n and line[i] != ',':
                raise ValueError("character after closing quote")
            fields.append(''.join(buf))
            if i >= n:
                return fields
            i += 1  # skip comma; next field starts here (may be empty or end of line)
            if i == n:
                fields.append("")
                return fields
        else:
            # Unquoted field: taken exactly as written, up to the next comma
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError("quote inside unquoted field")
                i += 1
            fields.append(line[start:i])
            if i >= n:
                return fields
            i += 1  # skip comma
            if i == n:
                fields.append("")
                return fields

