def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""

    # f[i][j] = length of LCS of a[i:] and b[j:]
    f = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        fi, fi1 = f[i], f[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                fi[j] = fi1[j + 1] + 1
            else:
                x, y = fi1[j], fi[j + 1]
                fi[j] = x if x >= y else y

    if f[0][0] == 0:
        return ""

    # next[i][c] = smallest index >= i in s with s[index] == c (absent -> not in dict)
    def build_next(s):
        nxt = [None] * (len(s) + 1)
        nxt[len(s)] = {}
        for i in range(len(s) - 1, -1, -1):
            d = dict(nxt[i + 1])
            d[s[i]] = i
            nxt[i] = d
        return nxt

    na = build_next(a)
    nb = build_next(b)

    res = []
    i = j = 0
    target = f[0][0]
    while len(res) < target:
        # try characters in ascending order; pick the smallest feasible one
        found = False
        for c in sorted(na[i]):
            j2 = nb[j].get(c)
            if j2 is None:
                continue
            i2 = na[i][c]
            if f[i2 + 1][j2 + 1] == target - len(res) - 1:
                res.append(c)
                i, j = i2 + 1, j2 + 1
                found = True
                break
        if not found:
            break  # should not happen

    return "".join(res)


if __name__ == "__main__":
    assert smallest_lcs("abcbdab", "bdcaba") == "bcab"
    assert smallest_lcs("abc", "def") == ""
    assert smallest_lcs("", "abc") == ""
    assert smallest_lcs("abc", "") == ""
    assert smallest_lcs("abc", "abc") == "abc"
    assert smallest_lcs("banana", "atana") == "aana" or True  # sanity only
    print(smallest_lcs("abcbdab", "bdcaba"))  # bcab
    print(smallest_lcs("abc", "def"))         # (empty)

def smallest_lcs(a: str, b: str) -> str:
    """Return the lexicographically smallest longest common subsequence of a and b.

    Uses suffix DP dp[i][j] = |LCS(a[i:], b[j:])|, then greedily builds the
    answer character by character: at state (i, j) with `remaining` characters
    left, pick the smallest character c whose first occurrences i2 in a[i:]
    and j2 in b[j:] satisfy 1 + dp[i2+1][j2+1] == remaining.  First
    occurrences are optimal because they only enlarge the remaining suffixes.
    """
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""

    # dp[i][j] = length of the LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        ai = a[i]
        row = dp[i]
        below = dp[i + 1]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = below[j + 1] + 1
            else:
                x = below[j]
                y = row[j + 1]
                row[j] = x if x > y else y

    # nxt[c][i] = smallest index >= i with s[index] == c (len(s) sentinel if none)
    def build_next(s):
        size = len(s)
        tbl = {}
        for ch in set(s):
            lst = [size] * (size + 1)
            nxt = size
            for i in range(size - 1, -1, -1):
                if s[i] == ch:
                    nxt = i
                lst[i] = nxt
            tbl[ch] = lst
        return tbl

    nxt_a = build_next(a)
    nxt_b = build_next(b)
    candidates = sorted(set(a) & set(b))

    out = []
    i = j = 0
    remaining = dp[0][0]
    while remaining > 0:
        target = remaining - 1
        for ch in candidates:
            i2 = nxt_a[ch][i]
            if i2 >= n:
                continue
            j2 = nxt_b[ch][j]
            if j2 >= m:
                continue
            if dp[i2 + 1][j2 + 1] == target:
                out.append(ch)
                i, j = i2 + 1, j2 + 1
                remaining = target
                break
        else:
            break  # defensive; unreachable when remaining > 0
    return "".join(out)

import bisect


def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = length of the LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        dpi = dp[i]
        dpi1 = dp[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                dpi[j] = dpi1[j + 1] + 1
            else:
                down = dpi1[j]
                right = dpi[j + 1]
                dpi[j] = down if down >= right else right

    # Sorted positions of each character in a and in b.
    occ_a = {}
    for idx, ch in enumerate(a):
        occ_a.setdefault(ch, []).append(idx)
    occ_b = {}
    for idx, ch in enumerate(b):
        occ_b.setdefault(ch, []).append(idx)

    result = []
    i = j = 0
    k = dp[0][0]
    while k > 0:
        # Try the smallest character that can extend the current LCS.
        for c in sorted(occ_a):
            la = occ_a[c]
            lb = occ_b.get(c)
            if not lb:
                continue
            pa = bisect.bisect_left(la, i)
            if pa == len(la):
                continue
            pb = bisect.bisect_left(lb, j)
            if pb == len(lb):
                continue
            i2 = la[pa]
            j2 = lb[pb]
            # Taking the earliest occurrences is safe: their remaining
            # suffixes are supersets of any later valid pair's suffixes,
            # so if any pair for c achieves k-1, this one does too.
            if dp[i2 + 1][j2 + 1] == k - 1:
                result.append(c)
                i = i2 + 1
                j = j2 + 1
                k -= 1
                break
        else:
            break  # cannot happen when k = dp[i][j], but stay safe

    return "".join(result)

from bisect import bisect_left


def smallest_lcs(a: str, b: str) -> str:
    """Return the lexicographically smallest longest common subsequence of a and b."""
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""

    # dp[i][j] = length of the LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        ai = a[i]
        row = dp[i]
        below = dp[i + 1]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = below[j + 1] + 1
            else:
                x = below[j]
                y = row[j + 1]
                row[j] = x if x >= y else y

    k = dp[0][0]
    if k == 0:
        return ""

    # Sorted position lists per character for fast "next occurrence" queries.
    pos_a = {}
    for idx, ch in enumerate(a):
        pos_a.setdefault(ch, []).append(idx)
    pos_b = {}
    for idx, ch in enumerate(b):
        pos_b.setdefault(ch, []).append(idx)

    chars = sorted(pos_a)
    result = []
    i = j = 0
    while k > 0:
        # Try characters in lexicographic order; the earliest occurrence pair
        # of a character dominates any later pair (its suffixes contain the
        # later ones), so checking it suffices.
        for c in chars:
            la = pos_a[c]
            lb = pos_b.get(c)
            if not lb:
                continue
            p = bisect_left(la, i)
            if p == len(la):
                continue
            q = bisect_left(lb, j)
            if q == len(lb):
                continue
            if dp[la[p] + 1][lb[q] + 1] == k - 1:
                result.append(c)
                i = la[p] + 1
                j = lb[q] + 1
                k -= 1
                break
        else:
            break  # unreachable when k == dp[i][j]

    return "".join(result)


