    assert smallest_lcs("abcbdab", "bdcaba") == "bcab"
    assert smallest_lcs("abc", "def") == ""
    assert smallest_lcs("", "abc") == ""
    assert smallest_lcs("abc", "abc") == "abc"
    assert smallest_lcs("ba", "ab") == "a"  # LCSs: "a" and "b"; "a" < "b"
    assert smallest_lcs("abcbdab", "bdcaba") == "bcab"
    print("All tests passed.")

def smallest_lcs(a: str, b: str) -> str:
    """Return the lexicographically smallest longest common subsequence of a and b."""
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""

    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row, nxt = dp[i], dp[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                r, u = row[j + 1], nxt[j]
                row[j] = r if r >= u else u

    chars = sorted(set(a) & set(b))
    if not chars:
        return ""

    # nxt_a[c][i] = smallest index >= i with a[index] == c (n if none); same for b.
    nxt_a = {c: [n] * (n + 1) for c in chars}
    for i in range(n - 1, -1, -1):
        ai = a[i]
        for c in chars:
            nxt_a[c][i] = i if ai == c else nxt_a[c][i + 1]
    nxt_b = {c: [m] * (m + 1) for c in chars}
    for j in range(m - 1, -1, -1):
        bj = b[j]
        for c in chars:
            nxt_b[c][j] = j if bj == c else nxt_b[c][j + 1]

    # Greedy reconstruction: at each step pick the smallest character that can
    # still lead to an LCS of the remaining length.  Using the earliest
    # occurrence of c in each string is optimal, since any later occurrence
    # leaves shorter suffixes and thus can only give a smaller remaining LCS.
    res = []
    i = j = 0
    k = dp[0][0]
    while k > 0:
        for c in chars:
            i2 = nxt_a[c][i]
            j2 = nxt_b[c][j]
            if i2 < n and j2 < m and dp[i2 + 1][j2 + 1] == k - 1:
                res.append(c)
                i, j = i2 + 1, j2 + 1
                k -= 1
                break
        else:
            break  # cannot happen if dp is correct
    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # lcs[i][j] = length of the LCS of a[i:] and b[j:]
    lcs = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row = lcs[i]
        nxt = lcs[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                down = nxt[j]
                right = row[j + 1]
                row[j] = down if down >= right else right

    # Only characters present in both strings can ever be used.
    chars = sorted(set(a) & set(b))
    if not chars:
        return ""

    char_index = {c: k for k, c in enumerate(chars)}
    nc = len(chars)

    def build_next(s: str):
        # next[i][k] = smallest index >= i in s where chars[k] occurs, else -1
        tab = [[-1] * nc for _ in range(len(s) + 1)]
        for i in range(len(s) - 1, -1, -1):
            row = tab[i]
            row[:] = tab[i + 1]
            k = char_index.get(s[i])
            if k is not None:
                row[k] = i
        return tab

    nxt_a = build_next(a)
    nxt_b = build_next(b)

    res = []
    i = j = 0
    while lcs[i][j] > 0:
        need = lcs[i][j] - 1
        for k, c in enumerate(chars):
            ia = nxt_a[i][k]
            jb = nxt_b[j][k]
            if ia != -1 and jb != -1 and lcs[ia + 1][jb + 1] == need:
                res.append(c)
                i, j = ia + 1, jb + 1
                break
        else:
            break  # defensive; cannot happen when lcs[i][j] > 0
    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    """
    Return the lexicographically smallest longest common subsequence of a and b.
    Runs in O(n*m + (n+m)*|alphabet|) time, easily fast enough for n, m <= 300.
    """
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""

    # lcs[i][j] = length of the LCS of a[i:] and b[j:]
    lcs = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        ai = a[i]
        row = lcs[i]
        nxt = lcs[i + 1]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                x, y = nxt[j], row[j + 1]
                row[j] = x if x >= y else y

    k = lcs[0][0]
    if k == 0:
        return ""

    common = sorted(set(a) & set(b))

    # next_a[c][i] = smallest index >= i with a[index] == c (n if none); same for b.
    next_a = {}
    for c in common:
        arr = [n] * (n + 1)
        for i in range(n - 1, -1, -1):
            arr[i] = i if a[i] == c else arr[i + 1]
        next_a[c] = arr

    next_b = {}
    for c in common:
        arr = [m] * (m + 1)
        for j in range(m - 1, -1, -1):
            arr[j] = j if b[j] == c else arr[j + 1]
        next_b[c] = arr

    # Greedy reconstruction: at state (i, j) with k characters still to pick,
    # choose the smallest character c whose first occurrences ia in a[i:] and
    # jb in b[j:] satisfy lcs[ia+1][jb+1] == k-1.  Using the first occurrences
    # is sufficient: any later occurrence pair can only have a smaller (or
    # equal) remaining LCS value, so if any pair works, the first pair works.
    res = []
    i = j = 0
    while k > 0:
        target = k - 1
        for c in common:
            ia = next_a[c][i]
            if ia >= n:
                continue
            jb = next_b[c][j]
            if jb >= m:
                continue
            if lcs[ia + 1][jb + 1] == target:
                res.append(c)
                i = ia + 1
                j = jb + 1
                k = target
                break
        else:
            break  # defensive; cannot happen when k > 0

    return "".join(res)


