    assert smallest_lcs("abc", "def") == ""
    assert smallest_lcs("", "abc") == ""
    assert smallest_lcs("abc", "abc") == "abc"
    assert smallest_lcs("cba", "abc") == "a"
    assert smallest_lcs("banana", "atana") == "aana"
    print("all tests passed")

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row = dp[i]
        nxt_row = dp[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt_row[j + 1] + 1
            else:
                r = nxt_row[j]
                if dp[i][j + 1] > r:
                    r = dp[i][j + 1]
                row[j] = r

    k = dp[0][0]
    if k == 0:
        return ""

    # nxt[c][i] = smallest index >= i where c occurs in a (similarly for b)
    def build_next(s):
        tables = {}
        for c in set(s):
            arr = [None] * (len(s) + 1)
            nxt = None
            for i in range(len(s) - 1, -1, -1):
                if s[i] == c:
                    nxt = i
                arr[i] = nxt
            tables[c] = arr
        return tables

    nxt_a = build_next(a)
    nxt_b = build_next(b)

    alphabet = sorted(set(a) & set(b))

    result = []
    i, j = 0, 0
    for remaining in range(k, 0, -1):
        for c in alphabet:
            ia = nxt_a[c][i]
            if ia is None:
                continue
            jb = nxt_b[c][j]
            if jb is None:
                continue
            if dp[ia + 1][jb + 1] == remaining - 1:
                result.append(c)
                i, j = ia + 1, jb + 1
                break

    return "".join(result)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""

    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row = dp[i]
        nxt = dp[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                down = nxt[j]
                right = row[j + 1]
                row[j] = down if down >= right else right

    # next_occ[c][i] = smallest index >= i where s[index] == c (len(s) if none)
    def build_next(s):
        tables = {}
        for c in set(s):
            arr = [len(s)] * (len(s) + 1)
            nx = len(s)
            for i in range(len(s) - 1, -1, -1):
                if s[i] == c:
                    nx = i
                arr[i] = nx
            tables[c] = arr
        return tables

    ta = build_next(a)
    tb = build_next(b)
    common_chars = sorted(set(ta) & set(tb))

    res = []
    i = j = 0
    L = dp[0][0]
    while L > 0:
        for c in common_chars:
            i1 = ta[c][i]
            j1 = tb[c][j]
            if i1 < n and j1 < m and dp[i1 + 1][j1 + 1] == L - 1:
                res.append(c)
                i, j = i1 + 1, j1 + 1
                L -= 1
                break
        else:
            break  # cannot happen if dp is correct
    return "".join(res)

from bisect import bisect_left


def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""

    # dp[i][j] = length of the LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        ai = a[i]
        nxt_row = dp[i + 1]
        row = dp[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt_row[j + 1] + 1
            else:
                x = nxt_row[j]
                y = row[j + 1]
                row[j] = x if x > y else y

    # Sorted positions of each character in each string.
    pos_a = {}
    for idx, ch in enumerate(a):
        pos_a.setdefault(ch, []).append(idx)
    pos_b = {}
    for idx, ch in enumerate(b):
        pos_b.setdefault(ch, []).append(idx)

    # Candidate characters, tried in ascending order for lexicographic minimality.
    chars = sorted(set(pos_a) & set(pos_b))

    res = []
    i = j = 0
    remaining = dp[0][0]
    while remaining > 0:
        for c in chars:
            la = pos_a[c]
            p = bisect_left(la, i)
            if p == len(la):
                continue
            lb = pos_b[c]
            q = bisect_left(lb, j)
            if q == len(lb):
                continue
            ia = la[p]
            jb = lb[q]
            # Earliest match for c must still allow an LCS of length remaining - 1.
            if dp[ia + 1][jb + 1] == remaining - 1:
                res.append(c)
                i, j = ia + 1, jb + 1
                remaining -= 1
                break
        else:
            break  # defensive; cannot happen while remaining > 0

    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""

    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        ai = a[i]
        row = dp[i]
        nxt = dp[i + 1]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                best = nxt[j + 1]
                v = nxt[j]
                if v > best:
                    best = v
                v = row[j + 1]
                if v > best:
                    best = v
                row[j] = best

    # next[i] maps each character to its earliest occurrence index >= i in the string
    def build_next(s):
        tables = [None] * (len(s) + 1)
        tables[len(s)] = {}
        d = {}
        for i in range(len(s) - 1, -1, -1):
            d = dict(d)
            d[s[i]] = i
            tables[i] = d
        return tables

    na = build_next(a)
    nb = build_next(b)

    res = []
    i = j = 0
    while dp[i][j] > 0:
        target = dp[i][j]
        best_c = None
        for c, p in na[i].items():
            q = nb[j].get(c)
            if q is not None and dp[p + 1][q + 1] + 1 == target:
                if best_c is None or c < best_c:
                    best_c = c
        # best_c is guaranteed to exist when dp[i][j] > 0
        p = na[i][best_c]
        q = nb[j][best_c]
        res.append(best_c)
        i, j = p + 1, q + 1

    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    # lcs[i][j] = length of LCS of a[i:] and b[j:]
    lcs = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row = lcs[i]
        nxt = lcs[i + 1]
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                row[j] = row[j + 1] if row[j + 1] >= nxt[j] else nxt[j]

    result = []
    i = j = 0
    while (need := lcs[i][j]) > 0:
        for c in sorted(set(a[i:])):
            # find first occurrence of c in a[i:] and b[j:] that keeps LCS length
            ai = a.find(c, i)
            bj = b.find(c, j)
            while ai != -1:
                bj = b.find(c, j)
                while bj != -1:
                    if lcs[ai + 1][bj + 1] + 1 == need:
                        result.append(c)
                        i, j = ai + 1, bj + 1
                        break
                    bj = b.find(c, bj + 1)
                if bj != -1:
                    break
                ai = a.find(c, ai + 1)
            else:
                continue
            break
        else:
            # shouldn't happen, but guard
            break
    return "".join(result)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row = dp[i]
        nxt = dp[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                # max of dp[i+1][j] and dp[i][j+1]
                v = nxt[j]
                v2 = row[j + 1]
                row[j] = v if v >= v2 else v2

    # next occurrence of each character at or after index i
    def build_next(s):
        nxt = {}
        table = {}
        for c in set(s):
            table[c] = [None] * (len(s) + 1)
        arr = [None] * (len(s) + 1)
        for i in range(len(s) - 1, -1, -1):
            arr[i] = arr[i + 1]
            c = s[i]
            if c not in table:
                table[c] = [None] * (len(s) + 1)
            table[c][i] = i
        for c, t in table.items():
            last = None
            for i in range(len(s), -1, -1):
                if t[i] is not None:
                    last = t[i]
                t[i] = last
        return table

    nxt_a = build_next(a)
    nxt_b = build_next(b)

    chars = sorted(set(a) & set(b))
    result = []
    i = j = 0
    L = dp[0][0]
    while L > 0:
        for c in chars:
            ia = nxt_a[c][i]
            jb = nxt_b[c][j]
            if ia is not None and jb is not None and dp[ia + 1][jb + 1] == L - 1:
                result.append(c)
                i, j = ia + 1, jb + 1
                L -= 1
                break
        else:
            break  # should not happen
    return "".join(result)

from bisect import bisect_left


def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row = dp[i]
        nxt = dp[i + 1]
        for j in range(m - 1, -1, -1):
            if a[i] == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                rj1 = row[j + 1]
                nj = nxt[j]
                row[j] = rj1 if rj1 >= nj else nj

    # Precompute sorted positions of each character in both strings.
    pos_a = {}
    pos_b = {}
    for i, c in enumerate(a):
        pos_a.setdefault(c, []).append(i)
    for j, c in enumerate(b):
        pos_b.setdefault(c, []).append(j)

    chars = sorted(set(pos_a) & set(pos_b))

    res = []
    i = j = 0
    k = dp[0][0]
    while k > 0:
        for c in chars:
            la = pos_a[c]
            lb = pos_b[c]
            ia = bisect_left(la, i)
            if ia == len(la):
                continue
            ib = bisect_left(lb, j)
            if ib == len(lb):
                continue
            na = la[ia]
            nb = lb[ib]
            if dp[na + 1][nb + 1] == k - 1:
                res.append(c)
                i, j = na + 1, nb + 1
                k -= 1
                break
        else:
            # Should not happen if dp is correct.
            break

    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = length of the LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row = dp[i]
        nxt_row = dp[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt_row[j + 1] + 1
            else:
                down = nxt_row[j]
                right = row[j + 1]
                row[j] = down if down >= right else right

    # nxt[i] maps each character c to the smallest index >= i where c occurs.
    def build_next(s):
        nxt = [None] * (len(s) + 1)
        nxt[len(s)] = {}
        for i in range(len(s) - 1, -1, -1):
            d = dict(nxt[i + 1])
            d[s[i]] = i
            nxt[i] = d
        return nxt

    nxt_a = build_next(a)
    nxt_b = build_next(b)

    chars = sorted(set(a))
    res = []
    i = j = 0
    L = dp[0][0]
    while L > 0:
        # Try the smallest character that can start an LCS of length L.
        for c in chars:
            ia = nxt_a[i].get(c)
            if ia is None:
                continue
            jb = nxt_b[j].get(c)
            if jb is None:
                continue
            # Earliest pair maximizes dp among all pairs matching c,
            # and dp[ia+1][jb+1] <= L-1 automatically, so equality
            # means an LCS of length L starts with this c here.
            if dp[ia + 1][jb + 1] == L - 1:
                res.append(c)
                i, j = ia + 1, jb + 1
                L -= 1
                break
        else:
            break  # defensive; cannot happen when L == dp[i][j] > 0
    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)
    if n == 0 or m == 0:
        return ""

    # dp[i][j] = length of LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row = dp[i]
        nxt = dp[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                down = nxt[j]
                right = row[j + 1]
                row[j] = down if down >= right else right

    # next[i] maps each character to the smallest index >= i where it occurs
    def build_next(s):
        tab = [None] * (len(s) + 1)
        cur = {}
        tab[len(s)] = {}
        for i in range(len(s) - 1, -1, -1):
            cur = dict(cur)
            cur[s[i]] = i
            tab[i] = cur
        return tab

    nxt_a = build_next(a)
    nxt_b = build_next(b)

    common_chars = sorted(set(a) & set(b))

    res = []
    i = j = 0
    k = dp[0][0]
    while k > 0:
        for c in common_chars:
            ia = nxt_a[i].get(c, -1)
            jb = nxt_b[j].get(c, -1)
            if ia != -1 and jb != -1 and dp[ia + 1][jb + 1] == k - 1:
                res.append(c)
                i, j = ia + 1, jb + 1
                k -= 1
                break
        else:
            break  # no valid continuation (should not happen)

    return "".join(res)

def smallest_lcs(a: str, b: str) -> str:
    n, m = len(a), len(b)

    # dp[i][j] = length of the LCS of a[i:] and b[j:]
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n - 1, -1, -1):
        row, nxt = dp[i], dp[i + 1]
        ai = a[i]
        for j in range(m - 1, -1, -1):
            if ai == b[j]:
                row[j] = nxt[j + 1] + 1
            else:
                d1, d2 = nxt[j], row[j + 1]
                row[j] = d1 if d1 >= d2 else d2

    # next occurrence tables: na[i][c] = smallest index >= i with a[index] == c
    na = [None] * (n + 1)
    na[n] = {}
    for i in range(n - 1, -1, -1):
        d = dict(na[i + 1])
        d[a[i]] = i
        na[i] = d

    nb = [None] * (m + 1)
    nb[m] = {}
    for j in range(m - 1, -1, -1):
        d = dict(nb[j + 1])
        d[b[j]] = j
        nb[j] = d

    chars = sorted(set(a) & set(b))

    res = []
    i = j = 0
    remaining = dp[0][0]
    while remaining > 0:
        for c in chars:
            ii = na[i].get(c)
            jj = nb[j].get(c)
            if ii is not None and jj is not None and dp[ii + 1][jj + 1] == remaining - 1:
                res.append(c)
                i, j = ii + 1, jj + 1
                remaining -= 1
                break
        else:
            break  # should not happen if DP is correct

    return "".join(res)

from collections import OrderedDict


def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    """Simulate an LRU cache with expiring entries.

    Returns the result of every ("get", key, time) operation, in order.
    """
    cache = OrderedDict()  # key -> (value, expiry_time or None); order = LRU -> MRU
    results = []

    def purge_expired(now: int) -> None:
        """Remove all entries whose expiry time has passed (t >= expiry)."""
        expired = [
            key
            for key, (_value, expiry) in cache.items()
            if expiry is not None and now >= expiry
        ]
        for key in expired:
            del cache[key]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            purge_expired(time)
            expiry = None if ttl is None else time + ttl
            # Whether present or new, this becomes the most recently used.
            cache[key] = (value, expiry)
            cache.move_to_end(key)
            if len(cache) > capacity:
                cache.popitem(last=False)  # evict least recently used
        elif op[0] == "get":
            _, key, time = op
            purge_expired(time)
            if key in cache:
                value, _expiry = cache[key]
                cache.move_to_end(key)  # successful get refreshes recency
                results.append(value)
            else:
                results.append(None)
        else:
            raise ValueError(f"unknown operation: {op!r}")

    return results

