                # present and not expired (purged otherwise): replace, no eviction
                del cache[key]
                cache[key] = (value, None if ttl is None else time + ttl)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)  # evict LRU
                cache[key] = (value, None if ttl is None else time + ttl)
        else:  # get
            _, key, time = op
            purge(time)
            if key in cache:
                value, exp = cache[key]
                # move to most recently used
                del cache[key]
                cache[key] = (value, exp)
                results.append(value)
            else:
                results.append(None)

    return results

