            exp = None if ttl is None else time + ttl
            if key in cache:
                del cache[key]
            elif len(cache) >= capacity:
                cache.popitem(last=False)
            cache[key] = (value, exp)
        else:
            _, key, time = op
            purge(time)
            if key in cache:
                value, exp = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(None)
    return results

from collections import OrderedDict

def simulate_cache(capacity: int, ops: list) -> list:
    if not isinstance(capacity, int) or capacity < 1:
        raise ValueError("capacity must be an integer >= 1")

    cache = OrderedDict()  # key -> (value, expiry or None); order: least -> most recent
    results = []

    def purge(now):
        expired = [k for k, (v, exp) in cache.items() if exp is not None and now >= exp]
        for k in expired:
            del cache[k]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            if ttl is not None and ttl <= 0:
                raise ValueError("ttl must be a positive integer or None")
            purge(time)
            if key in cache:
                del cache[key]
                cache[key] = (value, None if ttl is None else time + ttl)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)  # evict LRU
                cache[key] = (value, None if ttl is None else time + ttl)
        else:
            _, key, time = op
            purge(time)
            if key in cache:
                value, exp = cache[key]
                del cache[key]
                cache[key] = (value, exp)
                results.append(value)
            else:
                results.append(None)

    return results

from collections import OrderedDict

def simulate_cache(capacity, ops):
    if capacity < 1:
        raise ValueError("capacity must be >= 1")
    cache = OrderedDict()  # key -> (value, expiry or None); order: LRU first
    results = []

    def purge(now):
        # An entry is expired at every t >= expiry, so remove entries with expiry <= now.
        expired = [k for k, (_, exp) in cache.items() if exp is not None and exp <= now]
        for k in expired:
            del cache[k]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            if ttl is not None and ttl <= 0:
                raise ValueError("ttl must be a positive integer or None")
            purge(time)
            if key in cache:
                # Present and not expired (purge removed it otherwise): replace, no eviction.
                del cache[key]
            elif len(cache) >= capacity:
                # Cache full of live entries: evict least recently used.
                cache.popitem(last=False)
            cache[key] = (value, None if ttl is None else time + ttl)
        else:
            _, key, time = op
            purge(time)
            if key in cache:
                value, _ = cache[key]
                cache.move_to_end(key)  # successful get makes it most recently used
                results.append(value)
            else:
                results.append(None)
    return results

from collections import OrderedDict

def simulate_cache(capacity, ops):
    cache = OrderedDict()  # key -> (value, expiry or None); order = least to most recent

    def expired(exp, t):
        # Per spec: expired at every time t >= time + ttl.
        return exp is not None and t >= exp

    results = []
    for op in ops:
        if op[0] == "put":
            _, key, value, t, ttl = op
            exp = None if ttl is None else t + ttl
            if key in cache:
                _, old_exp = cache[key]
                if not expired(old_exp, t):
                    # Present and not expired: replace value and expiry,
                    # become most recently used, never evicts anything.
                    cache.move_to_end(key)
                    cache[key] = (value, exp)
                    continue
                else:
                    # Expired entry: treat as a brand-new insert.
                    del cache[key]
            # New key: expired entries never count toward capacity, purge them.
            for k in [k for k, (v, e) in cache.items() if expired(e, t)]:
                del cache[k]
            if len(cache) >= capacity:
                cache.popitem(last=False)  # evict least recently used
            cache[key] = (value, exp)
        else:
            _, key, t = op
            if key in cache:
                value, exp = cache[key]
                if not expired(exp, t):
                    results.append(value)
                    cache.move_to_end(key)  # successful get updates recency only
                    continue
                del cache[key]  # expired: drop it
            results.append(None)
    return results

from collections import OrderedDict


def simulate_cache(capacity: int, ops: list) -> list:
    cache = OrderedDict()  # key -> (value, expiry or None); order = recency, oldest first
    results = []

    def live_expiry(key, t):
        """Return expiry if key present and not expired at time t, else remove and return None."""
        if key not in cache:
            return None
        value, expiry = cache[key]
        if expiry is not None and t >= expiry:
            del cache[key]
            return None
        return expiry

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            expiry = None if ttl is None else time + ttl
            if key in cache:
                # Present: if expired, treat as new key (may need eviction).
                if live_expiry(key, time) is None:
                    # Evict LRU live entry if at capacity.
                    if len(cache) >= capacity:
                        cache.popitem(last=False)
                    cache[key] = (value, expiry)
                else:
                    # Replace in place: no eviction, refresh value/expiry/recency.
                    cache[key] = (value, expiry)
                    cache.move_to_end(key)
            else:
                # Count live entries (all entries in cache are live by invariant).
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, expiry)
        else:  # get
            _, key, time = op
            if live_expiry(key, time) is not None:
                value = cache[key][0]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(None)

    return results

