def simulate_cache(capacity, ops):
    cache = OrderedDict()  # key -> (value, expiry or None); order: least to most recent
    results = []

    def purge(now):
        # remove expired entries (times are non-decreasing)
        for k in list(cache.keys()):
            expiry = cache[k][1]
            if expiry is not None and now >= expiry:
                del cache[k]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            purge(time)
            expiry = time + ttl if ttl is not None else None
            if key in cache:
                cache[key] = (value, expiry)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, expiry)
        else:
            _, key, time = op
            purge(time)
            if key in cache:
                value, _ = cache[key]
                cache.move_to_end(key)
                results.append(value)
            else:
                results.append(None)

    return results

from collections import OrderedDict

def simulate_cache(capacity: int, ops: list[tuple]) -> list:
    cache = OrderedDict()  # key -> (value, expiry or None); first item = least recently used
    results = []

    def purge(now):
        # Expired entries never count toward capacity and are never returned.
        expired = [k for k, (_, exp) in cache.items()
                   if exp is not None and now >= exp]
        for k in expired:
            del cache[k]

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            purge(time)
            expiry = None if ttl is None else time + ttl
            if key in cache:
                # Replacing an existing, non-expired entry: no eviction.
                cache[key] = (value, expiry)
                cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)  # evict least recently used
                cache[key] = (value, expiry)
        else:  # get
            _, key, time = op
            purge(time)
            if key in cache:
                value, _ = cache[key]
                cache.move_to_end(key)  # successful get makes it most recently used
                results.append(value)
            else:
                results.append(None)
    return results

from collections import OrderedDict

def simulate_cache(capacity, ops):
    cache = OrderedDict()  # key -> (value, expiry or None); order = LRU (least recent first)
    results = []

    def alive(entry, t):
        return entry is not None and (entry[1] is None or t < entry[1])

    for op in ops:
        if op[0] == "put":
            _, key, value, time, ttl = op
            expiry = None if ttl is None else time + ttl
            if key in cache and alive(cache[key], time):
                cache[key] = (value, expiry)
                cache.move_to_end(key)
            else:
                # remove dead entry for this key if present
                if key in cache:
                    del cache[key]
                # count live entries
                live = [k for k, v in cache.items() if alive(v, time)]
                if len(live) >= capacity:
                    # evict least recently used live entry
                    for k in cache:
                        if alive(cache[k], time):
                            del cache[k]
                            break
                cache[key] = (value, expiry)
        else:
            _, key, time = op
            entry = cache.get(key)
            if alive(entry, time):
                results.append(entry[0])
                cache.move_to_end(key)
            else:
                results.append(None)
    return results
